INSERT INTO public.recipes (id, name, source_cuisine, cuisine, diet, is_jain, dish_type, serves, prep_time, cook_time, blurb, tip, badge, tags, ingredients, method, meal_hint, serving_unit, serving_weight_g, kcal, protein_g, carbs_g, fat_g, fibre_g, iron_mg, calcium_mg, vit_b12_mcg, sodium_mg, nutrition_estimated) VALUES
  (1, 'Mujaddara', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'main', '4', '10 min', '35 min', 'Lebanese lentils and rice topped with deeply caramelized onions.', 'Reducing the olive oil to 2–3 tbsp total would bring this closer to ~450 kcal.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Brown or green lentils — 1 cup','Basmati rice — 1 cup','Onions, thinly sliced — 3 large','Olive oil — 4 tbsp','Cumin — 1 tsp','Ground coriander — ½ tsp','Salt — to taste','Water or vegetable stock — 4 cups']::text[], ARRAY['Rinse the lentils and simmer in 2 cups water for about 15 minutes, until just tender but not mushy. Drain.','Heat 2 tbsp olive oil in a wide pan. Add the sliced onions and cook slowly over medium-low heat, stirring occasionally, until deeply caramelized — 20–25 minutes.','Remove half the caramelized onions and set aside as garnish.','Add the rice, cumin, coriander, and drained lentils to the pan with the remaining onions. Stir to coat.','Add 2 cups water or stock, season with salt, bring to a boil, then reduce heat, cover, and simmer 15–18 minutes until the rice is tender.','Fluff with a fork, top with the reserved caramelized onions, and serve warm or at room temperature.']::text[], ARRAY['dinner']::text[], 'plate', 300, 520, 18.5, 62, 14.5, 9, 6.8, 85, 0, 480, false),
  (2, 'Ratatouille', 'Western European', 'european', 'vegan', false, 'side', '4', '20 min', '40 min', 'A rustic French Provençal vegetable stew.', 'Already a fairly light dish — no major adjustment needed.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Eggplant, diced — 1 medium','Zucchini, diced — 2 medium','Bell peppers, diced — 2 (red & yellow)','Tomatoes, chopped — 4 medium (or 1 can crushed)','Onion, chopped — 1 large','Garlic, minced — 3 cloves','Olive oil — 3 tbsp','Dried herbes de Provence — 1 tsp','Salt & pepper — to taste']::text[], ARRAY['Heat olive oil in a large pot. Sauté the onion and garlic until softened, about 4 minutes.','Add the eggplant and cook 5–6 minutes until it starts to soften, stirring occasionally.','Add the zucchini and bell peppers; cook another 5 minutes.','Stir in the chopped tomatoes and herbs, and season with salt and pepper.','Cover and simmer on low heat 25–30 minutes, stirring occasionally, until the vegetables are tender and the stew has thickened.','Adjust seasoning and serve warm, with crusty bread or over rice.']::text[], ARRAY['lunch']::text[], 'bowl', 220, 190, 3.2, 18.5, 10.8, 4.2, 1.1, 42, 0, 280, false),
  (3, 'Chiles Rellenos', 'Mexican', 'latin_american', 'egg', false, 'main', '4', '25 min', '20 min', 'Poblano peppers stuffed with melting cheese, battered and fried.', 'Baking instead of shallow-frying meaningfully lowers the fat content — the oil absorption during frying is the biggest lever here.', 'Traditional', ARRAY['Nut-Free','Jain-Friendly','High-Protein','Low-Carb']::text[], ARRAY['Poblano peppers — 4 large','Monterey Jack cheese, cut into batons — 200 g','All-purpose flour — ½ cup','Eggs, separated — 3','Vegetable oil — for shallow frying','Salt — to taste','Simple tomato sauce — 1 cup']::text[], ARRAY['Char the poblano peppers over a flame or under a broiler until blackened all over. Steam in a covered bowl 10 minutes, then peel.','Make a slit in each pepper and remove the seeds, keeping the pepper whole. Stuff each with cheese batons.','Beat the egg whites to soft peaks, then gently fold in the yolks to make a light batter.','Dredge the stuffed peppers in flour, then dip in the egg batter to coat.','Shallow-fry in hot oil, turning gently, until golden on all sides — about 3–4 minutes total.','Drain on paper towels and serve warm with tomato sauce spooned over.']::text[], ARRAY['lunch']::text[], 'plate', 250, 420, 18.5, 22, 20.5, 2.8, 1.9, 385, 0.85, 580, false),
  (4, 'Gado-Gado', 'Southeast Asian', 'asian', 'vegan', false, 'main', '4', '20 min', '15 min', 'Indonesian vegetable salad with a rich peanut sauce.', 'Using half the peanut sauce and topping up with a squeeze of extra lime keeps the dish bright while cutting calories.', 'Traditional', ARRAY['Gluten-Free']::text[], ARRAY['Mixed vegetables (green beans, cabbage, bean sprouts, carrots), blanched — 4 cups','Boiled potatoes, sliced — 2 medium','Firm tofu, cubed and fried — 200 g','Cucumber, sliced — 1','Unsweetened peanut butter — ½ cup','Kecap manis, or soy sauce + a little jaggery — 2 tbsp','Garlic, minced — 1 clove','Lime juice — 1 tbsp','Red chili, chopped (optional) — 1','Warm water — to thin the sauce']::text[], ARRAY['Blanch the mixed vegetables until just tender-crisp. Drain and cool.','Whisk the peanut butter, kecap manis, garlic, lime juice, and chili together with a little warm water into a smooth, pourable sauce.','Arrange the blanched vegetables, boiled potato, fried tofu, and cucumber on a plate.','Drizzle generously with the peanut sauce just before serving.','Serve at room temperature, with extra sauce on the side.']::text[], ARRAY['lunch']::text[], 'plate', 330, 400, 16.5, 32, 18.5, 7.5, 3.2, 185, 0.15, 385, false),
  (5, 'Misir Wat', 'East African', 'african', 'vegan', false, 'dal', '4', '10 min', '30 min', 'A rich, spiced Ethiopian red lentil stew.', 'Reducing the oil to 2 tbsp trims calories with little change to texture, since the lentils give the dish its body.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Red lentils — 1½ cups','Onion, finely chopped — 1 large','Garlic, minced — 3 cloves','Ginger, grated — 1 tbsp','Berbere spice blend — 2 tbsp','Tomato paste — 2 tbsp','Vegetable oil — 3 tbsp','Water — 3 cups','Salt — to taste']::text[], ARRAY['Heat the oil in a pot and sauté the onion until soft and golden, about 8 minutes.','Add the garlic and ginger; cook 1 minute until fragrant.','Stir in the berbere spice and tomato paste; cook 1–2 minutes to deepen the flavor.','Add the rinsed red lentils and water. Bring to a boil.','Reduce heat and simmer, stirring occasionally, 20–25 minutes until the lentils break down into a thick stew.','Season with salt and serve with injera or flatbread.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 365, 13.2, 42.8, 11.5, 7.2, 6.8, 48, 0, 385, false),
  (6, 'Miso Soup (Vegetarian Dashi)', 'Japanese', 'asian', 'vegan', false, 'soup', '4', '25 min', '10 min', 'A genuinely vegetarian miso soup, made with kombu dashi instead of the traditional bonito stock.', 'Using silken tofu instead of firm brings this down to roughly 85 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Kombu (dried kelp) — 10 cm piece','Water — 4 cups','White or yellow miso paste — 4 tbsp','Firm tofu, cubed — 200 g','Dried wakame, rehydrated — 2 tbsp','Spring onions, sliced — 2']::text[], ARRAY['Soak the kombu in the water for 20–30 minutes (or overnight, chilled) to make a vegetarian dashi.','Heat gently over low heat, removing the kombu just before it boils — boiling turns the stock bitter.','Add the rehydrated wakame and tofu cubes; keep at a gentle simmer.','Ladle a little hot dashi into a bowl, whisk in the miso paste until smooth, then stir it back into the pot. Don''t let it boil after this.','Warm through gently without boiling.','Ladle into bowls, top with spring onions, and serve immediately.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 110, 8.2, 7.1, 3.5, 1.2, 2.1, 145, 0.4, 580, false),
  (7, 'Coconut Vegetable Curry (Thai-Style)', 'Southeast Asian', 'asian', 'vegan', false, 'curry', '4', '15 min', '20 min', 'A base Thai green curry recipe, with notes for red and massaman variations.', 'Swapping half the coconut milk for vegetable stock cuts roughly 100 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Coconut milk — 2 cups (400 ml can)','Thai green curry paste (vegetarian) — 3 tbsp','Mixed vegetables (eggplant, bell pepper, green beans, bamboo shoots) — 3 cups','Firm tofu, cubed — 200 g','Vegetable stock or water — 1 cup','Palm sugar or brown sugar — 1 tbsp','Soy sauce — 2 tbsp','Thai basil leaves — a handful','Kaffir lime leaves — 2–3 (optional)']::text[], ARRAY['Scoop the thick cream from the top of the coconut milk into a pot and heat until it starts to split and release its oil.','Add the curry paste and fry 2–3 minutes until fragrant.','Add the remaining coconut milk and stock; stir to combine.','Add the firmer vegetables first and simmer 5 minutes, then the tofu and remaining vegetables for another 5–7 minutes.','Stir in soy sauce, sugar, and kaffir lime leaves; taste and adjust.','Finish with Thai basil just before serving, over steamed jasmine rice.','For red curry: swap in red curry paste, same method. For massaman: swap to massaman paste, add 2 cubed potatoes and 3 tbsp roasted peanuts, plus a cinnamon stick and 2 cardamom pods, simmering 20–25 minutes total.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 350, 12.5, 18.3, 19.8, 3.2, 2.1, 185, 0.3, 520, false),
  (8, 'Ta''ameya', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'snack', '4', '20 min + overnight soak', '15 min', 'Egyptian fava bean falafel, made from raw soaked beans rather than cooked chickpeas.', 'Baking at 200°C (400°F) for about 20 minutes instead of deep-frying cuts roughly 100 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Dried split fava beans, soaked overnight — 1½ cups','Onion, roughly chopped — 1 small','Garlic cloves — 3','Fresh coriander, packed — 1 cup','Fresh parsley, packed — 1 cup','Fresh dill (optional) — 2 tbsp','Ground coriander — 1 tsp','Ground cumin — 1 tsp','Baking soda — ½ tsp','Salt — to taste','Sesame seeds — for coating','Vegetable oil — for frying']::text[], ARRAY['Drain the soaked fava beans well — they''re used raw, which is traditional for ta''ameya.','Blend the beans, onion, garlic, coriander, parsley, and dill until finely ground but not pureed.','Mix in the ground coriander, cumin, and salt; rest in the fridge 30 minutes.','Just before frying, mix in the baking soda.','Shape into patties, pressing sesame seeds onto both sides.','Deep-fry a few at a time until deep golden and crisp, about 3–4 minutes.','Drain and serve hot in flatbread with tahini sauce, tomatoes, and pickles.']::text[], ARRAY['snack']::text[], 'serving', 150, 425, 14.2, 38.5, 18.3, 8.6, 4.8, 95, 0, 380, false),
  (9, 'Vegetable Tagine', 'North African', 'middle_eastern', 'vegan', false, 'curry', '4', '20 min', '45 min', 'A warmly spiced Moroccan stew of vegetables, chickpeas, and dried apricots.', 'Leaving out the toasted almond garnish saves about 20 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free']::text[], ARRAY['Olive oil — 3 tbsp','Onion, sliced — 1 large','Garlic, minced — 3 cloves','Carrots, sliced — 2 medium','Zucchini, sliced — 2 medium','Bell pepper, sliced — 1','Chickpeas, cooked — 1½ cups','Dried apricots, halved — ½ cup','Diced tomatoes — 2 cups','Vegetable stock — 1½ cups','Ground cumin — 1 tsp','Ground cinnamon — ½ tsp','Ground ginger — ½ tsp','Paprika — 1 tsp','Salt & pepper — to taste','Fresh coriander — garnish','Toasted almonds — garnish (optional)']::text[], ARRAY['Heat the olive oil; sauté the onion until soft, about 5 minutes.','Add garlic and spices; cook 1 minute until fragrant.','Add the carrots and cook 3–4 minutes.','Stir in the tomatoes, stock, and apricots; bring to a simmer.','Cover and cook gently 20 minutes, until the carrots begin to soften.','Add the zucchini, bell pepper, and chickpeas; simmer, covered, another 15–20 minutes until tender and thickened.','Season, garnish with coriander and almonds, and serve with couscous or flatbread.']::text[], ARRAY['dinner']::text[], 'bowl', 300, 330, 12.5, 38.2, 12.8, 8.6, 3.2, 82, 0, 485, false),
  (10, 'Moqueca', 'South American', 'latin_american', 'vegan', false, 'curry', '4', '15 min', '30 min', 'A Brazilian coconut stew, vegetarian version with hearts of palm and tofu in place of fish.', 'Using ''lite'' coconut milk instead of full-fat cuts roughly 90 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Palm oil (dendê), or olive oil + a pinch of paprika — 2 tbsp','Onion, sliced — 1 large','Garlic, minced — 3 cloves','Bell peppers (red & yellow), sliced — 2','Tomatoes, chopped — 3 medium','Coconut milk — 1½ cups (300 ml)','Hearts of palm, sliced — 1 cup','Firm tofu, cubed — 200 g','Fresh coriander — ½ cup','Lime juice — 2 tbsp','Salt & pepper — to taste']::text[], ARRAY['Heat the oil; sauté the onion and garlic until soft, about 5 minutes.','Add the bell peppers and cook another 3–4 minutes.','Stir in the tomatoes and cook until they break down, about 5 minutes.','Add the coconut milk and bring to a gentle simmer.','Add the hearts of palm and tofu; simmer 10–12 minutes.','Stir in lime juice, season, finish with coriander, and serve with white rice.']::text[], ARRAY['dinner']::text[], 'bowl', 280, 370, 12.5, 18.2, 20.8, 3.1, 2.8, 145, 0, 385, false),
  (11, 'Paal Payasam', 'South Indian', 'south_indian', 'veg', true, 'dessert', '4', '5 min', '20 min', 'A South Indian rice and vermicelli kheer, gently spiced with cardamom.', 'Using low-fat milk and reducing the sugar to ¼ cup brings this down to roughly 300 kcal/serving.', 'Traditional', ARRAY['Jain-Friendly']::text[], ARRAY['Milk — 4 cups','Vermicelli (semiya) — ½ cup','Sugar — ⅓ cup','Ghee — 2 tbsp','Cashews — 2 tbsp','Raisins — 1 tbsp','Cardamom powder — ¼ tsp']::text[], ARRAY['Heat the ghee; roast the cashews and raisins until golden and plump. Set aside.','Lightly roast the vermicelli in a little ghee until fragrant, about 2 minutes.','Bring the milk to a gentle boil in a heavy-bottomed pot, then reduce to a simmer.','Add the roasted vermicelli; cook, stirring frequently, until soft, 8–10 minutes.','Add the sugar and cardamom powder; simmer another 5 minutes.','Stir in the roasted cashews and raisins. Serve warm or chilled.']::text[], ARRAY['snack']::text[], 'bowl', 200, 360, 9.2, 42.5, 14.8, 0.6, 0.8, 285, 0.42, 125, false),
  (12, 'Mysore Pak', 'South Indian', 'south_indian', 'veg', true, 'dessert', '8', '10 min', '20 min', 'A rich, ghee-heavy South Indian gram flour sweet — genuinely indulgent by tradition.', 'Cutting the ghee to 1 cup and portioning into 12 pieces instead of 8 brings servings down to roughly 270 kcal.', 'Traditional', ARRAY['Nut-Free','Jain-Friendly']::text[], ARRAY['Besan (gram flour) — 1 cup','Ghee — 1½ cups','Sugar — 1 cup','Water — ½ cup']::text[], ARRAY['Sieve the besan to remove lumps.','Combine sugar and water; boil to a one-string syrup consistency.','Melt the ghee separately and keep it warm.','Gradually whisk the besan into the syrup, stirring continuously.','Add the warm ghee a ladle at a time, stirring continuously, until the mixture thickens and turns porous.','Pour into a greased tray, spreading evenly. Cut into squares while still warm, then cool completely.']::text[], ARRAY['snack']::text[], 'piece', 87, 485, 8.2, 48.5, 28.3, 2.1, 2.8, 95, 0.15, 18, false),
  (13, 'Horchata', 'Mexican', 'latin_american', 'veg', true, 'drink', '4', '4 hrs soak + 10 min', 'none', 'A chilled Mexican rice and cinnamon beverage.', 'Reducing the sugar to ¼ cup and skipping the added milk brings this to roughly 120 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['White rice — ½ cup','Water — 4 cups, divided','Cinnamon stick — 1','Sugar — ⅓ cup','Vanilla extract — ½ tsp','Milk or plant milk (optional) — ½ cup']::text[], ARRAY['Combine the rice, 2 cups water, and cinnamon stick in a blender; blend briefly, then soak at least 4 hours (or overnight, chilled).','Blend the soaked mixture again until smooth.','Strain through a fine sieve or cheesecloth, pressing to extract as much liquid as possible.','Stir in the remaining water, sugar, vanilla, and milk if using.','Chill well and serve over ice.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 170, 1.2, 38.5, 0.8, 0.3, 0.4, 45, 0.05, 12, false),
  (14, 'Pad Thai (Vegetarian)', 'Southeast Asian', 'asian', 'egg', false, 'main', '4', '30 min', '15 min', 'The classic Thai stir-fried noodle dish, made vegetarian.', 'Omitting the eggs and reducing the oil to 2 tbsp brings this to roughly 420 kcal/serving.', 'Traditional', NULL, ARRAY['Flat rice noodles — 200 g','Firm tofu, cubed — 200 g','Bean sprouts — 1½ cups','Carrot, julienned — 1 medium','Spring onions, chopped — 3','Garlic, minced — 3 cloves','Eggs (optional) — 2','Peanuts, crushed — ¼ cup','Vegetable oil — 3 tbsp','Tamarind paste — 2 tbsp','Soy sauce — 3 tbsp','Palm sugar or brown sugar — 2 tbsp','Lime wedges — to serve']::text[], ARRAY['Soak the noodles in warm water until pliable but still firm, 20–30 minutes; drain.','Whisk the tamarind paste, soy sauce, and sugar together for the sauce.','Heat the oil; fry the tofu until golden, then push to one side.','Add garlic, and scramble the eggs alongside if using.','Add the noodles and sauce; toss continuously until coated and just tender, 2–3 minutes.','Add the bean sprouts, carrot, and half the spring onions; toss another minute.','Top with peanuts and remaining spring onions, and serve with lime wedges.']::text[], ARRAY['dinner']::text[], 'plate', 330, 500, 16.5, 58.2, 17.8, 3.2, 3.1, 142, 0.2, 1045, false),
  (15, 'Hummus & Za''atar Pita Platter', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'snack', '4', '15 min', 'none', 'A shareable Middle Eastern hummus platter with warm za''atar pita.', 'Serving 2 pitas instead of 4 as a lighter snack portion brings this to roughly 380 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free','High-Protein']::text[], ARRAY['Chickpeas, cooked — 2 cups','Tahini — ¼ cup','Lemon juice — 3 tbsp','Garlic — 2 cloves','Olive oil — 5 tbsp total','Cumin — ½ tsp','Salt — to taste','Pita bread — 4 pieces','Za''atar spice blend — 2 tbsp']::text[], ARRAY['Blend the chickpeas, tahini, lemon juice, garlic, cumin, and salt until smooth, adding water as needed.','With the processor running, drizzle in 3 tbsp olive oil until light and creamy.','Warm the pita, brush lightly with the remaining olive oil, and sprinkle generously with za''atar.','Cut the pita into wedges.','Plate the hummus, drizzle with more olive oil, and serve with the pita wedges.']::text[], ARRAY['snack']::text[], 'plate', 250, 560, 14.2, 58.5, 22.8, 9.5, 4.2, 142, 0, 485, false),
  (16, 'Vegetable Hakka Chow Mein', 'Chinese', 'asian', 'vegan', false, 'main', '4', '10 min', '15 min', 'A quick, high-heat stir-fried noodle dish loaded with crisp vegetables.', 'This dish is naturally light on protein — adding 150g cubed, pan-fried tofu makes it more filling for about +110 kcal and +11g protein.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Hakka noodles (egg-free) — 250 g','Cabbage, shredded — 2 cups','Carrot, julienned — 1','Bell pepper, julienned — 1','Spring onions, chopped — 3','Garlic, minced — 3 cloves','Ginger, minced — 1 tbsp','Soy sauce — 3 tbsp','Vinegar — 1 tbsp','Vegetable oil — 3 tbsp','Black pepper — to taste']::text[], ARRAY['Cook the noodles until just al dente; drain, toss with a little oil, and set aside.','Heat the oil; stir-fry the garlic and ginger briefly until fragrant.','Add the cabbage, carrot, and bell pepper; stir-fry on high heat 3–4 minutes, keeping them crisp.','Add the noodles, soy sauce, vinegar, and pepper; toss together on high heat 2–3 minutes.','Stir in most of the spring onions, garnish with the rest, and serve hot.']::text[], ARRAY['dinner']::text[], 'plate', 250, 260, 8.2, 32.5, 9.8, 2.1, 1.8, 45, 0, 580, false),
  (17, 'Brigadeiro', 'South American', 'latin_american', 'veg', true, 'dessert', '8', '15 min + 1 hr cooling', '12 min', 'Brazilian chocolate fudge truffles, rolled in sprinkles.', 'Treating this as a 1–2 truffle portion rather than 2–3 brings it to roughly 100–130 kcal.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Sweetened condensed milk — 1 can (395 g)','Unsweetened cocoa powder — 4 tbsp','Butter — 1 tbsp','Chocolate sprinkles — for coating']::text[], ARRAY['Combine the condensed milk, cocoa powder, and butter in a saucepan.','Cook over medium-low heat, stirring constantly, until it thickens and pulls away from the pan sides, about 10–12 minutes.','Cool completely on a greased plate, about 1 hour.','Grease your hands lightly and roll into small balls.','Roll each ball in chocolate sprinkles. Serve in small paper cups, at room temperature.']::text[], ARRAY['snack']::text[], 'piece', 30, 200, 3.2, 28.5, 7.8, 0.8, 0.9, 95, 0.18, 85, false),
  (18, 'Onigiri', 'Japanese', 'asian', 'vegan', true, 'main', '4', '20 min', '20 min (rice)', 'Japanese filled rice balls, wrapped in nori.', 'Already a light, low-fat snack — for a meal-sized portion, 3–4 onigiri brings it closer to 350–400 kcal.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Japanese short-grain rice, cooked & lightly seasoned — 3 cups','Filling of choice (umeboshi, seasoned mushroom, or edamame + sesame) — ½ cup','Nori sheets, cut into strips — 4','Salt — for shaping','Rice vinegar (optional) — 1 tbsp']::text[], ARRAY['Cook the rice and season lightly with rice vinegar if using; cool enough to handle.','Wet your hands and rub a little salt onto your palms.','Take a handful of rice, flatten slightly, and place a spoonful of filling in the center.','Fold the rice around the filling and shape into a triangle or ball, pressing firmly.','Wrap a strip of nori around the base of each onigiri.','Repeat with the remaining rice and filling. Serve at room temperature or slightly warm.']::text[], ARRAY['snack']::text[], 'piece', 120, 220, 4.2, 47.8, 0.8, 0.6, 0.4, 12, 0, 380, false),
  (19, 'Harira', 'North African', 'middle_eastern', 'vegan', false, 'soup', '4', '15 min', '40 min', 'A warmly spiced Moroccan lentil and vegetable soup.', 'Reducing the olive oil to 1 tbsp trims about 40 kcal/serving with little impact on flavor.', 'Traditional', ARRAY['Vegan','Nut-Free','High-Protein']::text[], ARRAY['Brown or green lentils — 1 cup','Chickpeas, cooked — 1 cup','Onion, chopped — 1','Celery, chopped — 2 stalks','Tomatoes, chopped — 3 medium','Tomato paste — 2 tbsp','Ground ginger — 1 tsp','Ground cinnamon — ½ tsp','Turmeric — ½ tsp','Fresh coriander & parsley — ½ cup combined','Vegetable stock — 6 cups','Olive oil — 2 tbsp','Flour (optional, to thicken) — 2 tbsp','Lemon wedges — to serve']::text[], ARRAY['Heat the olive oil; sauté the onion and celery until softened, about 5 minutes.','Add the ginger, cinnamon, and turmeric; cook 1 minute until fragrant.','Stir in the tomatoes and tomato paste; cook 3–4 minutes.','Add the lentils, chickpeas, and stock; bring to a boil.','Reduce heat and simmer, partially covered, 30–35 minutes until the lentils are tender.','For a thicker soup, whisk the flour with water and stir in, simmering 5 more minutes.','Stir in the fresh herbs just before serving, with lemon wedges.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 360, 18.5, 42, 8.5, 10.2, 5.8, 95, 0, 520, false),
  (20, 'Shiro Wat', 'East African', 'african', 'vegan', false, 'curry', '4', '10 min', '25 min', 'A smooth, spiced Ethiopian chickpea flour stew.', 'Reducing the oil to 2 tbsp cuts roughly 30 kcal/serving — the shiro itself gives the dish its body.', 'Traditional', ARRAY['Vegan','Nut-Free','Low-Carb']::text[], ARRAY['Shiro powder (or chickpea flour + 1 tbsp berbere) — 1 cup','Onion, finely chopped — 1 large','Garlic, minced — 3 cloves','Ginger, grated — 1 tbsp','Tomato paste — 2 tbsp','Berbere spice blend — 1 tbsp','Vegetable oil — 3 tbsp','Water — 3 cups','Salt — to taste']::text[], ARRAY['Heat the oil; sauté the onion until soft and golden, about 8 minutes.','Add garlic and ginger; cook 1 minute.','Stir in the tomato paste and berbere spice; cook 1–2 minutes.','Whisk the shiro powder into the water separately until smooth and lump-free.','Gradually pour into the pot, whisking constantly to avoid lumps.','Simmer gently, stirring frequently, 15–20 minutes until thickened to a smooth, porridge-like consistency.','Season with salt and serve with injera or flatbread.']::text[], ARRAY['dinner']::text[], 'bowl', 220, 230, 8.2, 18.5, 9.8, 3.2, 4.5, 65, 0, 420, false),
  (21, 'Pesarattu', 'South Indian', 'south_indian', 'vegan', false, 'main', '4', '4 hrs soak + 10 min', '20 min', 'A South Indian moong dal dosa, crisped with onion.', 'Using 1 tsp oil per dosa on a well-seasoned pan instead of a generous drizzle saves about 60 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Whole green moong dal, soaked 4 hrs — 1½ cups','Rice (soaked with dal) — ¼ cup','Ginger — 1 inch','Green chilies — 2','Cumin seeds — 1 tsp','Salt — to taste','Oil — for cooking','Onion, finely chopped (topping) — ½ cup']::text[], ARRAY['Drain the soaked moong dal and rice; blend with ginger, chilies, cumin, and a little water into a smooth, thick batter. Season with salt.','Heat a griddle, pour a ladle of batter, and spread into a thin circle.','Sprinkle chopped onion over the top and press gently; drizzle a little oil around the edges.','Cook until the base is golden and crisp, then flip briefly to finish.','Serve hot with coconut or ginger chutney.']::text[], ARRAY['breakfast','dinner']::text[], 'serving', 200, 400, 12.5, 48, 6.5, 4.2, 2.8, 85, 0, 320, false),
  (22, 'Rasam', 'South Indian', 'south_indian', 'veg', false, 'dal', '4', '10 min', '15 min', 'A light, tangy South Indian tamarind and lentil soup.', 'Already very light; pair with a protein-rich side (like the Vada) for a balanced meal.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Tamarind pulp — 2 tbsp','Tomato, chopped — 2 medium','Toor dal, cooked & mashed — ¼ cup','Rasam powder — 2 tsp','Turmeric — ¼ tsp','Mustard seeds — ½ tsp','Cumin seeds — ½ tsp','Curry leaves — a sprig','Garlic, crushed — 2 cloves','Ghee — 1 tbsp','Water — 3 cups','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Soak tamarind in warm water, extract the pulp, and discard the fibers.','Combine the tamarind water, tomato, mashed dal, rasam powder, turmeric, and salt with the remaining water; simmer 10–12 minutes.','In a small pan, heat the ghee; add mustard seeds, cumin, curry leaves, and garlic, and let them sputter.','Pour this tempering over the simmering rasam.','Simmer 2–3 more minutes, garnish with coriander, and serve hot.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 150, 80, 2.8, 10.2, 3.5, 2.1, 1.8, 45, 0.05, 380, false),
  (23, 'Vada (Medu Vada)', 'South Indian', 'south_indian', 'vegan', true, 'snack', '4', '4 hrs soak + 15 min', '15 min', 'Crisp, fluffy South Indian lentil fritters.', 'Baking or air-frying instead of deep-frying cuts roughly 150 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly','High-Protein']::text[], ARRAY['Urad dal, soaked 4 hrs — 1½ cups','Green chilies, chopped — 2','Ginger, grated — 1 tsp','Curry leaves, chopped — a sprig','Black pepper — ½ tsp','Salt — to taste','Oil — for deep frying']::text[], ARRAY['Drain the soaked urad dal and grind to a thick, fluffy batter with minimal water.','Whisk the batter vigorously by hand for a few minutes to incorporate air.','Fold in the chilies, ginger, curry leaves, and pepper; season with salt.','Wet your hands and shape portions into donut-like rings.','Deep-fry until golden brown and crisp, turning occasionally.','Drain and serve hot with coconut chutney and sambar.']::text[], ARRAY['snack','dinner','breakfast']::text[], 'piece', 50, 430, 8.2, 32.5, 22.8, 1.9, 2.1, 85, 0, 380, false),
  (24, 'Tom Yum Soup (Vegetarian)', 'Southeast Asian', 'asian', 'vegan', false, 'soup', '4', '10 min', '15 min', 'A hot and sour Thai soup, fragrant with lemongrass and lime leaf.', 'Add rice noodles for a more filling meal (+~150 kcal/serving) if serving as a main rather than a starter.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Vegetable stock — 4 cups','Lemongrass, bruised — 2 stalks','Galangal or ginger, sliced — 4–5 slices','Kaffir lime leaves — 4','Mushrooms, sliced — 2 cups','Tomatoes, quartered — 2','Firm tofu, cubed — 200 g','Vegetarian chili paste (nam prik pao) — 2 tbsp','Lime juice — 3 tbsp','Soy sauce — 2 tbsp','Fresh red chilies, sliced — 2','Fresh coriander — garnish']::text[], ARRAY['Bring the stock to a boil with the lemongrass, galangal, and lime leaves; simmer 5 minutes to infuse.','Add the mushrooms and tofu; simmer 5 minutes.','Stir in the chili paste and soy sauce.','Add the tomatoes and simmer 2–3 minutes.','Remove from heat and stir in the lime juice off the heat, to keep it bright.','Garnish with chilies and coriander; serve hot.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 110, 8.5, 7.2, 3.8, 1.5, 2.1, 145, 0.3, 485, false),
  (25, 'Fresh Vegetable Spring Rolls', 'Southeast Asian', 'asian', 'vegan', false, 'snack', '4', '25 min', 'none', 'Vietnamese-style fresh rice paper rolls with a peanut dipping sauce.', 'Dip lightly rather than pouring the full sauce portion over — using half saves about 40 kcal/serving.', 'Traditional', ARRAY['Jain-Friendly']::text[], ARRAY['Rice paper wrappers — 8','Rice vermicelli, cooked — 1 cup','Lettuce leaves — 8','Carrot, julienned — 1','Cucumber, julienned — 1','Fresh mint & basil — a handful','Firm tofu, pan-fried and sliced — 200 g','Peanut dipping sauce (peanut butter, soy sauce, lime, water) — ½ cup']::text[], ARRAY['Arrange all filling ingredients within reach.','Dip a rice paper wrapper in warm water a few seconds until pliable.','Lay it flat; arrange lettuce, vermicelli, tofu, carrot, cucumber, and herbs in the lower third.','Fold the sides in and roll tightly from the bottom.','Repeat with the remaining wrappers and filling.','Whisk the dipping sauce ingredients together and serve alongside.']::text[], ARRAY['snack']::text[], 'serving', 180, 250, 10.5, 28, 7.5, 3.2, 2.1, 145, 0.2, 420, false),
  (26, 'Nasi Goreng (Vegetarian)', 'Southeast Asian', 'asian', 'egg', false, 'main', '4', '10 min', '15 min', 'Indonesian fried rice, topped with a fried egg.', 'Omitting the fried egg topping brings this to roughly 440 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Cooked, day-old rice — 4 cups','Firm tofu, cubed — 200 g','Shallots, sliced — 3','Garlic, minced — 3 cloves','Red chili, sliced — 2','Kecap manis — 3 tbsp','Soy sauce — 1 tbsp','Vegetable oil — 3 tbsp','Eggs, fried (optional topping) — 4','Cucumber & tomato — garnish','Fried shallots — garnish']::text[], ARRAY['Heat oil in a wok; fry the tofu until golden, then set aside.','Sauté shallots, garlic, and chili until fragrant.','Add the cold rice, breaking up clumps; stir-fry on high heat 3–4 minutes.','Add kecap manis and soy sauce; toss until evenly coated.','Return the tofu to the wok and toss through.','Fry the eggs separately if using, and top each serving with one.','Garnish with cucumber, tomato, and fried shallots.']::text[], ARRAY['dinner']::text[], 'plate', 330, 520, 18.5, 62, 18.5, 2.2, 3.8, 185, 0.35, 685, false),
  (27, 'Baba Ganoush', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'snack', '4', '10 min', '20 min', 'A smoky, creamy Middle Eastern eggplant dip.', 'Reducing the finishing olive oil drizzle to 1 tbsp saves about 30 kcal/serving.', 'Traditional', ARRAY['Nut-Free','Low-Carb']::text[], ARRAY['Eggplants, large — 2','Tahini — 3 tbsp','Lemon juice — 2 tbsp','Garlic, minced — 1 clove','Olive oil — 2 tbsp (plus more to serve)','Salt — to taste','Fresh parsley — garnish','Pita bread — to serve']::text[], ARRAY['Char the eggplants over a flame or under a broiler until blackened and soft inside, 15–20 minutes.','Cool slightly, peel off the skin, and drain excess liquid.','Mash or blend the flesh with tahini, lemon juice, garlic, and olive oil — a little texture is traditional.','Season with salt.','Drizzle with more olive oil and garnish with parsley. Serve with warm pita.']::text[], ARRAY['snack']::text[], 'bowl', 120, 165, 4.2, 12.8, 10.5, 2.4, 0.8, 42, 0, 185, false),
  (28, 'Fattoush Salad', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'salad', '4', '15 min', '5 min', 'A bright Levantine salad topped with crisp toasted pita.', 'Reducing the olive oil to 2 tbsp and baking the pita instead of frying saves about 70 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Romaine lettuce, chopped — 4 cups','Tomatoes, diced — 2','Cucumber, diced — 1','Radishes, sliced — 4','Red onion, thinly sliced — ½','Fresh mint & parsley — ½ cup combined','Pita bread, toasted/fried crisp — 2 pieces','Sumac — 1 tsp','Olive oil — 4 tbsp','Lemon juice — 2 tbsp','Pomegranate molasses (optional) — 1 tsp','Salt — to taste']::text[], ARRAY['Toast or lightly fry the pita until crisp; break into bite-sized pieces.','Combine the lettuce, tomatoes, cucumber, radishes, onion, mint, and parsley in a large bowl.','Whisk the olive oil, lemon juice, pomegranate molasses, sumac, and salt for the dressing.','Toss the salad with the dressing just before serving.','Add the crisp pita last so it stays crunchy.']::text[], ARRAY['lunch']::text[], 'bowl', 180, 235, 7.2, 24.5, 11.8, 4.2, 2.1, 85, 0, 320, false),
  (29, 'Kung Pao Tofu', 'Chinese', 'asian', 'vegan', false, 'main', '4', '15 min', '15 min', 'A spicy, peanut-studded stir-fry, vegetarian take on the Sichuan classic.', 'Cutting the peanuts to ⅓ cup and the oil to 2 tbsp brings this to roughly 300 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','High-Protein','Low-Carb']::text[], ARRAY['Firm tofu, cubed — 400 g','Bell pepper, diced — 1','Zucchini, diced — 1','Dried red chilies — 6–8','Garlic, minced — 3 cloves','Ginger, minced — 1 tbsp','Roasted peanuts — ½ cup','Spring onions, chopped — 3','Soy sauce — 3 tbsp','Rice vinegar — 2 tbsp','Sugar — 1 tbsp','Cornstarch — 1 tbsp (mixed with water)','Vegetable oil — 3 tbsp']::text[], ARRAY['Pan-fry the tofu in a little oil until golden on most sides; set aside.','Heat the remaining oil; add dried chilies, garlic, and ginger, stir-frying briefly.','Add the bell pepper and zucchini; stir-fry 3–4 minutes.','Whisk together soy sauce, rice vinegar, sugar, and the cornstarch slurry.','Return the tofu to the pan, pour in the sauce, and toss until thickened, about 2 minutes.','Stir in the peanuts and most of the spring onions; garnish with the rest and serve over rice.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 375, 18.5, 22.3, 16.2, 3.1, 3.4, 185, 0, 720, false),
  (30, 'Vegetable Fried Rice', 'Chinese', 'asian', 'egg', false, 'main', '4', '10 min', '15 min', 'A classic wok-fried rice, loaded with mixed vegetables.', 'Omitting the eggs and using just 2 tbsp total oil brings this to roughly 350 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Cooked, day-old rice — 4 cups','Mixed vegetables (carrot, peas, corn, beans) — 1½ cups','Spring onions, chopped — 3','Garlic, minced — 3 cloves','Eggs (optional) — 2','Soy sauce — 3 tbsp','Sesame oil — 1 tbsp','Vegetable oil — 2 tbsp','White pepper — to taste']::text[], ARRAY['Heat vegetable oil in a wok; add garlic and stir-fry briefly.','Add the mixed vegetables and stir-fry 3–4 minutes.','If using eggs, push the vegetables aside, scramble the eggs, then mix together.','Add the cold rice, breaking up clumps; stir-fry on high heat 3–4 minutes.','Add soy sauce, sesame oil, and white pepper; toss to coat.','Stir in most of the spring onions, garnish with the rest, and serve hot.']::text[], ARRAY['dinner']::text[], 'plate', 300, 410, 12.5, 52, 13.5, 3.2, 2.1, 48, 0.3, 720, false),
  (31, 'Japanese Vegetable Tempura', 'Japanese', 'asian', 'veg', false, 'snack', '4', '15 min', '15 min', 'Light, crisp battered and fried vegetables, served with a soy dipping sauce.', 'Draining on a rack rather than paper towels (which reabsorb oil) and skipping the egg yolk saves about 40 kcal/serving.', 'Traditional', ARRAY['Nut-Free','Jain-Friendly']::text[], ARRAY['Mixed vegetables (sweet potato, eggplant, bell pepper, green beans), sliced — 4 cups','Tempura flour (or all-purpose flour) — 1 cup','Ice-cold sparkling water — 1 cup','Egg yolk (optional) — 1','Vegetable oil — for deep frying','Tentsuyu dipping sauce (soy sauce, mirin, vegetarian dashi) — to serve']::text[], ARRAY['Prepare the dipping sauce by combining soy sauce, mirin, and vegetarian dashi.','Slice vegetables thin and even for quick, even cooking.','Just before frying, whisk the flour, ice-cold water, and egg yolk lightly — a few lumps are fine.','Heat oil to around 170–180°C (340–355°F).','Dip vegetable pieces in the batter and fry a few at a time until light golden and crisp, about 2 minutes.','Drain on a rack and serve immediately with the dipping sauce.']::text[], ARRAY['snack']::text[], 'plate', 150, 330, 8.5, 32, 18.5, 4.2, 1.8, 65, 0.2, 485, false),
  (32, 'Chawanmushi', 'Japanese', 'asian', 'egg', false, 'main', '4', '10 min', '15 min', 'A silky Japanese savory egg custard, made with vegetarian dashi.', 'Already minimal; no adjustment needed.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Eggs — 3','Vegetarian dashi (kombu-based, cooled) — 1½ cups','Soy sauce — 1 tsp','Mirin — 1 tsp','Salt — a pinch','Shiitake mushroom, sliced — 4','Spinach leaves — a small handful','Enoki mushrooms (optional) — a few strands']::text[], ARRAY['Whisk the eggs gently, avoiding too much air.','Combine with the cooled dashi, soy sauce, mirin, and salt; whisk gently, then strain for a silky texture.','Divide the mushrooms and spinach among 4 small heatproof cups.','Pour the egg mixture over, filling each cup about ¾ full.','Cover with foil and steam over gently simmering water 12–15 minutes, until just set with a slight wobble.','Serve warm, directly in the cups.']::text[], ARRAY['breakfast']::text[], 'bowl', 150, 65, 8.2, 2.1, 3.5, 0.4, 1.8, 42, 0.35, 285, false),
  (33, 'Zaalouk', 'North African', 'middle_eastern', 'vegan', false, 'side', '4', '10 min', '30 min', 'A smoky Moroccan eggplant and tomato dip, warmed with cumin and paprika.', 'Reducing the olive oil to 2 tbsp saves about 30 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Eggplants, diced — 2 medium','Tomatoes, chopped — 3','Garlic, minced — 3 cloves','Olive oil — 3 tbsp','Ground cumin — 1 tsp','Paprika — 1 tsp','Fresh coriander & parsley — ¼ cup','Lemon juice — 1 tbsp','Salt — to taste']::text[], ARRAY['Heat olive oil; cook the diced eggplant over medium heat until softened, about 10 minutes.','Add garlic, cumin, and paprika; cook 1 minute.','Stir in the tomatoes; cover and simmer 15–20 minutes, mashing occasionally, until soft and jam-like.','Stir in lemon juice and season with salt.','Finish with coriander and parsley; serve warm or at room temperature with bread.']::text[], ARRAY['snack']::text[], 'bowl', 150, 145, 2.1, 11.8, 11.2, 2.9, 0.9, 42, 0, 285, false),
  (34, 'Esquites', 'Mexican', 'latin_american', 'veg', true, 'snack', '4', '10 min', '10 min', 'Mexican street corn salad, creamy and topped with cotija cheese.', 'Swapping the mayonnaise for plain Greek yogurt cuts roughly 70 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Corn kernels — 3 cups','Mayonnaise — 3 tbsp','Cotija or feta, crumbled — ½ cup','Lime juice — 2 tbsp','Chili powder — 1 tsp','Fresh coriander — ¼ cup','Butter — 1 tbsp','Salt — to taste']::text[], ARRAY['Heat the butter in a skillet; cook the corn, stirring, until lightly charred in spots, 8–10 minutes.','Cool slightly, then stir in the mayonnaise, half the cheese, lime juice, and chili powder.','Transfer to a bowl; top with remaining cheese, a little more chili powder, and coriander.','Serve warm or at room temperature with lime wedges.']::text[], ARRAY['snack']::text[], 'bowl', 150, 245, 8.5, 28, 11.5, 3.2, 0.8, 95, 0.3, 340, false),
  (35, 'Feijão Tropeiro (Vegetarian)', 'South American', 'latin_american', 'vegan', false, 'main', '4', '10 min', '20 min', 'A Brazilian sauté of beans, greens, and toasted cassava flour.', 'Omitting the boiled egg garnish saves about 40 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Cooked pinto or black beans — 2 cups','Cassava flour (farinha) — ½ cup','Collard greens or kale, shredded — 2 cups','Onion, chopped — 1','Garlic, minced — 3 cloves','Olive oil — 3 tbsp','Smoked paprika — 1 tsp','Salt & pepper — to taste','Hard-boiled eggs, sliced (optional garnish) — 2']::text[], ARRAY['Heat olive oil; sauté the onion and garlic until soft, about 5 minutes.','Add the greens and cook until wilted, 3–4 minutes.','Stir in the smoked paprika, then add the beans; cook 5 minutes, lightly mashing a few to help everything bind.','Sprinkle in the cassava flour gradually, stirring constantly, until evenly toasted, 3–4 minutes.','Season with salt and pepper.','Top with sliced hard-boiled egg if using, and serve warm.']::text[], ARRAY['dinner']::text[], 'plate', 250, 305, 12.5, 38.2, 11.8, 8.4, 4.2, 125, 0, 385, false),
  (36, 'Ful Medames', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'main', '4', '10 min', '10 min', 'A classic Egyptian breakfast of warm, garlicky mashed fava beans.', 'Reducing the olive oil to 2 tbsp saves about 25 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Cooked fava beans — 3 cups','Garlic, minced — 3 cloves','Olive oil — 3 tbsp','Lemon juice — 3 tbsp','Cumin — 1 tsp','Tomato, chopped — 1','Onion, chopped — ¼ cup','Fresh parsley — 2 tbsp','Salt — to taste','Pita bread — to serve']::text[], ARRAY['Heat the fava beans with a little of their liquid; mash lightly, leaving some beans whole for texture.','Stir in garlic and cumin; warm through 5 minutes.','Off heat, stir in olive oil and lemon juice; season with salt.','Top with chopped tomato, onion, and parsley.','Serve warm with pita for scooping.']::text[], ARRAY['breakfast']::text[], 'bowl', 220, 240, 8.5, 28, 11.2, 7.5, 2.8, 52, 0, 285, false),
  (37, 'Congee (Vegetarian)', 'Chinese', 'asian', 'vegan', false, 'main', '4', '5 min', '50 min', 'A comforting, thick Chinese rice porridge.', 'Naturally very light — add a soft-boiled egg or tofu strips for a more filling, protein-rich breakfast (+~90 kcal, +8g protein).', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Rice — 1 cup','Water or vegetable stock — 8 cups','Ginger, sliced — 3 slices','Soy sauce — 2 tbsp','Sesame oil — 1 tsp','Spring onions, chopped — 2','Toppings (pickled vegetables, fried shallots, tofu strips) — optional']::text[], ARRAY['Rinse the rice and combine with water/stock and ginger in a large pot.','Bring to a boil, then simmer uncovered, stirring occasionally, 45–60 minutes, until it breaks down into a thick, creamy porridge.','Add more water if it thickens too much.','Season with soy sauce.','Ladle into bowls, drizzle with sesame oil, and top with spring onions and desired toppings.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 200, 3.8, 44.2, 1.5, 0.6, 0.4, 12, 0, 485, false),
  (38, 'Kinche', 'East African', 'african', 'veg', true, 'main', '4', '5 min', '20 min', 'An Ethiopian savory cracked wheat porridge.', 'Reducing the butter to 1 tbsp saves about 25 kcal/serving.', 'Traditional', ARRAY['Nut-Free','Jain-Friendly']::text[], ARRAY['Cracked wheat (coarse bulgur) — 1 cup','Water — 3 cups','Butter or niter kibbeh — 2 tbsp','Berbere spice (optional) — 1 tsp','Salt — to taste']::text[], ARRAY['Rinse the cracked wheat.','Bring the water to a boil; add the wheat and a pinch of salt.','Simmer, stirring occasionally, 15–20 minutes, until thick and tender.','Stir in the butter and berbere spice if using.','Serve warm as a savory breakfast porridge.']::text[], ARRAY['breakfast']::text[], 'bowl', 200, 200, 6.2, 32.5, 7.8, 5.2, 2.1, 28, 0.08, 285, false),
  (39, 'Cong You Bing', 'Chinese', 'asian', 'vegan', false, 'staple', '4', '40 min (incl. resting)', '15 min', 'Flaky, pan-fried Chinese scallion pancakes.', 'Using less oil for pan-frying (1 tbsp per pancake) saves about 50 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['All-purpose flour — 2 cups','Boiling water — ¾ cup','Spring onions, finely chopped — 1 cup','Sesame oil — 3 tbsp','Salt — 1 tsp','Vegetable oil — for pan-frying']::text[], ARRAY['Gradually mix the boiling water into the flour to form a shaggy dough; knead smooth, then rest covered 30 minutes.','Divide into 4 portions; roll each into a thin circle.','Brush with sesame oil, sprinkle with salt and scallions, roll into a log, and coil into a spiral.','Flatten and roll out again into a thin round.','Pan-fry in a little oil until golden and crisp on both sides, 3–4 minutes per side.','Cut into wedges and serve hot.']::text[], ARRAY['breakfast']::text[], 'piece', 120, 395, 8.5, 48.2, 16.8, 1.2, 2.1, 45, 0, 580, false),
  (40, 'Tamagoyaki', 'Japanese', 'asian', 'egg', true, 'main', '4', '10 min', '10 min', 'A gently sweet-savory Japanese rolled omelette.', 'Already lean — no adjustment needed.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Eggs — 6','Vegetarian dashi — 3 tbsp','Soy sauce — 1 tbsp','Mirin — 1 tbsp','Sugar — 1 tsp','Vegetable oil — for cooking']::text[], ARRAY['Whisk the eggs with dashi, soy sauce, mirin, and sugar.','Heat a lightly oiled rectangular pan over medium heat.','Pour in a thin layer of egg; when mostly set, roll it to one side.','Oil the empty pan space, pour in another thin layer letting it flow under the rolled portion, and continue rolling.','Repeat until all the egg is used, building layers into one roll.','Slice and serve warm or at room temperature.']::text[], ARRAY['breakfast']::text[], 'serving', 90, 125, 11.2, 3.8, 7.1, 0, 1.8, 32, 0.52, 385, false),
  (41, 'Pão de Queijo', 'South American', 'latin_american', 'egg', true, 'snack', '4', '15 min', '25 min', 'Rich, chewy Brazilian cheese bread — genuinely indulgent by tradition.', 'Reducing the oil to ¼ cup and using low-fat milk cuts roughly 150 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Tapioca starch — 2 cups','Milk — ½ cup','Vegetable oil — ½ cup','Eggs — 2','Parmesan or similar hard cheese, grated — 1 cup','Salt — ½ tsp']::text[], ARRAY['Heat the milk, oil, and salt together until just simmering; pour over the tapioca starch and mix into a sticky dough.','Cool slightly, then knead in the eggs one at a time, followed by the cheese, until smooth and elastic.','Roll into small, golf-ball-sized portions.','Bake at 190°C (375°F) for 20–25 minutes, until puffed and golden.','Serve warm.']::text[], ARRAY['breakfast']::text[], 'serving', 120, 620, 18.5, 52.3, 34.2, 0.8, 1.2, 385, 0.6, 520, false),
  (42, 'Sopa de Tortilla', 'Mexican', 'latin_american', 'veg', false, 'soup', '4', '15 min', '25 min', 'A smoky Mexican tortilla soup, finished with avocado and crisp tortilla strips.', 'Baking the tortilla strips instead of frying, and using half the avocado, saves about 70 kcal/serving.', 'Traditional', ARRAY['Nut-Free','Low-Carb']::text[], ARRAY['Corn tortillas, cut into strips — 4','Tomatoes — 4 medium (or 1 can)','Onion — 1','Garlic — 3 cloves','Vegetable stock — 4 cups','Dried guajillo chili (or chili powder) — 1–2','Vegetable oil — 4 tbsp total','Avocado, diced — 1','Queso fresco or feta, crumbled — ½ cup','Fresh coriander & lime — to serve']::text[], ARRAY['Fry the tortilla strips in a little oil until crisp; drain and set aside.','Blend the tomatoes, onion, garlic, and soaked chili until smooth.','Heat 1 tbsp oil in a pot; cook the blended mixture 8–10 minutes until it darkens and thickens.','Add the stock; simmer 15 minutes. Season with salt.','Ladle into bowls, top with crispy tortilla strips, avocado, queso fresco, coriander, and lime.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 300, 9.5, 32, 12.5, 5, 1.8, 95, 0.3, 580, false),
  (43, 'Bissara', 'North African', 'middle_eastern', 'vegan', false, 'soup', '4', '10 min', '50 min', 'A creamy North African fava bean puree, drizzled with olive oil.', 'Reducing the finishing olive oil to 1 tbsp total saves about 20 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Dried split fava beans — 1½ cups','Water — 4 cups','Garlic — 3 cloves','Ground cumin — 1 tsp','Olive oil — 3 tbsp (plus more to serve)','Paprika — 1 tsp','Salt — to taste','Lemon wedges — to serve']::text[], ARRAY['Rinse the beans; combine with water and garlic in a pot.','Boil, then simmer 45–60 minutes until very soft and starting to break down.','Blend or mash until smooth, adding water as needed for a creamy, soup-like consistency.','Stir in cumin, olive oil, and salt.','Ladle into bowls, drizzle with more oil, sprinkle with paprika, and serve with lemon and bread.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 345, 13.2, 38.5, 11.8, 10.2, 3.1, 58, 0, 380, false),
  (44, 'Pongal', 'South Indian', 'south_indian', 'veg', true, 'main', '4', '10 min', '25 min', 'A comforting South Indian savory rice and lentil dish, tempered with cumin and pepper.', 'Reducing the ghee to 2 tbsp saves about 30 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Jain-Friendly']::text[], ARRAY['Rice — 1 cup','Split yellow moong dal — ½ cup','Water — 4 cups','Ghee — 3 tbsp','Cumin seeds — 1 tsp','Black pepper, cracked — 1 tsp','Ginger, grated — 1 tbsp','Curry leaves — a sprig','Cashews — 2 tbsp','Salt — to taste']::text[], ARRAY['Dry-roast the moong dal lightly until fragrant, then rinse together with the rice.','Cook the rice and dal with water until very soft and porridge-like, about 20–25 minutes.','In a small pan, heat the ghee; add cumin, pepper, ginger, curry leaves, and cashews, sautéing until the cashews are golden.','Pour the tempering over the cooked rice and dal; mix well.','Season with salt; serve hot with coconut chutney or sambar.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 390, 8.5, 52, 14.5, 3.2, 2.1, 45, 0.15, 380, false),
  (45, 'Gomen', 'East African', 'african', 'vegan', false, 'side', '4', '10 min', '30 min', 'Ethiopian collard greens, slow-cooked until deeply tender.', 'Reducing the oil to 2 tbsp saves about 25 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Collard greens, shredded — 6 cups','Onion, chopped — 1','Garlic — 3 cloves','Ginger, grated — 1 tbsp','Vegetable oil — 3 tbsp','Green chili, chopped (optional) — 1','Salt — to taste']::text[], ARRAY['Heat oil in a pot; sauté the onion until soft, cooking low and slow, 6–8 minutes.','Add garlic, ginger, and chili; cook 1–2 minutes.','Add the collard greens in batches, stirring to wilt.','Cover and cook on low heat, stirring occasionally, 20–25 minutes, until very tender.','Season with salt; serve with injera or flatbread.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 120, 3.2, 8.5, 5.8, 2.1, 1.8, 85, 0, 280, false),
  (46, 'Spanakopita', 'Western European', 'european', 'egg', false, 'main', '4', '20 min', '40 min', 'A crisp Greek spinach and feta pie, layered in phyllo.', 'Reducing the brushing oil to 3 tbsp total saves about 60 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Fresh spinach, chopped — 500 g','Onion, chopped — 1','Feta cheese, crumbled — 200 g','Eggs — 2','Fresh dill, chopped — 2 tbsp','Phyllo pastry sheets — 8','Olive oil — ¼ cup (for brushing + sauté)','Salt & pepper — to taste']::text[], ARRAY['Sauté the onion in a little olive oil until soft; add the spinach in batches and cook until wilted, then drain excess liquid.','Cool slightly, then mix with feta, eggs, and dill; season.','Layer half the phyllo in a baking dish, brushing each sheet lightly with oil.','Spread the spinach-feta filling evenly over the base.','Top with the remaining phyllo, brushing each layer, and score into portions.','Bake at 180°C (350°F) for 35–40 minutes until golden and crisp. Cool slightly before slicing.']::text[], ARRAY['lunch']::text[], 'piece', 200, 440, 14.2, 32.5, 22.8, 2.1, 3.2, 185, 0.65, 485, false),
  (47, 'Ethiopian Vegetable & Mushroom Tibs', 'East African', 'african', 'vegan', false, 'side', '4', '10 min', '15 min', 'A quick, high-heat Ethiopian mushroom and pepper stir-fry.', 'Reducing the oil to 2 tbsp saves about 25 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Mixed mushrooms, sliced — 3 cups','Bell peppers, sliced — 2','Onion, sliced — 1','Garlic — 3 cloves','Rosemary or berbere spice — 1 tsp','Vegetable oil — 3 tbsp','Jalapeño or green chili, sliced (optional) — 1','Salt — to taste']::text[], ARRAY['Heat oil in a wide pan over high heat; cook the onion until starting to soften, 3–4 minutes.','Add the mushrooms and cook until they release their liquid and start to brown, 5–6 minutes.','Add the bell peppers, garlic, and chili; stir-fry 4–5 minutes until tender but still with some bite.','Season with rosemary or berbere spice and salt.','Serve hot with injera or flatbread.']::text[], ARRAY['dinner']::text[], 'bowl', 180, 125, 4.2, 12.8, 5.1, 2.4, 1.8, 42, 0.05, 380, false),
  (48, 'Arepas with Black Beans & Avocado', 'South American', 'latin_american', 'veg', true, 'main', '4', '15 min', '15 min', 'Grilled Colombian/Venezuelan cornmeal patties, filled with beans and avocado.', 'Using a lighter hand with the avocado and queso fresco brings this to roughly 420 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly','High-Protein']::text[], ARRAY['Pre-cooked cornmeal (masarepa) — 2 cups','Warm water — 2½ cups','Salt — 1 tsp','Vegetable oil — for cooking','Black beans, cooked — 1½ cups','Avocado, sliced — 1','Queso fresco, crumbled — ½ cup','Fresh coriander — garnish']::text[], ARRAY['Mix the cornmeal with warm water and salt; rest 5 minutes until it forms a smooth, pliable dough.','Divide into 8 balls; flatten each into a disc about 1cm thick.','Cook on a lightly oiled griddle over medium heat, 5–7 minutes per side, until golden with a slight crust.','Split each arepa open slightly and fill with black beans, avocado, and queso fresco.','Garnish with coriander and serve warm.']::text[], ARRAY['dinner']::text[], 'plate', 300, 485, 14.2, 52.8, 16.5, 8.3, 2.8, 185, 0.3, 425, false),
  (49, 'Arroz con Leche', 'Mexican', 'latin_american', 'veg', true, 'dessert', '4', '5 min', '40 min', 'A creamy, cinnamon-scented Mexican rice pudding.', 'Reducing the sugar to ⅓ cup and using low-fat milk brings this to roughly 340 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['White rice — 1 cup','Water — 2 cups','Milk — 3 cups','Cinnamon stick — 1','Sugar — ½ cup','Vanilla extract — 1 tsp','Raisins (optional) — ¼ cup','Ground cinnamon — for garnish']::text[], ARRAY['Combine the rice, water, and cinnamon stick; boil, then simmer until the water is mostly absorbed, about 10 minutes.','Add the milk and sugar; simmer, stirring frequently, 25–30 minutes, until thick and creamy.','Stir in vanilla and raisins if using; remove the cinnamon stick.','Serve warm or chilled, dusted with ground cinnamon.']::text[], ARRAY['snack']::text[], 'bowl', 200, 415, 8.2, 58.4, 6.8, 0.8, 0.9, 240, 0.5, 85, false),
  (50, 'Karkade', 'North African', 'middle_eastern', 'vegan', true, 'drink', '4', '5 min', '15 min (steeping)', 'A tart, ruby-red Egyptian hibiscus tea, served chilled.', 'Can be enjoyed unsweetened for a virtually calorie-free option.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Dried hibiscus flowers — ½ cup','Water — 4 cups','Sugar or honey — 2–3 tbsp, to taste','Fresh mint (optional) — a few leaves','Lime slices — to serve']::text[], ARRAY['Bring the water to a boil; add the dried hibiscus flowers.','Remove from heat, cover, and steep 10–15 minutes.','Strain out the flowers.','Stir in sugar or honey while still warm, so it dissolves easily.','Chill well and serve over ice, garnished with mint and lime.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 30, 0.3, 7.5, 0.1, 1.2, 0.5, 12, 0, 8, false),
  (51, 'Dal Tadka', 'North Indian', 'north_indian', 'veg', false, 'dal', '4', '10 min', '30 min', 'Yellow lentil curry, finished with a sizzling cumin-garlic tempering.', 'Reducing the ghee to 1 tbsp saves about 45 kcal/serving — the flavour is still strong.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Toor dal — 1 cup','Water — 3 cups','Onion, chopped — 1','Tomatoes, chopped — 2','Garlic, minced — 4 cloves','Ginger, grated — 1 tbsp','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Red chili powder — 1 tsp','Ghee — 2 tbsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Rinse the toor dal and pressure cook (or simmer) with water and turmeric until completely soft, about 20 minutes.','Heat ghee in a pan; add cumin seeds and let them splutter.','Add onion and cook until golden, about 8 minutes.','Add garlic and ginger; cook 1 minute, then add tomatoes and red chili powder.','Cook until the tomatoes break down, about 5 minutes.','Pour this tadka over the cooked dal; stir and simmer 5 minutes.','Season with salt, garnish with coriander, and serve with rice or roti.']::text[], ARRAY['dinner','breakfast','lunch']::text[], 'bowl', 180, 290, 9.2, 32.5, 10.8, 6.2, 2.8, 42, 0.12, 385, false),
  (52, 'Palak Paneer', 'North Indian', 'north_indian', 'veg', false, 'curry', '4', '15 min', '25 min', 'Spinach and cottage cheese curry, silky and mildly spiced.', 'Skipping the cream and using a splash of milk saves about 50 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein','Low-Carb']::text[], ARRAY['Paneer, cubed — 250 g','Fresh spinach — 500 g','Onion, chopped — 1','Tomato, chopped — 1','Garlic — 4 cloves','Ginger — 1 inch','Green chilies — 2','Cream — 2 tbsp','Cumin seeds — 1 tsp','Garam masala — 1 tsp','Vegetable oil — 3 tbsp','Salt — to taste']::text[], ARRAY['Blanch the spinach in boiling water 2 minutes; drain and blend to a smooth purée.','Pan-fry the paneer cubes until golden on two sides; set aside.','Heat oil; add cumin seeds, then onion, and cook until golden.','Add ginger, garlic, and green chilies; cook 1 minute.','Add the tomato and cook until soft; stir in the garam masala.','Add the spinach purée; simmer 5 minutes.','Fold in the paneer and cream; warm through and season with salt.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 380, 18.5, 8.2, 28.4, 1.8, 3.2, 312, 0.35, 485, false),
  (53, 'Aloo Paratha', 'North Indian', 'north_indian', 'veg', false, 'main', '4', '30 min', '20 min', 'Whole wheat flatbread stuffed with spiced mashed potato.', 'Using just ½ tsp ghee per paratha instead of a generous knob saves about 60 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Whole wheat flour — 2 cups','Water — ¾ cup','Potatoes, boiled and mashed — 3 medium','Green chilies, chopped — 2','Fresh coriander, chopped — 3 tbsp','Cumin seeds — 1 tsp','Amchur (dry mango powder) — ½ tsp','Ghee or butter — for cooking','Salt — to taste']::text[], ARRAY['Mix flour with water and salt; knead into a smooth dough. Rest 20 minutes.','Combine mashed potato, chilies, coriander, cumin, amchur, and salt for the filling.','Divide the dough into 8 balls. Roll each into a small circle, place a spoonful of filling in the centre.','Gather the edges, pinch to seal, and gently roll out again into a flat disc.','Cook on a hot griddle with a little ghee, 2–3 minutes per side until golden.','Serve hot with yogurt and pickle.']::text[], ARRAY['breakfast','dinner','lunch']::text[], 'piece', 150, 420, 9.2, 48.5, 14.8, 6.2, 2.1, 45, 0.08, 320, false),
  (54, 'Rajma Masala', 'North Indian', 'north_indian', 'vegan', false, 'curry', '4', '10 min', '30 min', 'Kidney bean curry in a deeply spiced onion-tomato gravy.', 'Reducing the oil to 2 tbsp saves about 45 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Kidney beans, cooked — 2 cups','Onion, finely chopped — 1 large','Tomatoes, puréed — 3','Ginger-garlic paste — 2 tbsp','Coriander powder — 1 tsp','Cumin powder — 1 tsp','Garam masala — 1 tsp','Red chili powder — ½ tsp','Vegetable oil — 3 tbsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Heat oil; cook onion until deep golden, about 10 minutes.','Add ginger-garlic paste; cook 2 minutes.','Add the puréed tomatoes and all spices; cook until oil separates, about 8 minutes.','Add the kidney beans and enough water to make a thick gravy.','Simmer 15 minutes, mashing a few beans to thicken.','Garnish with coriander; serve with steamed rice.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 320, 12.5, 38.2, 11.8, 8.3, 4.2, 68, 0, 385, false),
  (55, 'Chole', 'North Indian', 'north_indian', 'vegan', false, 'curry', '4', '10 min', '25 min', 'Spiced chickpea curry, sharp with chole masala and a squeeze of lemon.', 'Already a lean dish — the oil is the main lever; 2 tbsp instead of 3 saves about 45 kcal.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Chickpeas, cooked — 2 cups','Onion, chopped — 1 large','Tomatoes, chopped — 3','Ginger-garlic paste — 2 tbsp','Chole masala — 2 tbsp','Cumin seeds — 1 tsp','Bay leaf — 1','Vegetable oil — 3 tbsp','Lemon juice — 1 tbsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Heat oil; add cumin seeds and bay leaf; let them splutter.','Add onion and cook until golden, about 8 minutes.','Add ginger-garlic paste and cook 2 minutes.','Add tomatoes and chole masala; cook until oil separates.','Add chickpeas and enough water for a thick gravy; simmer 15 minutes.','Squeeze in lemon juice, garnish with coriander, and serve with bhature or rice.']::text[], ARRAY['lunch','dinner','breakfast']::text[], 'bowl', 200, 340, 12.5, 38.2, 11.8, 8.5, 3.2, 68, 0, 385, false),
  (56, 'Matar Paneer', 'North Indian', 'north_indian', 'veg', false, 'curry', '4', '10 min', '25 min', 'Peas and cottage cheese in a creamy cashew-tomato gravy.', 'Skipping the cream and reducing cashews to 6 saves about 80 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','High-Protein','Low-Carb']::text[], ARRAY['Paneer, cubed — 200 g','Green peas — 1 cup','Onion, chopped — 1','Tomatoes, puréed — 2','Ginger-garlic paste — 1 tbsp','Cashews — 10 (soaked, for gravy)','Cream — 2 tbsp','Cumin seeds — 1 tsp','Garam masala — 1 tsp','Vegetable oil — 3 tbsp','Salt — to taste']::text[], ARRAY['Blend the soaked cashews with a little water into a smooth paste; set aside.','Heat oil; add cumin seeds, then onion; cook until golden.','Add ginger-garlic paste and cook 2 minutes.','Add puréed tomatoes and garam masala; cook until oil separates.','Stir in the cashew paste and cream; simmer 3 minutes.','Add peas and paneer; cook 5 minutes until heated through.','Season and serve with naan or roti.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 360, 18.5, 22, 16.5, 3.2, 2.8, 285, 0.35, 520, false),
  (57, 'Baingan Bharta', 'North Indian', 'north_indian', 'vegan', false, 'side', '4', '10 min', '30 min', 'Smoky roasted aubergine mashed and simmered with onion and tomato.', 'Already a very light dish — no real adjustment needed.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Aubergine (eggplant), large — 2','Onion, finely chopped — 1','Tomatoes, chopped — 2','Garlic, minced — 3 cloves','Ginger, grated — 1 tsp','Green chili, chopped — 1','Cumin seeds — 1 tsp','Coriander powder — 1 tsp','Garam masala — ½ tsp','Vegetable oil — 2 tbsp','Fresh coriander — garnish','Salt — to taste']::text[], ARRAY['Char the aubergines directly over a flame or under a broiler until completely blackened. Cool, peel, and mash the flesh.','Heat oil; add cumin seeds, then onion; cook until golden, about 8 minutes.','Add garlic, ginger, and chili; cook 1 minute.','Add tomatoes and spices; cook until soft, about 5 minutes.','Add the mashed aubergine; mix well and cook 8–10 minutes until the flavours meld.','Garnish with coriander; serve with roti.']::text[], ARRAY['dinner','lunch']::text[], 'bowl', 150, 155, 3.2, 12.8, 7.5, 3.4, 0.8, 42, 0, 280, false),
  (58, 'Lassi', 'North Indian', 'north_indian', 'veg', true, 'drink', '4', '5 min', 'none', 'Chilled yogurt drink — sweet or salted, both ways refreshing.', 'The salted version is naturally half the calories — a good everyday choice over the sweet.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Plain yogurt — 2 cups','Cold water or milk — 1 cup','Sugar — 3 tbsp (sweet version) or Salt — ½ tsp (salted version)','Cardamom powder — ¼ tsp (sweet) or Cumin, roasted and ground — ½ tsp (salted)','Rose water (optional) — 1 tsp','Fresh mint — a few leaves (salted)','Ice — a handful']::text[], ARRAY['For either version, blend all ingredients together until frothy and smooth.','Taste and adjust sweetness, salt, or spice.','Pour into glasses and serve immediately over ice.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 220, 140, 3.5, 16.2, 1.8, 0.1, 0.2, 145, 0.35, 65, false),
  (59, 'Minestrone Soup', 'Western European', 'european', 'vegan', false, 'soup', '4', '15 min', '35 min', 'A hearty Italian vegetable and bean soup with small pasta.', 'Halving the pasta and adding more beans keeps it filling at fewer carbs.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Onion, chopped — 1','Carrots, diced — 2','Celery, chopped — 2 stalks','Zucchini, diced — 1','Canned diced tomatoes — 1 can (400g)','Cannellini beans, cooked — 1 cup','Small pasta (ditalini or elbow) — ½ cup','Vegetable stock — 5 cups','Garlic, minced — 3 cloves','Olive oil — 3 tbsp','Dried oregano — 1 tsp','Fresh basil — garnish','Salt & pepper — to taste']::text[], ARRAY['Heat olive oil; sauté onion, carrots, and celery until softened, about 6 minutes.','Add garlic and oregano; cook 1 minute.','Add zucchini, tomatoes, beans, and stock; bring to a boil.','Add the pasta and simmer 10–12 minutes until pasta is just tender.','Season, garnish with fresh basil, and serve with crusty bread.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 240, 8.5, 28, 9.5, 6, 2.2, 65, 0, 580, false),
  (60, 'Caprese Salad with Burrata', 'Western European', 'european', 'veg', true, 'salad', '4', '10 min', 'none', 'Fresh tomato, basil, and burrata drizzled with olive oil and balsamic.', 'Reducing the olive oil to 2 tbsp saves about 60 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Burrata or fresh mozzarella — 250g','Ripe tomatoes, sliced — 4 large','Fresh basil leaves — a generous handful','Extra virgin olive oil — 4 tbsp','Balsamic glaze — 2 tbsp','Salt & black pepper — to taste']::text[], ARRAY['Arrange tomato slices on a platter.','Tear or slice the burrata and place over the tomatoes.','Scatter the basil leaves generously.','Drizzle with olive oil and balsamic glaze.','Season with salt and cracked black pepper; serve immediately.']::text[], ARRAY['snack']::text[], 'plate', 180, 280, 12.5, 8.2, 21.3, 1.5, 0.8, 185, 0.6, 320, false),
  (61, 'Lentil Soup', 'Western European', 'european', 'vegan', false, 'soup', '4', '10 min', '35 min', 'A French-style blended-and-chunky lentil soup, brightened with lemon.', 'Reducing the olive oil to 2 tbsp saves about 45 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Green or brown lentils — 1½ cups','Onion, chopped — 1','Carrots, diced — 2','Garlic, minced — 3 cloves','Celery — 2 stalks','Vegetable stock — 5 cups','Olive oil — 3 tbsp','Thyme — 1 tsp','Bay leaf — 1','Lemon juice — 1 tbsp','Salt & pepper — to taste']::text[], ARRAY['Heat oil; sauté onion, carrots, and celery until soft, about 6 minutes.','Add garlic and thyme; cook 1 minute.','Add lentils, stock, and bay leaf; bring to a boil.','Simmer 25–30 minutes until lentils are completely tender.','Remove the bay leaf; blend half the soup for a creamy-chunky texture.','Stir in lemon juice, season, and serve with crusty bread.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 280, 12.5, 32, 11.5, 7.5, 3.2, 65, 0, 680, false),
  (62, 'Quiche Florentine', 'Western European', 'european', 'egg', true, 'main', '6', '20 min', '40 min', 'A spinach and cheese tart in a buttery pastry shell.', 'Using half cream and half milk throughout saves about 60 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Shortcrust pastry shell, blind-baked — 1 (23cm)','Fresh spinach, wilted and drained — 300g','Gruyère or Emmental, grated — 150g','Eggs — 4','Double cream — 200ml','Milk — 100ml','Nutmeg — a pinch','Salt & pepper — to taste']::text[], ARRAY['Preheat oven to 180°C (350°F).','Spread the wilted, well-drained spinach evenly over the pastry base.','Scatter the grated cheese over the spinach.','Whisk together the eggs, cream, milk, nutmeg, salt, and pepper.','Pour the custard over the spinach and cheese.','Bake 35–40 minutes until set with a slight wobble in the centre.','Cool 10 minutes before slicing; serve warm or at room temperature.']::text[], ARRAY['lunch']::text[], 'serving', 180, 380, 16.2, 18.5, 24.8, 1.2, 2.1, 285, 1.2, 420, false),
  (63, 'Potato Gratin', 'Western European', 'european', 'veg', false, 'main', '6', '20 min', '60 min', 'Thinly sliced potatoes baked in garlicky cream, French bistro style.', 'Substituting half the cream with vegetable stock saves about 80 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Potatoes, thinly sliced — 1kg','Double cream — 300ml','Milk — 200ml','Garlic, minced — 2 cloves','Gruyère, grated — 100g','Butter — 1 tbsp','Nutmeg — a pinch','Salt & pepper — to taste']::text[], ARRAY['Preheat oven to 170°C (340°F). Rub a baking dish with the butter and garlic.','Warm the cream and milk together with garlic, nutmeg, salt, and pepper.','Layer the potato slices in the dish, pouring a little of the cream mixture over each layer.','Top with the remaining cream and scatter the cheese over.','Bake 55–60 minutes until the top is golden and the potatoes are completely tender.','Rest 10 minutes before serving.']::text[], ARRAY['dinner']::text[], 'serving', 220, 360, 9.5, 28, 18.5, 2, 0.8, 245, 0.5, 380, false),
  (64, 'Gazpacho', 'Western European', 'european', 'vegan', false, 'soup', '4', '15 min + 2 hrs chilling', 'none', 'Chilled Spanish raw tomato and vegetable soup.', 'Reducing the olive oil to 2 tbsp brings this to roughly 115 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Ripe tomatoes — 800g','Cucumber — 1','Red bell pepper — 1','Garlic — 1 clove','Red onion — ¼','Olive oil — 4 tbsp','Red wine vinegar — 2 tbsp','Salt — to taste','Ice-cold water — ½ cup','Croutons and diced vegetables — to garnish']::text[], ARRAY['Roughly chop all the vegetables and blend until completely smooth.','Add the olive oil, vinegar, and salt; blend again.','Add ice-cold water to achieve a pourable soup consistency.','Pass through a sieve for a silky texture if preferred.','Chill at least 2 hours before serving.','Serve very cold, topped with croutons and finely diced cucumber, tomato, and pepper.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 160, 2.5, 15.2, 12.8, 3.1, 1.2, 28, 0, 380, false),
  (65, 'Bibimbap', 'Korean', 'asian', 'egg', false, 'main', '4', '30 min', '20 min', 'Korean mixed rice bowl with sautéed vegetables, tofu, and gochujang.', 'Halving the gochujang and using 1 tbsp sesame oil saves about 60 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Steamed short-grain rice — 4 cups','Spinach, blanched — 2 cups','Carrots, julienned and sautéed — 2','Bean sprouts, blanched — 1 cup','Shiitake mushrooms, sautéed — 1 cup','Firm tofu, pan-fried — 200g','Fried eggs (optional) — 4','Gochujang (Korean chili paste) — 4 tbsp','Sesame oil — 2 tbsp','Soy sauce — 1 tbsp','Sesame seeds — for garnish']::text[], ARRAY['Prepare each vegetable topping separately: season spinach, carrots, and bean sprouts with a little sesame oil and soy sauce; sauté mushrooms with soy sauce.','Pan-fry the tofu until golden.','Divide the hot rice among 4 bowls.','Arrange the vegetable toppings and tofu in separate sections over the rice.','Top each bowl with a fried egg if using.','Add a spoonful of gochujang and a drizzle of sesame oil.','Mix everything together well at the table before eating.']::text[], ARRAY['dinner']::text[], 'plate', 400, 520, 18.5, 62, 15.2, 5.8, 4.2, 185, 0.5, 685, false),
  (66, 'Japchae', 'Korean', 'asian', 'egg', false, 'main', '4', '20 min', '20 min', 'Korean glass noodles stir-fried with vegetables and sesame oil.', 'Reducing the sesame oil to 1 tbsp and sugar to 1 tbsp saves about 80 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Glass noodles (dangmyeon) — 200g','Spinach, blanched — 2 cups','Carrots, julienned — 2','Bell pepper, julienned — 1','Shiitake mushrooms, sliced — 1 cup','Onion, sliced — 1','Eggs, beaten (optional) — 2','Soy sauce — 4 tbsp','Sugar — 2 tbsp','Sesame oil — 2 tbsp','Vegetable oil — 3 tbsp','Sesame seeds — garnish']::text[], ARRAY['Boil the glass noodles until tender (about 6 minutes); drain and cut into shorter lengths.','Toss noodles with 2 tbsp soy sauce and 1 tbsp sesame oil.','Stir-fry each vegetable separately in a little oil, seasoning with soy sauce.','Scramble the eggs separately if using.','Combine all the noodles, vegetables, and egg in a large pan; add the remaining soy sauce, sugar, and sesame oil; toss together over medium heat.','Garnish with sesame seeds; serve warm or at room temperature.']::text[], ARRAY['dinner']::text[], 'plate', 300, 440, 12.5, 48, 16.5, 3.2, 2.8, 85, 0.3, 890, false),
  (67, 'Doenjang Jjigae', 'Korean', 'asian', 'vegan', false, 'soup', '4', '10 min', '20 min', 'Korean fermented soybean paste stew with tofu and vegetables.', 'Already very light — add tofu or an egg if you want more protein without significant extra calories.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Doenjang (fermented soybean paste) — 3 tbsp','Firm tofu, cubed — 200g','Zucchini, diced — 1','Mushrooms, sliced — 1 cup','Onion, chopped — 1','Garlic, minced — 2 cloves','Vegetarian dashi or water — 4 cups','Gochugaru (Korean chili flakes, optional) — 1 tsp','Sesame oil — 1 tsp','Spring onions — garnish']::text[], ARRAY['Bring the dashi or water to a boil; stir in the doenjang paste until dissolved.','Add the onion, zucchini, and mushrooms; simmer 8 minutes.','Add the tofu and garlic; simmer another 5 minutes.','Add gochugaru if using; adjust seasoning.','Drizzle with sesame oil; garnish with spring onions.','Serve hot with steamed rice — the stew is salty enough to season the whole bowl.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 140, 8.5, 10.2, 4.8, 2.1, 2.4, 145, 0.3, 520, false),
  (68, 'Sundubu Jjigae', 'Korean', 'asian', 'egg', false, 'soup', '4', '10 min', '15 min', 'Soft tofu stew, spicy and comforting, optionally topped with an egg.', 'Omitting the egg saves about 70 kcal/serving if a lighter portion is preferred.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Silken tofu — 600g','Mushrooms, sliced — 1 cup','Zucchini, diced — 1','Onion, sliced — 1','Garlic, minced — 3 cloves','Gochugaru — 2 tbsp','Soy sauce — 2 tbsp','Sesame oil — 1 tbsp','Vegetable oil — 1 tbsp','Vegetable stock — 3 cups','Eggs (optional, one per serving) — 4','Spring onions — garnish']::text[], ARRAY['Heat oil in an earthenware pot or saucepan; fry gochugaru 1 minute until fragrant.','Add garlic and onion; cook 2–3 minutes.','Pour in the stock; add mushrooms and zucchini; simmer 5 minutes.','Break in the silken tofu in large spoonfuls; simmer 3 minutes.','Crack an egg into the stew if using; cover and cook until just set.','Add soy sauce and sesame oil; garnish with spring onions.','Serve immediately with steamed rice.']::text[], ARRAY['dinner']::text[], 'bowl', 350, 190, 16.5, 8.2, 7.8, 1.5, 2.1, 185, 0.4, 620, false),
  (69, 'Kimchi Bokkeumbap', 'Korean', 'asian', 'egg', false, 'main', '4', '10 min', '15 min', 'Kimchi fried rice with crumbled tofu, topped with a fried egg.', 'Omitting the fried egg and reducing gochujang to 1 tbsp brings this to roughly 350 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Cooked day-old rice — 4 cups','Vegetarian kimchi, chopped — 1½ cups','Tofu, crumbled — 200g','Spring onions, chopped — 3','Garlic, minced — 2 cloves','Gochujang — 2 tbsp','Soy sauce — 1 tbsp','Sesame oil — 1 tbsp','Vegetable oil — 2 tbsp','Fried eggs (optional) — 4','Sesame seeds — garnish','Nori strips — garnish']::text[], ARRAY['Heat vegetable oil in a wok over high heat; stir-fry garlic 30 seconds.','Add the kimchi and crumbled tofu; stir-fry 3–4 minutes.','Add the rice, breaking up clumps; stir-fry 3–4 minutes on high heat.','Add gochujang, soy sauce, and sesame oil; toss to coat evenly.','Stir in most of the spring onions.','Top each serving with a fried egg if using; garnish with sesame seeds, nori strips, and remaining spring onions.']::text[], ARRAY['dinner']::text[], 'plate', 350, 430, 14.2, 52.8, 14.5, 2.1, 2.8, 95, 0.4, 580, false),
  (70, 'Sri Lankan Dal Curry (Parippu)', 'Sri Lankan', 'asian', 'vegan', false, 'dal', '4', '10 min', '25 min', 'Red lentils simmered in coconut milk with a mustard-curry leaf tempering.', 'Using light coconut milk instead of full-fat saves about 50 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Red lentils — 1½ cups','Coconut milk — 1 cup','Onion, sliced — 1','Green chilies — 2','Garlic, minced — 3 cloves','Ginger, grated — 1 tbsp','Curry leaves — a sprig','Mustard seeds — 1 tsp','Turmeric — ½ tsp','Pandan leaf (optional) — 1','Vegetable oil — 2 tbsp','Salt — to taste']::text[], ARRAY['Cook the red lentils with water until soft; drain excess water.','Stir in coconut milk, turmeric, and salt; simmer 5 minutes.','Heat oil in a pan; fry mustard seeds and curry leaves until they splutter.','Add onion, garlic, ginger, and green chilies; cook until golden.','Pour this tempering over the lentils; stir and simmer 3 minutes.','Serve with steamed rice and other curries.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 310, 13.5, 38.2, 9.8, 6.4, 3.2, 42, 0, 385, false),
  (71, 'Kottu Roti (Vegetarian)', 'Sri Lankan', 'asian', 'egg', false, 'main', '4', '15 min', '15 min', 'Sri Lankan chopped flatbread stir-fried with egg and vegetables.', 'Reducing to 2 tbsp oil and using 2 eggs saves about 70 kcal/serving.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Roti or flatbread, shredded/chopped — 4 pieces','Eggs, beaten — 3','Onion, sliced — 1','Carrot, julienned — 1','Cabbage, shredded — 1 cup','Bell pepper, sliced — 1','Curry leaves — a sprig','Sri Lankan curry powder — 2 tbsp','Soy sauce — 2 tbsp','Vegetable oil — 3 tbsp','Salt — to taste']::text[], ARRAY['Heat oil in a wok; fry curry leaves until fragrant.','Add onion and cook until softened; add carrot, cabbage, and bell pepper; stir-fry 3–4 minutes.','Push vegetables to one side; scramble the eggs in the space alongside.','Add the chopped roti pieces; toss everything together on high heat.','Season with curry powder and soy sauce; stir-fry 3 more minutes.','Serve hot, ideally in the traditional loud-chopping style at the table.']::text[], ARRAY['dinner']::text[], 'plate', 300, 460, 13.5, 48.2, 18.3, 3.8, 2.4, 78, 0.35, 685, false),
  (72, 'Pol Sambol', 'Sri Lankan', 'asian', 'vegan', false, 'chutney', '4', '10 min', 'none', 'Sri Lankan coconut relish, tangy and spicy — a table staple.', 'Fresh grated coconut is naturally high in fat — a little goes a long way; half the serving still delivers the full flavour hit.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Freshly grated coconut (or desiccated, soaked) — 1½ cups','Red onion, finely chopped — 1 small','Green or red chilies, chopped — 2','Lime juice — 2 tbsp','Salt — to taste','Maldive fish substitute (dried shiitake powder, optional) — 1 tsp']::text[], ARRAY['Combine the grated coconut, red onion, and chilies in a bowl.','Add lime juice and salt; mix well, tasting as you go — it should be tangy and spicy.','Serve alongside rice, hoppers, or string hoppers as a side condiment.']::text[], ARRAY['snack']::text[], 'serving', 40, 180, 3.2, 12.5, 14.8, 2.1, 1.8, 42, 0.1, 285, false),
  (73, 'Akara', 'West African', 'african', 'vegan', false, 'snack', '4', '20 min + overnight soak', '15 min', 'Nigerian black-eyed pea fritters, light and airy inside, crisp outside.', 'Baking at 200°C for 20 minutes, turning once, saves about 120 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Black-eyed peas, soaked overnight — 1½ cups','Onion, roughly chopped — 1 small','Green chilies — 2','Salt — to taste','Vegetable oil — for deep frying']::text[], ARRAY['Drain and peel the soaked black-eyed peas by rubbing them between your palms; the skins will float off.','Blend the peeled peas, onion, and chilies with as little water as possible into a thick, smooth batter.','Whisk vigorously for several minutes to incorporate air — this makes the fritters light.','Season generously with salt.','Deep-fry spoonfuls in hot oil until golden and cooked through, about 3–4 minutes.','Drain and serve hot, with pap or a chili sauce alongside.']::text[], ARRAY['breakfast']::text[], 'serving', 120, 380, 12.5, 38.2, 18.4, 6.8, 2.1, 72, 0, 185, false),
  (74, 'Jollof Rice (Vegetarian)', 'West African', 'african', 'vegan', false, 'main', '4', '15 min', '40 min', 'West Africa''s iconic one-pot tomato rice, deeply savory and lightly spiced.', 'Reducing the oil to 3 tbsp saves about 45 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Long-grain rice — 2 cups','Tomatoes, blended — 4 large','Red bell pepper, blended — 1','Scotch bonnet or habanero chili — 1 (adjust to taste)','Onion, chopped — 1 large','Tomato paste — 2 tbsp','Vegetable stock — 2 cups','Vegetable oil — 4 tbsp','Bay leaves — 2','Mixed dried herbs — 1 tsp','Salt — to taste','Mixed vegetables (peas, carrots, beans) — 1 cup']::text[], ARRAY['Blend the tomatoes, red pepper, and scotch bonnet into a smooth purée.','Heat oil in a heavy pot; fry onion until golden, about 6 minutes.','Add tomato paste and cook 2 minutes; add the blended tomato purée.','Cook the tomato base, stirring frequently, until darkened and the oil floats to the top — about 15 minutes.','Add the stock, bay leaves, and herbs; season with salt.','Rinse the rice and add to the pot; stir, cover tightly and cook on low heat 25 minutes.','Stir in the mixed vegetables; cover and steam 5 more minutes.']::text[], ARRAY['dinner']::text[], 'plate', 300, 450, 8.5, 58, 15, 3.2, 2.1, 45, 0, 520, false),
  (75, 'Egusi Soup (Vegetarian)', 'West African', 'african', 'vegan', false, 'curry', '4', '15 min', '30 min', 'West African melon seed soup, rich with palm oil and leafy greens.', 'Reducing palm oil to 2 tbsp saves about 55 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Ground egusi (melon seeds) — 1 cup','Spinach or bitter leaf, chopped — 3 cups','Tomatoes, blended — 3','Red bell pepper, blended — 1','Onion, chopped — 1','Palm oil — 3 tbsp','Vegetable stock — 2 cups','Seasoning cubes (vegetarian) — 2','Crayfish substitute (ground dried shiitake) — 1 tbsp','Salt — to taste']::text[], ARRAY['Heat the palm oil in a pot; fry onion until softened.','Add the blended tomatoes and pepper; cook 10 minutes until the oil rises.','Mix the ground egusi with a little water to form a paste; add to the pot in small lumps.','Cook the egusi, stirring, 10 minutes until it changes colour and is cooked through.','Add the stock, dried shiitake, and seasoning; simmer 5 minutes.','Stir in the leafy greens; cook 3–4 minutes until wilted.','Serve with pounded yam, eba, or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 390, 12.5, 18.2, 22.8, 4.1, 3.8, 95, 0.2, 580, false),
  (76, 'Dosa', 'South Indian', 'south_indian', 'vegan', true, 'main', '4', '8 hrs fermentation', '20 min', 'Crisp South Indian rice-lentil crepe, served with chutney and sambar.', 'Using ½ tsp oil per dosa on a non-stick griddle instead of a generous drizzle halves the fat contribution.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Dosa rice — 2 cups','Urad dal — ½ cup','Fenugreek seeds — ½ tsp','Salt — to taste','Water — as needed','Oil or ghee — for cooking']::text[], ARRAY['Soak rice, urad dal, and fenugreek seeds separately for 6–8 hours.','Grind together with water into a smooth, slightly thick batter.','Ferment at room temperature 8–12 hours until risen and slightly tangy.','Season with salt; the batter should pour easily.','Heat a griddle; pour a ladle of batter and spread in a thin circle.','Drizzle a little oil around the edges; cook until the base is golden and crisp.','Serve hot with coconut chutney and sambar.']::text[], ARRAY['breakfast','snack','dinner']::text[], 'serving', 120, 240, 7.2, 28.5, 8.1, 1.8, 2.4, 65, 0.08, 385, false),
  (77, 'Coconut Chutney', 'South Indian, North Indian', 'south_indian', 'vegan', true, 'chutney', '4', '10 min', '5 min', 'Fresh coconut chutney with a mustard-curry leaf tempering.', 'Already a light condiment — portion size is the main variable.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Freshly grated coconut — 1 cup','Green chilies — 2','Ginger — ½ inch','Roasted chana dal — 2 tbsp','Salt — to taste','Water — as needed','Mustard seeds — ½ tsp','Curry leaves — a sprig','Dried red chili — 1','Coconut oil — 1 tsp']::text[], ARRAY['Blend coconut, green chilies, ginger, roasted chana dal, salt, and enough water into a smooth chutney.','Transfer to a bowl.','Heat coconut oil in a small pan; add mustard seeds and let them pop.','Add curry leaves and dried red chili; fry 30 seconds.','Pour this tempering over the chutney.','Serve alongside dosa, idli, or vada.']::text[], ARRAY['snack','dinner','lunch','breakfast']::text[], 'serving', 40, 130, 2.1, 8.5, 10.2, 2.1, 1.2, 32, 0, 180, false),
  (79, 'Avial', 'South Indian', 'south_indian', 'veg', false, 'side', '4', '20 min', '20 min', 'South Indian mixed vegetable curry in a coconut-yogurt sauce.', 'Reducing the coconut oil to 1 tbsp saves about 55 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Mixed vegetables (yam, raw banana, drumstick, carrot, beans, raw mango) — 4 cups','Freshly grated coconut — 1 cup','Green chilies — 3','Cumin seeds — 1 tsp','Turmeric — ½ tsp','Curry leaves — a sprig','Coconut oil — 2 tbsp','Curd (yogurt) — ½ cup','Salt — to taste']::text[], ARRAY['Cook the mixed vegetables in a little water with turmeric and salt until just tender.','Grind coconut, green chilies, and cumin into a coarse paste.','Add the coconut paste to the cooked vegetables; stir and heat through.','Remove from heat; stir in the yogurt.','Heat coconut oil; fry curry leaves and pour over the avial.','Serve warm with rice or rice and dal.']::text[], ARRAY['dinner','lunch']::text[], 'katori', 150, 220, 6.2, 28.5, 10.8, 5.1, 1.8, 92, 0.15, 285, false),
  (80, 'Udon Noodle Soup', 'Japanese', 'asian', 'vegan', false, 'main', '4', '10 min', '20 min', 'Thick udon noodles in a vegetarian kombu-dashi broth.', 'Already a light meal — adding a soft-boiled egg adds ~70 kcal and +6g protein if a more filling bowl is wanted.', 'Traditional', ARRAY['Nut-Free']::text[], ARRAY['Udon noodles — 400g','Kombu dashi (vegetarian) — 5 cups','Soy sauce — 3 tbsp','Mirin — 2 tbsp','Firm tofu, sliced — 200g','Spring onions, sliced — 3','Shiitake mushrooms — 6','Nori strips — garnish','Sesame oil — 1 tsp']::text[], ARRAY['Prepare the kombu dashi by soaking kombu in cold water 30 minutes, then heating gently without boiling; remove kombu.','Season the dashi with soy sauce and mirin.','Cook the udon noodles according to packet instructions; drain.','Add mushrooms to the broth; simmer 5 minutes.','Divide noodles among bowls; ladle hot broth and mushrooms over.','Top with tofu slices, spring onions, and nori; drizzle with sesame oil.']::text[], ARRAY['dinner']::text[], 'bowl', 400, 360, 14.2, 48.5, 8.3, 2.1, 2.8, 185, 0.4, 1240, false),
  (81, 'Agedashi Tofu', 'Japanese', 'asian', 'vegan', false, 'snack', '4', '15 min', '10 min', 'Japanese crispy fried tofu served in a savory dashi broth.', 'Pan-frying instead of deep-frying saves about 50 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Firm tofu — 400g','Potato starch or cornstarch — ½ cup','Vegetable oil — for frying','Kombu dashi — 1½ cups','Soy sauce — 3 tbsp','Mirin — 2 tbsp','Grated daikon radish — 4 tbsp','Spring onions — garnish','Grated ginger — 1 tsp']::text[], ARRAY['Press the tofu between paper towels 20 minutes to remove moisture; cut into cubes.','Combine dashi, soy sauce, and mirin in a saucepan; warm gently.','Dredge the tofu cubes in potato starch to coat.','Deep-fry or pan-fry in hot oil until a crisp, light crust forms, about 2–3 minutes.','Drain and place in serving bowls.','Pour the warm broth over the tofu.','Top with grated daikon, spring onions, and ginger.']::text[], ARRAY['snack']::text[], 'serving', 120, 195, 12.5, 18.2, 6.8, 1.2, 2.1, 145, 0, 520, false),
  (82, 'Korean Matcha Bingsu', 'Korean', 'asian', 'veg', true, 'dessert', '4', '20 min + freezing', 'none', 'Shaved matcha milk ice, topped with red bean paste and mochi.', 'Using oat milk and halving the condensed milk keeps this around 130 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Whole milk or oat milk — 500ml','Sweetened condensed milk — 3 tbsp','Matcha powder — 2 tsp','Red bean paste (anko, store-bought) — ½ cup','Mochi pieces (optional) — ½ cup','Drizzle of condensed milk — to serve']::text[], ARRAY['Whisk together the milk, condensed milk, and matcha until smooth.','Freeze in a shallow tray until solid, about 4 hours (or overnight).','Scrape or shave the frozen block into fine, fluffy ice crystals — a fork works; a blender pulse also works.','Pile the shaved ice into bowls.','Top with red bean paste, mochi pieces if using, and a drizzle of condensed milk.','Serve immediately.']::text[], ARRAY['snack']::text[], 'bowl', 200, 180, 6.2, 22.5, 4.8, 2.1, 1.2, 185, 0.4, 68, false),
  (83, 'Shakshuka', 'North African', 'middle_eastern', 'egg', false, 'main', '4', '10 min', '25 min', 'Eggs poached in a spiced tomato and pepper sauce.', 'Reducing the olive oil to 2 tbsp saves about 45 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Eggs — 6','Canned whole tomatoes — 800g','Red bell pepper, diced — 2','Onion, diced — 1','Garlic, minced — 4 cloves','Cumin — 1 tsp','Paprika — 1 tsp','Cayenne — ¼ tsp','Olive oil — 3 tbsp','Fresh coriander or parsley — garnish','Salt — to taste','Crusty bread — to serve']::text[], ARRAY['Heat olive oil in a wide pan; sauté onion and pepper until soft, about 8 minutes.','Add garlic and spices; cook 1 minute.','Crush in the tomatoes; simmer 15 minutes until thickened.','Make 6 wells in the sauce; crack an egg into each.','Cover and cook until the egg whites are just set but yolks are still runny, about 5–7 minutes.','Scatter with coriander and serve directly from the pan with bread.']::text[], ARRAY['breakfast']::text[], 'serving', 250, 230, 13.5, 12.8, 12.2, 2.1, 2.8, 68, 0.68, 520, false),
  (84, 'Khachapuri', 'Western European', 'european', 'egg', true, 'snack', '4', '40 min + resting', '20 min', 'Georgian cheese bread shaped as a boat, topped with a runny egg.', 'Using half the cheese and skipping the butter saves about 100 kcal/serving.', 'Traditional', ARRAY['Nut-Free','High-Protein']::text[], ARRAY['Bread dough (yeasted, basic recipe) — 500g','Sulguni or feta mixed with mozzarella — 400g','Eggs — 4 (one per boat)','Butter — 2 tbsp']::text[], ARRAY['Divide dough into 4; roll each into an oval shape.','Crumble the cheese and distribute over each oval, leaving a border.','Roll up the long edges to form a boat shape, pinching the ends.','Bake at 220°C (430°F) for 15 minutes until the dough is golden.','Remove from oven; make a small well in the cheese in each boat.','Crack one egg into each well; add a small knob of butter.','Return to the oven 3–4 minutes until the egg white is just set. Serve immediately.']::text[], ARRAY['snack']::text[], 'piece', 200, 480, 18.5, 48.2, 18.3, 1.8, 2.1, 285, 0.8, 520, false),
  (85, 'Tabbouleh', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'salad', '4', '20 min + 30 min rest', 'none', 'A parsley-forward Levantine salad with bulgur, tomato, and lemon.', 'Reducing the olive oil to 2 tbsp saves about 45 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Bulgur wheat, fine — ½ cup','Flat-leaf parsley, finely chopped — 3 cups (packed)','Mint, finely chopped — ½ cup','Tomatoes, finely diced — 3','Spring onions, sliced — 4','Lemon juice — 4 tbsp','Olive oil — 3 tbsp','Salt — to taste']::text[], ARRAY['Pour boiling water over the bulgur (just enough to cover); cover and let it soak 15 minutes until absorbed. Fluff and cool.','The parsley is the star — chop it very finely.','Combine parsley, mint, tomatoes, and spring onions.','Add the cooled bulgur; dress with lemon juice and olive oil.','Season with salt; rest 30 minutes before serving for the flavours to develop.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 200, 6.2, 22.5, 11.3, 5.1, 2.4, 95, 0, 185, false),
  (86, 'Manakish', 'Middle Eastern', 'middle_eastern', 'vegan', true, 'staple', '4', '30 min + resting', '10 min', 'Lebanese flatbread topped with a fragrant za''atar and olive oil paste.', 'Using 3 tbsp oil in the za''atar paste instead of 4 saves about 30 kcal/serving.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Pizza dough or flatbread dough — 500g','Za''atar spice blend — 4 tbsp','Olive oil — 4 tbsp','Optional toppings: sliced tomato, cucumber, fresh mint, feta']::text[], ARRAY['Divide the dough into 4 balls; let rest 20 minutes.','Mix za''atar and olive oil into a thick paste.','Roll each ball into a thin round (~20cm).','Spread the za''atar paste generously over each round.','Bake in a very hot oven (250°C/480°F) or on a hot griddle 6–8 minutes until golden and slightly puffed.','Serve warm with fresh vegetables and optional feta alongside.']::text[], ARRAY['breakfast']::text[], 'piece', 150, 360, 10.5, 42.8, 14.2, 2.1, 2.8, 85, 0.08, 520, false),
  (87, 'Muhammara', 'Middle Eastern', 'middle_eastern', 'vegan', true, 'chutney', '4', '15 min', '20 min (roasting)', 'Roasted red pepper and walnut dip with pomegranate molasses.', 'Reducing walnuts to ½ cup saves about 50 kcal/serving.', 'Traditional', ARRAY['Vegan']::text[], ARRAY['Red bell peppers — 4 large','Walnuts — ¾ cup','Breadcrumbs — ¼ cup','Pomegranate molasses — 2 tbsp','Olive oil — 3 tbsp','Cumin — 1 tsp','Chili flakes — 1 tsp','Lemon juice — 1 tbsp','Salt — to taste']::text[], ARRAY['Roast or char the red peppers until blackened; peel, seed, and cool.','Toast the walnuts lightly in a dry pan.','Blend the peppers, walnuts, breadcrumbs, pomegranate molasses, cumin, chili, and lemon juice.','With the blender running, drizzle in the olive oil.','Taste; adjust heat and tartness with extra chili or molasses.','Serve with warm pita or flatbread; drizzle with oil and scatter a few whole walnuts on top.']::text[], ARRAY['snack']::text[], 'serving', 60, 240, 6.2, 18.5, 15.8, 3.2, 1.8, 42, 0, 185, false),
  (88, 'Tacos de Frijoles', 'Mexican', 'latin_american', 'veg', false, 'main', '4', '15 min', '15 min', 'Mexican bean tacos with mashed avocado and salsa.', 'Using just half the avocado saves about 80 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','High-Protein']::text[], ARRAY['Corn tortillas — 12 small','Pinto or black beans, cooked — 2 cups','Onion, diced — 1','Garlic, minced — 2 cloves','Cumin — 1 tsp','Chipotle in adobo (or chili powder) — 1 tsp','Avocado, mashed — 1','Salsa or fresh tomato — ½ cup','Cotija or feta — ¼ cup','Lime — to serve','Coriander — garnish']::text[], ARRAY['Heat a little oil; fry onion and garlic until soft.','Add the beans, cumin, and chipotle; cook 5–8 minutes, mashing some beans to create a slightly chunky paste.','Warm the tortillas on a dry griddle.','Spread a little mashed avocado on each tortilla; add a spoonful of beans.','Top with salsa, crumbled cheese, and coriander.','Serve with lime wedges.']::text[], ARRAY['dinner']::text[], 'plate', 300, 420, 14.2, 48.5, 12.8, 8.3, 2.4, 95, 0.15, 385, false),
  (89, 'Agua Fresca de Jamaica', 'Mexican', 'latin_american', 'vegan', true, 'drink', '4', '10 min + chilling', '10 min', 'A tart Mexican hibiscus cooler, served over ice.', 'Halving the sugar brings this to roughly 30 kcal/serving — still pleasantly tart.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Dried hibiscus flowers — ½ cup','Water — 4 cups','Sugar — 2 tbsp','Lime juice — 2 tbsp','Fresh mint — optional','Ice — to serve']::text[], ARRAY['Boil 2 cups water; steep the hibiscus flowers 10 minutes.','Strain the flowers; dissolve the sugar in the hot liquid.','Add the remaining 2 cups cold water and lime juice.','Chill well; serve over ice with fresh mint.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 55, 0.3, 14.2, 0.1, 1.8, 0.4, 12, 0, 2, false),
  (90, 'Elote', 'Mexican', 'latin_american', 'egg', true, 'snack', '4', '5 min', '10 min', 'Mexican street corn on the cob, charred and dressed with mayo and cheese.', 'Swapping mayo for Greek yogurt saves about 60 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Corn on the cob — 4','Mayonnaise — 3 tbsp','Cotija or feta, crumbled — ½ cup','Chili powder — 1 tsp','Lime — 2, cut into wedges','Salt — to taste','Fresh coriander — garnish']::text[], ARRAY['Grill or boil the corn until cooked and slightly charred, about 8–10 minutes.','While hot, brush each cob with mayonnaise.','Roll in or sprinkle with crumbled cheese.','Dust with chili powder and salt.','Serve immediately with lime wedges and coriander.']::text[], ARRAY['snack']::text[], 'piece', 150, 210, 8.5, 22, 10.5, 2.5, 0.8, 85, 0.25, 320, false),
  (91, 'Ceviche de Coliflor', 'South American', 'latin_american', 'vegan', false, 'salad', '4', '20 min + 30 min marinating', '5 min', 'Peruvian cauliflower ceviche, bright with lime and ají amarillo.', 'Already a very light dish — the main calorie variable is the accompaniment.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free','Jain-Friendly','Low-Carb']::text[], ARRAY['Cauliflower, cut into small florets — 1 head','Lime juice — ½ cup','Red onion, thinly sliced — 1','Fresh coriander, chopped — ½ cup','Ají amarillo paste (or orange chili) — 1 tbsp','Celery, sliced — 2 stalks','Garlic, minced — 1 clove','Salt — to taste','Cancha (toasted corn) or tortilla chips — to serve']::text[], ARRAY['Lightly blanch the cauliflower florets 2–3 minutes; drain and cool.','Whisk together lime juice, ají amarillo paste, garlic, and salt.','Add the cauliflower, red onion, celery, and coriander; toss well.','Marinate 30 minutes — the lime juice will slightly "cook" the surfaces.','Serve with cancha or tortilla chips alongside.']::text[], ARRAY['snack']::text[], 'bowl', 150, 120, 3.2, 14.8, 0.8, 2.9, 0.7, 28, 0, 156, false),
  (92, 'Empanadas de Queso', 'South American', 'latin_american', 'egg', false, 'snack', '4', '30 min', '20 min', 'Cheese-filled pastries with caramelized onion and olive.', 'Using a lower-fat cheese and skipping the olives saves about 60 kcal/serving.', 'Traditional', ARRAY['Nut-Free','High-Protein']::text[], ARRAY['Empanada dough discs (store-bought or homemade) — 12','Mozzarella or Monterey Jack, grated — 250g','Onion, caramelized — 1','Green olives (optional) — 12','Egg, beaten — 1 (for egg wash)']::text[], ARRAY['Preheat oven to 200°C (390°F).','Combine the grated cheese and caramelized onion.','Place a spoonful of filling and one olive (if using) on each dough disc.','Fold the dough over; crimp the edges firmly with a fork to seal.','Brush with beaten egg.','Bake 18–20 minutes until golden.','Cool slightly before serving — the filling is very hot.']::text[], ARRAY['snack']::text[], 'serving', 180, 480, 18.5, 42.8, 18.2, 2.1, 2.4, 285, 0.85, 685, false),
  (93, 'Mapo Tofu (Vegetarian)', 'Chinese', 'asian', 'vegan', false, 'curry', '4', '10 min', '15 min', 'Sichuan-style silken tofu in a spicy, numbing bean-paste sauce.', 'Using firm tofu instead of silken gives more structure and fewer calories — roughly 240 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Silken or soft tofu — 600g','Doubanjiang (spicy fermented bean paste) — 2 tbsp','Fermented black beans — 1 tbsp','Garlic, minced — 3 cloves','Ginger, minced — 1 tbsp','Sichuan peppercorns, ground — 1 tsp','Vegetable stock — 1 cup','Cornstarch — 1 tbsp (mixed with 2 tbsp water)','Sesame oil — 1 tsp','Vegetable oil — 2 tbsp','Spring onions — garnish']::text[], ARRAY['Cut the tofu into 2cm cubes; blanch briefly in lightly salted water; drain carefully.','Heat oil; fry the doubanjiang and fermented black beans 2 minutes until fragrant and the oil turns red.','Add garlic and ginger; cook 1 minute.','Add the stock; bring to a simmer.','Gently slide in the tofu; simmer 3–4 minutes.','Stir in the cornstarch slurry to thicken.','Finish with ground Sichuan pepper and sesame oil; garnish with spring onions. Serve over rice.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 15.2, 12.8, 11.5, 1.2, 2.8, 185, 0, 580, false),
  (94, 'Dim Sum — Vegetable Steamed Dumplings', 'Chinese', 'asian', 'vegan', false, 'snack', '4', '40 min', '10 min', 'Har Gow-style steamed dumplings filled with cabbage, carrot, and mushroom.', 'Already a naturally light dish — pan-frying the bases in a little oil (potsticker style) adds about 40 kcal/serving for a crisp texture.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Dumpling wrappers — 16','Cabbage, finely chopped — 1 cup','Carrot, grated — 1','Shiitake mushrooms, finely diced — 1 cup','Spring onions — 3','Ginger, minced — 1 tsp','Soy sauce — 2 tbsp','Sesame oil — 1 tsp','Cornstarch — 1 tbsp','Dipping sauce (soy, vinegar, ginger) — to serve']::text[], ARRAY['Mix cabbage and carrot with a pinch of salt; squeeze out excess moisture.','Combine with mushrooms, spring onions, ginger, soy sauce, sesame oil, and cornstarch.','Place a spoonful of filling in the centre of each wrapper.','Moisten the edges and pleat/fold to seal.','Steam over boiling water 8–10 minutes until wrappers are translucent and filling is cooked.','Serve immediately with the dipping sauce.']::text[], ARRAY['snack']::text[], 'serving', 120, 220, 8.5, 28, 3.5, 2, 1.8, 45, 0.3, 420, false),
  (95, 'Hot and Sour Soup (Vegetarian)', 'Chinese', 'asian', 'egg', false, 'soup', '4', '15 min', '15 min', 'Classic Chinese soup, tangy with vinegar and laced with silky egg ribbons.', 'Already a light soup — pairs well with a more substantial main dish.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Low-Carb']::text[], ARRAY['Vegetable stock — 5 cups','Firm tofu, julienned — 150g','Shiitake mushrooms, sliced — 1 cup','Bamboo shoots, julienned — ½ cup','Eggs, beaten — 2','Rice vinegar — 3 tbsp','Soy sauce — 2 tbsp','White pepper — 1 tsp','Cornstarch — 3 tbsp (mixed with water)','Sesame oil — 1 tsp','Spring onions — garnish']::text[], ARRAY['Bring the stock to a boil; add mushrooms and bamboo shoots; simmer 5 minutes.','Add the tofu and soy sauce.','Stir in the cornstarch slurry gradually until the soup thickens.','Add the rice vinegar and white pepper — taste and adjust; it should be both hot and sour.','Slowly pour in the beaten eggs in a thin stream while stirring to create egg ribbons.','Drizzle with sesame oil; garnish with spring onions.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 140, 12.5, 10.2, 5.8, 1.2, 2.8, 185, 0.35, 680, false),
  (96, 'Rendang Sayur', 'Southeast Asian', 'asian', 'vegan', false, 'curry', '4', '20 min', '45 min', 'Indonesian vegetable rendang, slow-cooked in coconut milk until deeply dark.', 'Using light coconut milk and reducing it by 25% saves about 80 kcal/serving.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Jackfruit (young, canned) or mixed root vegetables — 600g','Coconut milk — 2 cups','Lemongrass, bruised — 2 stalks','Kaffir lime leaves — 4','Galangal or ginger, sliced — 3 slices','Shallots — 4','Garlic — 4 cloves','Red chilies — 3','Ground coriander — 1 tsp','Ground cumin — 1 tsp','Turmeric — ½ tsp','Kerisik (toasted coconut) or desiccated coconut — 3 tbsp','Vegetable oil — 2 tbsp','Salt — to taste']::text[], ARRAY['Blend shallots, garlic, chilies, galangal, and the ground spices into a paste.','Heat oil in a heavy pot; fry the spice paste until fragrant and darkened, about 5 minutes.','Add the jackfruit or vegetables, lemongrass, and lime leaves; stir to coat.','Add coconut milk; bring to a simmer.','Cook uncovered on medium-low heat 40–45 minutes, stirring frequently, until the liquid reduces and the mixture turns dark and almost dry.','Stir in the kerisik; season with salt.','Serve with steamed rice.']::text[], ARRAY['dinner']::text[], 'bowl', 220, 380, 8.5, 32, 18.5, 5.2, 2.1, 95, 0, 520, false),
  (97, 'Laksa (Vegetarian)', 'Southeast Asian', 'asian', 'egg', false, 'main', '4', '20 min', '25 min', 'Malaysian coconut noodle soup with fried tofu and bean sprouts.', 'Using light coconut milk and halving the laksa paste saves about 100 kcal/serving.', 'Traditional', ARRAY['Gluten-Free','Nut-Free']::text[], ARRAY['Rice noodles — 300g','Coconut milk — 1½ cups','Vegetable stock — 3 cups','Laksa paste (vegetarian) — 4 tbsp','Firm tofu, fried — 200g','Bean sprouts — 1 cup','Spring onions — 3','Boiled eggs (optional) — 4','Fresh coriander and mint — garnish','Lime — to serve']::text[], ARRAY['Soak rice noodles in hot water until pliable; drain.','Fry the laksa paste in a little oil 2–3 minutes until very fragrant.','Add stock and bring to a boil; add coconut milk and simmer 10 minutes.','Add the fried tofu; simmer 3 minutes.','Blanch the bean sprouts briefly in the broth.','Divide noodles among bowls; ladle over the hot broth.','Top with tofu, bean sprouts, spring onions, halved boiled egg if using, and herbs.','Serve with lime on the side.']::text[], ARRAY['dinner']::text[], 'bowl', 400, 490, 18.5, 42.3, 22.8, 3.2, 4.1, 185, 0.6, 856, false),
  (98, 'Onam Sadya', 'South Indian', 'south_indian', 'veg', true, 'main', '6', '2 hrs', '2 hrs', 'A festival banana-leaf feast — the full Kerala Sadya, showcased as one entry.', 'A full Sadya is a once-a-year festival meal, not calibrated against daily intake targets — documenting it honestly without adjusting the tradition.', 'Traditional', ARRAY['Gluten-Free','Nut-Free','Jain-Friendly']::text[], ARRAY['Parippu (green gram dal with coconut and ghee) — for rice course','Avial (mixed vegetable coconut curry) — 1 batch (see Avial)','Thoran (dry coconut-tempered vegetables) — beans, cabbage, or raw banana','Olan (white pumpkin and cowpeas in thin coconut milk) — 1 batch','Pulissery (ripe mango or cucumber in spiced yogurt curry) — 1 batch','Pachadi (pineapple or cucumber raita-style accompaniment) — 1 batch','Pickle and pappadom — to serve','Payasam (ada/rice and parippu/lentil, two types) — for dessert','Steamed rice — as needed']::text[], ARRAY['Prepare each component separately over the course of the morning — Parippu, Avial, Thoran, Olan, Pulissery, and Pachadi.','Cook the two payasams last, since they hold well once made.','Wash and lay out banana leaves, tip pointing left, one per diner.','Arrange each dish in its traditional position on the leaf — pickle and pappadom near the front, curries along the sides, rice in the centre.','Serve rice with Parippu and ghee first, then work through the remaining dishes as the meal progresses.','Finish with both payasams, served last.']::text[], ARRAY['lunch']::text[], 'plate', 900, 1900, 42, 245, 68, 18, 8.5, 320, 0.8, 480, false),
  (99, 'Pani Puri', 'North Indian', 'north_indian', 'vegan', false, 'snack', '4', '30 min', '20 min', 'Crisp hollow puris filled with spiced potato and dipped in tangy mint water.', 'The pani itself adds almost nothing to the calorie count — most calories come from the fried puri shells.', 'Traditional', ARRAY['Vegan','Nut-Free']::text[], ARRAY['Semolina (sooji) — ½ cup','Whole wheat flour — 2 tbsp','Water — as needed','Oil — for deep frying','Boiled potatoes, mashed — 2','Chickpeas, cooked — ½ cup','Chaat masala — 1 tsp','Cumin powder — ½ tsp','Salt — to taste','Fresh mint leaves — 1 cup','Fresh coriander — ½ cup','Green chilies — 2','Tamarind pulp — 2 tbsp','Cumin, roasted — 1 tsp','Black salt — ½ tsp','Sugar — 1 tsp']::text[], ARRAY['Knead semolina and flour with water into a stiff dough; rest 20 minutes.','Roll very thin; cut into small circles (3–4 cm). Deep-fry until puffed and crisp.','Blend all pani ingredients (mint, coriander, chilies, tamarind, roasted cumin, black salt, sugar, water) until smooth; strain and chill.','Combine the potato filling with chickpeas and seasonings.','To serve, crack a small hole in each puri, fill with a spoonful of filling, and dip into the spiced pani just before eating.']::text[], ARRAY['snack']::text[], 'serving', 120, 210, 6.2, 28.5, 5.8, 4.1, 2.3, 48, 0, 380, false),
  (100, 'Mole Verde', 'Mexican', 'latin_american', 'vegan', false, 'curry', '4', '30 min', '40 min', 'Oaxacan-style green mole sauce, complex and herby, served over vegetables.', 'Reducing the pumpkin seeds to ⅓ cup saves about 50 kcal/serving — the flavour remains complex.', 'Traditional', ARRAY['Vegan','Gluten-Free','Nut-Free']::text[], ARRAY['Tomatillos — 500g','Poblano or green peppers — 3','Pumpkin seeds (pepitas) — ½ cup','Fresh coriander — 1 cup','Epazote or fresh herb mix — 2 tbsp','Onion — 1','Garlic — 4 cloves','Vegetable stock — 2 cups','Vegetable oil — 3 tbsp','Cumin — 1 tsp','Mixed vegetables (zucchini, green beans, chayote) — 3 cups','Corn tortillas — to serve','Salt — to taste']::text[], ARRAY['Char the tomatillos and poblano peppers under a broiler until blistered; peel the peppers.','Toast the pumpkin seeds in a dry pan until they begin to pop.','Blend the tomatillos, peppers, toasted seeds, coriander, epazote, onion, and garlic into a smooth sauce.','Heat oil in a heavy pot; add the sauce all at once — it will sputter.','Fry the sauce, stirring constantly, 5–8 minutes until darkened and thickened.','Add the stock; simmer 20 minutes until the mole coats a spoon.','Add the mixed vegetables; cook until tender, 10–15 minutes.','Season with salt and cumin; serve over rice with warm tortillas.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 320, 12.5, 28, 12.5, 5.2, 3.8, 145, 0, 380, false),
  (101, 'Idli with Sambar & Chutney', 'South Indian', 'south_indian', 'veg', false, 'main', '2', '5 min', '15 min', 'Pillowy steamed rice cakes served with tangy sambar and cooling coconut chutney — the quintessential South Indian morning.', 'Overnight batter stored in the fridge develops a pleasant tang and gives a lighter, more airy idli.', 'Traditional', NULL, ARRAY['6 idlis (from fermented batter)','1 cup sambar (reheated)','3 tbsp coconut chutney','1 tsp ghee (optional)','Fresh coriander to garnish']::text[], ARRAY['Steam idlis in a greased mould for 12–15 min until spongy.','Heat sambar in a small pan, adding a splash of water if too thick.','Prepare coconut chutney by blending fresh coconut, green chilli, ginger and tempering with mustard seeds.','Arrange idlis on a plate and drizzle ghee if using.','Serve with sambar in a bowl and chutney on the side.']::text[], ARRAY['breakfast','dinner','snack']::text[], 'plate', 250, 160, 5.2, 28.4, 3.1, 2.8, 1.6, 78, 0.18, 385, false),
  (102, 'Appam with Coconut Milk Stew', 'South Indian', 'south_indian', 'vegan', false, 'main', '2', '8 hrs', '20 min', 'Lacy fermented rice crepes with crisp edges and a soft centre, paired with a fragrant, mild coconut milk vegetable stew.', 'A teaspoon of coconut cream stirred into the stew just before serving adds richness without extra cooking.', 'Traditional', NULL, ARRAY['1 cup appam batter (fermented overnight)','1 coconut, grated (for milk)','2 medium potatoes, cubed','1 carrot, sliced','1 cup green beans, trimmed','2 green chillies, slit','1 sprig curry leaves','Salt to taste']::text[], ARRAY['Extract thick and thin coconut milk from grated coconut.','Cook potatoes, carrots and beans in thin coconut milk until tender.','Add thick coconut milk, green chillies, curry leaves and salt; simmer 5 min.','Heat appam pan; pour a ladle of batter, swirl to coat, cover and cook 2 min until edges crisp.','Serve hot appams alongside the warm coconut stew.']::text[], ARRAY['breakfast','snack','dinner']::text[], 'plate', 300, 290, 8.5, 42, 8.5, 4.2, 1.8, 95, 0, 320, false),
  (103, 'Rava Upma with Vegetables', 'South Indian', 'south_indian', 'veg', false, 'main', '2', '5 min', '15 min', 'A quick semolina porridge tempered with mustard seeds, curry leaves and crunchy cashews, studded with seasonal vegetables.', 'Always add the rava to boiling water (not cold) and stir immediately to guarantee a lump-free upma.', 'Traditional', NULL, ARRAY['1 cup fine semolina (rava)','1 medium onion, finely sliced','1 tomato, chopped','½ cup mixed vegetables (peas, carrot, beans)','1 tsp mustard seeds','8 cashews','8 curry leaves','1 tsp ghee','Salt and lemon juice to taste']::text[], ARRAY['Dry-roast semolina in a pan until fragrant and lightly golden; set aside.','Heat ghee, splutter mustard seeds and curry leaves, add cashews and fry until golden.','Add onion and sauté until translucent; add tomato and vegetables, cook 3 min.','Pour in 2 cups boiling water, add salt and stir in roasted semolina steadily.','Stir vigorously to prevent lumps, cover and cook 3 min; finish with lemon juice.']::text[], ARRAY['breakfast','dinner','snack']::text[], 'bowl', 200, 220, 7.2, 32.5, 5.8, 2.1, 1.8, 45, 0.1, 185, false),
  (104, 'Kootu (Vegetable & Lentil Curry)', 'South Indian', 'south_indian', 'vegan', false, 'dal', '3', '10 min', '25 min', 'A thick, earthy South Indian curry of vegetables and chana dal bound with a freshly ground coconut paste — wholesome and deeply satisfying.', 'Add the coconut paste at the end and simmer briefly — long cooking dulls its fresh flavour.', 'Traditional', NULL, ARRAY['1 cup yam or raw banana, diced','½ cup chana dal, soaked 30 min','½ cup fresh coconut, grated','1 tsp cumin seeds','2 dried red chillies','1 tsp black pepper','1 tsp mustard seeds','8 curry leaves','Salt to taste']::text[], ARRAY['Pressure cook chana dal with a pinch of turmeric until soft but not mushy.','Boil yam or banana in salted water until just tender; drain.','Grind coconut, cumin, pepper and dried chillies to a smooth paste.','Combine cooked dal, vegetables and coconut paste; simmer 8 min until thick.','Temper with mustard seeds and curry leaves in oil; pour over and mix.']::text[], ARRAY['dinner','lunch']::text[], 'bowl', 150, 210, 8.2, 28.5, 4.8, 5.2, 2.1, 65, 0, 180, false),
  (105, 'Kerala Vegetable Stew (Ishtoo)', 'South Indian', 'south_indian', 'vegan', false, 'curry', '3', '10 min', '20 min', 'A silky, mildly spiced coconut milk stew fragrant with whole spices — Kerala''s answer to the Sunday comfort dish.', 'Never boil after adding thick coconut milk — gentle heat keeps it silky and prevents curdling.', 'Traditional', NULL, ARRAY['2 medium potatoes, cubed','1 carrot, sliced','1 cup green beans, cut','1 cup thick coconut milk','½ cup thin coconut milk','1 onion, sliced','3 green chillies, slit','1 inch ginger, julienned','2 cloves, 1 cinnamon stick, 3 cardamoms','Salt to taste']::text[], ARRAY['Heat coconut oil; add whole spices and sauté until fragrant.','Add onion, ginger and green chillies; cook until onion softens.','Add vegetables and thin coconut milk; simmer until vegetables are tender.','Pour in thick coconut milk and salt; heat gently without boiling.','Serve with appam or idiyappam.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 240, 3.2, 28.5, 12.8, 4.1, 1.4, 52, 0, 310, false),
  (106, 'Puliyodarai (Tamarind Rice)', 'South Indian', 'south_indian', 'vegan', true, 'main', '2', '10 min', '20 min', 'Bold, tangy tamarind rice tempered with sesame oil and peanuts — a temple staple and beloved travel food.', 'The tamarind paste can be made in bulk and refrigerated for a week — mix with hot rice anytime.', 'Traditional', NULL, ARRAY['2 cups cooked rice','Lemon-sized ball of tamarind','2 tbsp sesame oil','1 tsp mustard seeds','2 dried red chillies','2 tbsp roasted peanuts','1 tsp chana dal','½ tsp turmeric','8 curry leaves','Salt to taste']::text[], ARRAY['Soak tamarind in ½ cup warm water; squeeze and strain to extract pulp.','Heat sesame oil; splutter mustard seeds, chana dal, red chillies and curry leaves.','Add tamarind extract, turmeric and salt; cook until the paste thickens and oil separates.','Fold in cooked rice and peanuts; mix gently to coat every grain.','Rest 10 min before serving so the flavours meld.']::text[], ARRAY['dinner','lunch','breakfast']::text[], 'plate', 250, 320, 6.5, 42, 12, 2.5, 2.1, 65, 0, 380, false),
  (107, 'Kadala Curry (Black Chickpea Curry)', 'South Indian', 'south_indian', 'vegan', false, 'curry', '3', '8 hrs', '30 min', 'Deep, robust Kerala-style black chickpea curry in a roasted coconut and spice gravy — the classic companion to Puttu.', 'Roasting the coconut until amber rather than just pale gives the gravy its characteristic deep colour and nutty flavour.', 'Traditional', NULL, ARRAY['1 cup black chickpeas (soaked overnight)','½ cup fresh coconut, grated','2 onions, sliced','2 tomatoes, chopped','1 tsp coriander powder','½ tsp chilli powder','½ tsp garam masala','1 tsp ginger-garlic paste','Coconut oil and salt']::text[], ARRAY['Pressure cook soaked chickpeas with salt until tender (3–4 whistles).','Dry-roast grated coconut until golden; grind to a smooth paste.','Sauté onions until deep golden; add ginger-garlic paste, tomatoes and spice powders.','Add cooked chickpeas and coconut paste; simmer 10 min until gravy thickens.','Finish with coconut oil tempering of mustard seeds and curry leaves.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 12.5, 32.8, 9.2, 8.4, 3.2, 78, 0, 385, false),
  (108, 'Masala Bajji (Vegetable Fritters)', 'South Indian', 'south_indian', 'vegan', false, 'snack', '2', '10 min', '15 min', 'Crisp gram-flour fritters with a spiced vegetable filling — the quintessential South Indian rainy-day snack.', 'A pinch of baking soda in the batter gives a lighter, crisper crust.', 'Traditional', NULL, ARRAY['2 medium potatoes or 1 raw banana, sliced','1 cup gram flour (besan)','½ tsp chilli powder','¼ tsp turmeric','½ tsp ajwain (carom seeds)','Salt to taste','Oil for deep frying','Coconut chutney to serve']::text[], ARRAY['Whisk gram flour with chilli, turmeric, ajwain, salt and enough water to make a thick batter.','Heat oil to 175°C.','Dip vegetable slices into batter, coating evenly.','Fry in batches until golden and crisp, about 3–4 min per side.','Drain on paper and serve hot with coconut chutney.']::text[], ARRAY['snack']::text[], 'serving', 100, 220, 6.2, 22.5, 10.8, 2.1, 1.8, 42, 0, 180, false),
  (109, 'Paniyaram', 'South Indian', 'south_indian', 'vegan', false, 'snack', '2', '5 min', '15 min', 'Crispy-outside, fluffy-inside dumplings made from fermented rice batter, cooked in a special mould — a clever way to use leftover dosa batter.', 'Keep the heat at medium-low after adding the batter — too high and the outside burns before the centre cooks through.', 'Traditional', NULL, ARRAY['1 cup dosa or idli batter','1 small onion, finely chopped','2 tbsp fresh coconut, grated','1 green chilli, minced','8 curry leaves, chopped','½ tsp mustard seeds','1 tsp oil plus oil for greasing']::text[], ARRAY['Temper mustard seeds and curry leaves in oil; add onion, chilli and coconut; sauté 3 min.','Stir tempered mix into the batter.','Heat a paniyaram mould; grease each cavity with a drop of oil.','Fill each cavity ¾ full; cover and cook on medium heat 4 min until base is golden.','Flip with a skewer and cook 2 min more; serve with tomato chutney.']::text[], ARRAY['snack','dinner']::text[], 'serving', 120, 180, 5.2, 28.4, 5.8, 1.2, 1.1, 42, 0.1, 156, false),
  (110, 'Sundal (Spiced Chickpeas)', 'South Indian', 'south_indian', 'vegan', true, 'snack', '2', '5 min', '10 min', 'A light, protein-rich South Indian stir-fry of boiled legumes tempered with coconut and spices — a Navratri staple and everyday snack.', 'Works equally well with black-eyed peas, kidney beans or cooked corn — use whatever legume you have.', 'Traditional', NULL, ARRAY['1 cup boiled chickpeas (or canned, drained)','3 tbsp fresh coconut, grated','1 tsp mustard seeds','1 dried red chilli','8 curry leaves','1 tsp oil','½ tsp asafoetida','Salt and lime juice to taste']::text[], ARRAY['Heat oil; splutter mustard seeds, dried chilli and curry leaves.','Add asafoetida, then chickpeas; toss well to coat in the tempering.','Add salt and coconut; stir-fry 2 min on high heat.','Finish with a squeeze of lime juice.','Serve warm or at room temperature.']::text[], ARRAY['snack','breakfast']::text[], 'bowl', 100, 150, 7.2, 16.8, 4.5, 3.8, 2.1, 42, 0, 185, false),
  (111, 'Poha (Flattened Rice Stir-Fry)', 'North Indian', 'north_indian', 'vegan', false, 'main', '2', '10 min', '15 min', 'Light, golden and fragrant — this central-Indian breakfast of flattened rice tossed with mustard seeds, peanuts and a squeeze of lemon never disappoints.', 'Rinsing just until soft and draining immediately keeps each flake separate rather than mushy.', 'Traditional', NULL, ARRAY['2 cups thick poha (flattened rice)','1 medium onion, finely sliced','2 green chillies, slit','½ tsp turmeric','1 tsp mustard seeds','2 tbsp roasted peanuts','8 curry leaves','1 tsp sugar','Lemon juice and coriander to finish']::text[], ARRAY['Rinse poha under cold water until just soft; drain and set aside — do not over-soak.','Heat oil; splutter mustard seeds and curry leaves.','Add onion and chillies; sauté until onion softens.','Add turmeric, sugar and peanuts; toss well, then fold in poha.','Season with salt and lemon juice; garnish with coriander and serve.']::text[], ARRAY['breakfast']::text[], 'plate', 200, 280, 5.2, 48.5, 6.8, 2.1, 1.8, 45, 0.1, 185, false),
  (112, 'Besan Chilla (Gram Flour Crepe)', 'North Indian', 'north_indian', 'vegan', false, 'main', '2', '5 min', '15 min', 'A protein-packed savoury crepe made from spiced gram flour — quicker than a dosa, just as satisfying.', 'Resting the batter 5 min after mixing allows the flour to hydrate and the chilla to cook more evenly.', 'Traditional', NULL, ARRAY['1 cup gram flour (besan)','½ onion, finely chopped','1 tomato, finely chopped','2 green chillies, minced','¼ tsp turmeric','½ tsp cumin powder','Salt to taste','Oil for cooking','Mint chutney to serve']::text[], ARRAY['Whisk gram flour with all vegetables, spices and salt; add water to make a pourable batter.','Heat a non-stick pan over medium heat; brush with a little oil.','Pour a ladleful of batter and spread into a thin circle.','Drizzle oil around edges; cook 2–3 min until edges lift, then flip and cook 1 min.','Serve immediately with mint chutney or pickled onions.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 230, 8.5, 24.2, 7.8, 3.2, 2.1, 42, 0, 185, false),
  (113, 'Sabudana Khichdi', 'North Indian', 'north_indian', 'veg', false, 'main', '2', '4 hrs', '15 min', 'Soft, chewy tapioca pearls tossed with roasted peanuts, green chillies and cumin — a popular fasting dish that doubles as a perfect weekend breakfast.', 'The key is the right soak: pearls should be just separate and non-sticky — neither crunchy nor a paste.', 'Traditional', NULL, ARRAY['1 cup sabudana (tapioca pearls)','½ cup roasted peanuts, coarsely crushed','2 medium potatoes, boiled and cubed','3 green chillies, minced','1 tsp cumin seeds','1 tsp lemon juice','1 tsp sugar','Salt and ghee to taste','Fresh coriander to garnish']::text[], ARRAY['Soak sabudana in just enough water to cover for 4–6 hours; drain and fluff with a fork.','Heat ghee; splutter cumin seeds, then add chillies and potatoes; toss 3 min.','Add sabudana and peanuts; fold gently to avoid breaking the pearls.','Cook uncovered 5 min, stirring occasionally, until pearls turn translucent.','Season with salt, sugar and lemon juice; garnish with coriander.']::text[], ARRAY['breakfast']::text[], 'bowl', 200, 310, 8.5, 38.2, 14.8, 3.2, 2.1, 42, 0.02, 285, false),
  (114, 'Methi Thepla', 'North Indian', 'north_indian', 'veg', true, 'staple', '2', '15 min', '20 min', 'Thin, pliable Gujarati flatbreads enriched with fresh fenugreek leaves and yoghurt — perfect for breakfast or packed for travel.', 'Theplas stay soft for 2–3 days when stored between layers of foil — ideal for packed lunches.', 'Traditional', NULL, ARRAY['1 cup whole wheat flour','½ cup fresh methi (fenugreek) leaves, chopped','2 tbsp yoghurt','½ tsp turmeric','½ tsp chilli powder','½ tsp cumin powder','1 tsp sesame seeds','Oil and salt to taste']::text[], ARRAY['Mix all ingredients except oil with enough water to form a soft, pliable dough; rest 10 min.','Divide into equal balls; roll each out thinly.','Heat a tawa over medium-high heat; cook thepla 1 min per side, pressing lightly.','Apply a thin smear of oil; flip and cook until golden spots appear.','Serve with yoghurt, mango pickle or green chutney.']::text[], ARRAY['breakfast','dinner']::text[], 'piece', 100, 260, 8.5, 32, 8.5, 5.2, 3.8, 95, 0.18, 320, false),
  (115, 'Kadhi Pakora', 'North Indian', 'north_indian', 'veg', false, 'dal', '3', '20 min', '30 min', 'Tangy yoghurt-based gravy with gram flour dumplings — a North Indian comfort classic that tastes better the next day.', 'Constant stirring during the first 15 minutes of cooking prevents the yoghurt from splitting.', 'Traditional', NULL, ARRAY['2 cups yoghurt, whisked','3 tbsp gram flour (besan) for kadhi','1 tsp turmeric','1 tsp chilli powder','For pakoras: ½ cup besan, 1 onion sliced','Tempering: ghee, cumin, dried chilli, mustard seeds, hing','Salt to taste','Fresh coriander to garnish']::text[], ARRAY['Whisk yoghurt, besan, turmeric, chilli and salt into a smooth batter; thin with 2 cups water.','Cook yoghurt mixture on medium heat, stirring constantly, for 20 min until thick.','Mix onion pakora batter; drop spoonfuls into hot oil and fry until golden; drain.','Add pakoras to the kadhi; simmer 8 min so they soak up the gravy.','Finish with a sizzling tempering of ghee, cumin, mustard seeds and dried chilli poured over the top.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 290, 12.5, 22.8, 10.2, 2.1, 1.8, 185, 0.35, 380, false),
  (116, 'Vegetable Biryani', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '20 min', '40 min', 'Fragrant basmati rice layered with spiced vegetables, caramelised onions and saffron milk — a celebratory one-pot that is worth every minute.', 'Parboiling rice to exactly 70% cooked is the secret — it finishes on dum without going mushy.', 'Traditional', NULL, ARRAY['2 cups basmati rice, soaked 30 min','2 cups mixed vegetables (carrot, peas, potato, beans)','2 onions, thinly sliced','1 cup yoghurt','2 tsp biryani masala','1 tsp saffron in 3 tbsp warm milk','Whole spices: cloves, cardamom, bay leaf','Ghee, mint, coriander and salt']::text[], ARRAY['Fry onions in ghee until deep golden and crisp; drain (these are fried onions for topping).','Marinate vegetables in yoghurt, biryani masala, chilli and ginger-garlic paste for 15 min.','Parboil soaked rice with whole spices and salt until 70% cooked; drain.','Layer marinated vegetables then rice in a heavy pot; top with fried onions, saffron milk, mint and ghee.','Seal and cook on dum (very low heat) for 20 min; rest 5 min before opening.']::text[], ARRAY['lunch']::text[], 'plate', 300, 380, 9.2, 52.1, 8.4, 3.8, 1.9, 78, 0.18, 285, false),
  (117, 'Dal Makhani', 'North Indian', 'north_indian', 'veg', false, 'dal', '3', '8 hrs', '60 min', 'Slow-simmered whole black lentils in a rich, buttery tomato gravy — the signature dish of the North Indian restaurant tradition.', 'Restaurant-quality dal makhani comes from slow simmering for an hour or more — do not rush this step.', 'Traditional', NULL, ARRAY['1 cup whole black lentils (urad dal)','¼ cup rajma (kidney beans)','1 cup tomato purée','2 tbsp butter','1 tbsp cream','1 tsp ginger-garlic paste','1 tsp chilli powder','½ tsp garam masala','Salt to taste']::text[], ARRAY['Soak lentils and rajma overnight; pressure cook until very soft (6–7 whistles).','Mash slightly with the back of a spoon while still in the cooker.','Heat butter; add ginger-garlic paste, then tomato purée; cook until oil surfaces.','Add cooked dal, chilli powder, salt and 1 cup water; simmer 30 min, stirring often.','Stir in cream and garam masala; cook 5 more min and serve with naan.']::text[], ARRAY['lunch','dinner','breakfast']::text[], 'bowl', 200, 340, 14.2, 32.5, 10.8, 6.4, 3.8, 85, 0.15, 280, false),
  (118, 'Shahi Paneer', 'North Indian', 'north_indian', 'veg', false, 'curry', '3', '15 min', '25 min', 'Cubes of fresh cottage cheese bathed in a regal cashew and cream gravy perfumed with cardamom — rich, mild and deeply satisfying.', 'Soaking cashews for 30 min before blending gives a silkier, creamier sauce with no grit.', 'Traditional', NULL, ARRAY['300g paneer, cubed','2 onions, roughly chopped','2 tomatoes, chopped','20 cashews, soaked','2 tbsp cream','1 tsp cardamom powder','1 tsp chilli powder','1 tsp ginger-garlic paste','Salt and ghee to taste']::text[], ARRAY['Boil onions and cashews together for 10 min; blend to a smooth paste.','Heat ghee; add ginger-garlic paste and cook 1 min.','Add tomato and cook until soft; blend this too, combine with cashew-onion paste.','Return gravy to pan; add chilli, cardamom, salt and simmer 10 min.','Add paneer and cream; heat 3 min and garnish with cream swirl and dried rose petals.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 360, 18.5, 12.8, 24.2, 1.8, 1.9, 285, 0.38, 520, false),
  (119, 'Aloo Tikki Chaat', 'North Indian', 'north_indian', 'veg', false, 'snack', '2', '20 min', '20 min', 'Crispy spiced potato patties smothered in yoghurt, tamarind chutney and pomegranate — the street-food dish that defines Delhi evenings.', 'Frying in a well-oiled pan on medium-low gives a crust that stays crisp even after topping.', 'Traditional', NULL, ARRAY['3 medium potatoes, boiled and mashed','½ cup boiled chickpeas','1 tsp chaat masala','½ tsp cumin powder','½ cup whisked yoghurt','2 tbsp tamarind chutney','2 tbsp green chutney','Sev, pomegranate seeds and coriander to top']::text[], ARRAY['Mix mashed potato with salt, cumin and chaat masala; shape into flat patties.','Shallow-fry on medium heat until deeply golden and crisp on both sides.','Place patties on a plate; top with warm chickpeas.','Drizzle cold yoghurt, tamarind and green chutneys liberally.','Finish with sev, pomegranate and coriander; serve immediately.']::text[], ARRAY['snack']::text[], 'plate', 200, 280, 8.5, 38, 6.5, 5.2, 2.1, 92, 0.18, 485, false),
  (120, 'Samosa with Mint Chutney', 'North Indian', 'north_indian', 'vegan', false, 'snack', '2', '30 min', '25 min', 'Flaky triangular pastry filled with spiced mashed potato and peas — perhaps the most universally beloved Indian snack.', 'Frying on medium rather than high heat ensures the pastry cooks through and turns properly flaky.', 'Traditional', NULL, ARRAY['For pastry: 1 cup flour, 2 tbsp oil, salt, water','For filling: 3 potatoes boiled, ½ cup peas','1 tsp cumin seeds, 1 tsp coriander powder','½ tsp amchur, 1 green chilli minced','Oil for deep frying','Mint chutney to serve']::text[], ARRAY['Make a stiff pastry dough with flour, oil and salt; rest 20 min.','Sauté cumin, chilli and peas; add mashed potato, amchur and coriander; cool.','Roll pastry thin; cut into semi-circles; fold into cones, fill and seal with water.','Deep fry on medium heat (not high) until golden — about 8–10 min.','Drain and serve with fresh mint chutney.']::text[], ARRAY['snack']::text[], 'piece', 120, 320, 7.2, 38.5, 15.8, 3.2, 2.1, 28, 0, 340, false),
  (121, 'Dahi Bhalla', 'North Indian', 'north_indian', 'veg', true, 'snack', '2', '4 hrs', '20 min', 'Soft, spongy lentil dumplings soaked in cold yoghurt and topped with tamarind and green chutneys — a cooling contrast of textures and temperatures.', 'Soaking the fried bhallas in water is non-negotiable — it makes them impossibly soft and helps them absorb the yoghurt.', 'Traditional', NULL, ARRAY['1 cup urad dal (soaked 4 hrs)','1 cup thick yoghurt, whisked and sweetened','2 tbsp tamarind chutney','1 tbsp green chutney','Cumin powder and chaat masala to dust','Fresh coriander and pomegranate to garnish','Oil for frying']::text[], ARRAY['Grind soaked dal to a fluffy batter; whisk vigorously to incorporate air.','Drop spoonfuls into hot oil and fry until light golden; do not over-fry.','Soak fried bhallas in warm salted water for 10 min; squeeze gently and place on plate.','Pour chilled yoghurt over generously; drizzle both chutneys.','Dust with cumin and chaat masala; garnish and serve cold.']::text[], ARRAY['snack']::text[], 'serving', 150, 240, 8.5, 28.2, 6.8, 4.2, 2.4, 85, 0.25, 185, false),
  (122, 'Bhel Puri', 'North Indian', 'north_indian', 'vegan', false, 'snack', '2', '10 min', '0 min', 'The iconic Mumbai street snack — puffed rice tossed with crunchy sev, raw mango, onion and two chutneys in a brisk, textured salad.', 'Mix and serve instantly — bhel turns soggy within minutes of adding chutney.', 'Traditional', NULL, ARRAY['2 cups puffed rice (murmura)','½ cup thin sev','1 small onion, finely chopped','1 small potato, boiled and cubed','½ raw mango, grated (or tomato)','2 tbsp tamarind chutney','1 tbsp green chutney','1 tsp chaat masala','Coriander to garnish']::text[], ARRAY['Combine puffed rice, onion, potato and raw mango in a large bowl.','Add both chutneys and chaat masala; toss briskly.','Fold in sev last, tossing just once to keep it crunchy.','Transfer immediately to serving bowls.','Garnish with coriander and serve within 2 minutes.']::text[], ARRAY['snack','breakfast']::text[], 'bowl', 100, 180, 5.2, 28.5, 4.8, 2.1, 1.8, 45, 0.05, 385, false),
  (123, 'Nasi Lemak (Vegetarian)', 'Southeast Asian', 'asian', 'egg', false, 'main', '2', '15 min', '30 min', 'Coconut-fragrant rice with crispy peanuts, cucumber, boiled egg and a fiery sambal â€” Malaysia''s national breakfast, vegetarian style.', 'Pressing a piece of pandan leaf into the rice cooker is the single step that transforms plain coconut rice into something aromatic.', 'Traditional', NULL, ARRAY['1 cup jasmine rice cooked in coconut milk with pandan leaf','2 eggs, hard boiled','3 tbsp roasted peanuts','1/2 cucumber, sliced','Sambal: 5 dried chillies, 1 onion, 1 tomato, tamarind, sugar, salt','2 tsp oil']::text[], ARRAY['Cook rinsed rice in equal parts coconut milk and water with pandan leaf and salt.','Blend sambal ingredients and fry in oil until deep red and fragrant, about 10 min.','Halve hard-boiled eggs.','Arrange rice on a plate; place peanuts, cucumber and egg alongside.','Spoon sambal generously and serve.']::text[], ARRAY['breakfast']::text[], 'plate', 300, 380, 14.5, 42, 14.8, 3.2, 2.4, 58, 0.52, 385, false),
  (124, 'Khao Tom (Thai Rice Porridge)', 'Southeast Asian', 'asian', 'vegan', false, 'main', '2', '5 min', '20 min', 'Silky, mild Thai rice soup garnished with ginger, spring onion and crispy garlic â€” the soothing blank canvas of Southeast Asian mornings.', 'Cooking the rice in stock rather than water gives depth without any extra effort.', 'Traditional', NULL, ARRAY['1 cup jasmine rice, rinsed','4 cups vegetable stock','2 cm ginger, sliced','2 spring onions, sliced','2 tbsp fried garlic','1 tbsp soy sauce','1 tsp sesame oil','White pepper to taste','Fresh coriander to garnish']::text[], ARRAY['Simmer rice in stock with ginger on medium heat for 20 min, stirring occasionally, until porridge-like.','Season with soy sauce, sesame oil and white pepper.','Ladle into bowls; top with spring onion, fried garlic and coriander.','Serve with a wedge of lime and sliced chilli on the side.','Add a soft-boiled egg for extra protein.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 210, 4.2, 37.8, 5.1, 0.8, 0.6, 28, 0.1, 520, false),
  (125, 'Roti Canai with Vegetable Dal', 'Southeast Asian', 'asian', 'egg', false, 'main', '2', '30 min', '20 min', 'Flaky, layered Malaysian flatbread served with a yellow lentil dal â€” the morning ritual of a region.', 'The dough must rest fully so the gluten relaxes enough to stretch tissue-thin without tearing.', 'Traditional', NULL, ARRAY['For roti: 2 cups plain flour, 1 egg, 2 tbsp condensed milk, salt, ghee','For dal: 1/2 cup red lentils, 1 onion, 1 tomato','1 tsp curry powder, 1/2 tsp turmeric','Coconut milk splash, curry leaves, mustard seeds']::text[], ARRAY['Mix flour, egg, condensed milk and salt into a soft dough; rest 30 min, divide into balls.','Stretch each ball on an oiled surface into a paper-thin sheet; fold into a square.','Cook on a hot iron griddle with ghee until golden and puffed; crumple gently to flake.','Simmer red lentils with onion, tomato, curry powder and turmeric until soft; thin with coconut milk.','Serve roti with warm dal on the side.']::text[], ARRAY['breakfast']::text[], 'plate', 250, 350, 12.5, 42, 12, 5.5, 3.2, 85, 0.25, 480, false),
  (126, 'Jok (Thai Congee with Tofu)', 'Southeast Asian', 'asian', 'vegan', false, 'main', '2', '5 min', '25 min', 'Warming Thai rice porridge with silken tofu, fresh ginger and crispy fried shallots.', 'Stirring vigorously halfway through breaks the grains slightly and gives a naturally creamier congee.', 'Traditional', NULL, ARRAY['1/2 cup jasmine rice, rinsed','4 cups light vegetable stock','100g silken tofu, cubed','2 cm ginger, julienned','2 tbsp fried shallots','1 spring onion, sliced','1 tbsp light soy sauce','White pepper and sesame oil to taste']::text[], ARRAY['Simmer rice in stock, stirring often, for 20-25 min until very soft and creamy.','Gently slide in tofu cubes and warm through 2 min.','Season with soy sauce and white pepper.','Ladle into bowls; top with fried shallots, ginger and spring onion.','Finish with a few drops of sesame oil.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 200, 8.5, 22, 5.5, 0.8, 1.2, 85, 0, 380, false),
  (127, 'Mee Goreng Breakfast', 'Southeast Asian', 'asian', 'egg', false, 'main', '2', '10 min', '15 min', 'Spiced fried egg noodles with tofu and bean sprouts, sauced with soy and chilli â€” a fast, fiery Southeast Asian morning.', 'A very hot wok is non-negotiable â€” the smoky char is what separates good mee goreng from great.', 'Traditional', NULL, ARRAY['200g fresh yellow noodles','100g firm tofu, cubed and fried','1 cup bean sprouts','2 eggs','2 tbsp sweet soy sauce (kecap manis)','1 tbsp chilli sauce','1 onion, sliced','3 garlic cloves, minced','2 spring onions and lime to serve']::text[], ARRAY['Heat oil in a wok over high heat; fry tofu until golden, push to the side.','Add garlic and onion; stir-fry 1 min, then push aside and scramble eggs.','Add noodles and toss everything together vigorously.','Pour in kecap manis and chilli sauce; toss 2 min on high heat.','Add bean sprouts, toss 30 seconds and serve with spring onion and lime.']::text[], ARRAY['breakfast']::text[], 'plate', 300, 340, 16.5, 38.2, 12.8, 3.2, 3.8, 142, 0.6, 748, false),
  (128, 'Banh Mi Chay (Vegetarian Baguette)', 'Southeast Asian', 'asian', 'egg', false, 'main', '2', '20 min', '0 min', 'A Vietnamese vegetarian baguette stuffed with lemongrass tofu, pickled daikon, cucumber and fresh herbs â€” an explosion of textures.', 'Start the pickled daikon and carrot the evening before â€” even a 30-minute pickle makes a difference.', 'Traditional', NULL, ARRAY['2 small baguettes','150g firm tofu, sliced and marinated in lemongrass, soy and sugar','1/2 cup pickled daikon and carrot (in vinegar and sugar)','1/2 cucumber, matchsticked','Fresh coriander, mint and sliced chilli','Sriracha mayo','Maggi seasoning sauce']::text[], ARRAY['Pan-fry marinated tofu until caramelised on both sides.','Split baguettes and toast lightly inside.','Spread mayo; drizzle a few drops of Maggi sauce.','Layer with tofu, pickled vegetables, cucumber and herbs.','Top with sliced chilli and serve immediately.']::text[], ARRAY['lunch']::text[], 'serving', 250, 340, 14.5, 42, 9.5, 2.8, 2.1, 145, 0.4, 680, false),
  (129, 'Pho Chay (Vegetarian Noodle Soup)', 'Southeast Asian', 'asian', 'vegan', false, 'main', '2', '15 min', '40 min', 'A clear, deeply aromatic Vietnamese broth scented with charred ginger and star anise, poured over rice noodles and fresh herbs.', 'Charring the onion and ginger directly on a flame adds the subtle smokiness that defines an authentic pho broth.', 'Traditional', NULL, ARRAY['4 cups vegetable stock','1 large onion, halved and charred on flame','3 cm ginger, charred','3 star anise, 1 cinnamon stick, 4 cloves','2 tbsp soy sauce','200g flat rice noodles','Bean sprouts, Thai basil, lime, sliced chilli to serve','Hoisin and sriracha on the side']::text[], ARRAY['Toast spices in a dry pan until fragrant; add to stock with charred onion and ginger.','Simmer broth 30 min; strain and season with soy sauce and salt.','Soak rice noodles per packet; blanch bean sprouts briefly.','Divide noodles into bowls; ladle hot broth over.','Serve immediately with herb plate and condiments.']::text[], ARRAY['lunch']::text[], 'bowl', 400, 260, 8.5, 42, 2.5, 2.8, 1.2, 45, 0, 680, false),
  (130, 'Char Kway Teow (Vegetarian)', 'Southeast Asian', 'asian', 'egg', false, 'main', '2', '10 min', '15 min', 'Smoky, chewy flat rice noodles stir-fried at blistering heat with egg, bean sprouts and soy â€” the street-food legend of Penang.', 'Let noodles sit for a few seconds before tossing â€” that rest develops the wok char.', 'Traditional', NULL, ARRAY['300g flat rice noodles (fresh)','2 eggs','1 cup bean sprouts','4 garlic cloves, minced','2 tbsp dark soy sauce','1 tbsp light soy sauce','1 tsp chilli paste','2 spring onions, cut','Oil for frying']::text[], ARRAY['Heat wok to smoking point with oil; fry garlic until golden.','Add noodles and toss vigorously for 1 min.','Push noodles aside; scramble eggs in the gap, then fold into noodles.','Add soy sauces and chilli paste; toss on high heat 2 min.','Add bean sprouts and spring onion; toss 30 seconds and serve.']::text[], ARRAY['lunch']::text[], 'plate', 300, 380, 12.5, 48, 11.5, 2.2, 2.1, 65, 0.5, 1040, false),
  (131, 'Mango Sticky Rice', 'Southeast Asian', 'asian', 'vegan', true, 'dessert', '2', '4 hrs', '25 min', 'Sweet glutinous rice bathed in salted coconut milk alongside ripe mango â€” Thailand''s most beloved dessert-snack.', 'Resist lifting the lid during the 15-minute rest â€” the rice soaks up all the coconut milk undisturbed.', 'Traditional', NULL, ARRAY['1 cup glutinous rice, soaked 4 hrs','1 cup coconut milk','3 tbsp sugar','1/2 tsp salt','1 ripe mango, sliced','Toasted sesame seeds to garnish','Extra coconut cream to drizzle']::text[], ARRAY['Steam soaked glutinous rice for 20-25 min until translucent.','Warm coconut milk with sugar and salt until dissolved; do not boil.','Pour two-thirds of the coconut sauce over hot rice; stir and cover for 15 min to absorb.','Slice mango and arrange alongside rice.','Drizzle remaining coconut cream and scatter sesame seeds.']::text[], ARRAY['snack']::text[], 'serving', 200, 320, 3.2, 52.1, 10.8, 1.9, 0.8, 28, 0, 412, false),
  (132, 'Banh Trang Nuong (Vietnamese Grilled Rice Paper)', 'Southeast Asian', 'asian', 'egg', false, 'snack', '2', '10 min', '10 min', 'Crispy grilled rice paper spread with egg, spring onion and chilli sauce â€” Da Lat''s famous street snack, simple and addictive.', 'Work fast â€” the rice paper crisps within seconds and the egg sets quickly over direct heat.', 'Traditional', NULL, ARRAY['4 sheets dried rice paper','2 eggs','2 spring onions, sliced','2 tbsp sriracha or chilli sauce','1 tbsp soy sauce','Fresh coriander','1 tbsp butter or oil']::text[], ARRAY['Place a rice paper sheet directly on a wire rack over a gas flame or in a dry pan.','When it starts to blister, brush one side with a little butter.','Crack half an egg over the sheet; spread gently with a spoon.','Scatter spring onion and drizzle soy and chilli sauce.','Cook until egg sets; fold in half and eat immediately while crisp.']::text[], ARRAY['snack']::text[], 'piece', 100, 180, 7.5, 18.2, 8.1, 0.8, 1.4, 45, 0.35, 580, false),
  (133, 'Satay Tofu with Peanut Sauce', 'Southeast Asian', 'asian', 'vegan', false, 'snack', '2', '20 min', '15 min', 'Skewered tofu grilled with lemongrass marinade and served with a rich, creamy peanut sauce.', 'Press tofu for at least 20 minutes before marinating so it absorbs flavour instead of releasing water.', 'Traditional', NULL, ARRAY['200g firm tofu, pressed and cubed','Marinade: 1 stalk lemongrass minced, 1 tsp turmeric, 1 tsp curry powder, soy sauce','Peanut sauce: 4 tbsp peanut butter, 1 tbsp sweet soy, 1 tsp chilli paste, coconut milk, lime juice','Cucumber and onion to serve']::text[], ARRAY['Marinate tofu cubes for 15 min; thread onto soaked skewers.','Grill or pan-fry on high heat, turning, until charred at edges.','Warm peanut butter, soy sauce, chilli paste and coconut milk together; thin with lime.','Arrange skewers with cucumber and onion wedges.','Serve with peanut sauce for dipping.']::text[], ARRAY['snack']::text[], 'serving', 150, 250, 14.5, 8.2, 16.8, 2.1, 3.2, 185, 0, 520, false),
  (134, 'Som Tum (Green Papaya Salad)', 'Southeast Asian', 'asian', 'vegan', false, 'salad', '2', '15 min', '0 min', 'A bright, funky salad of shredded unripe papaya pounded with lime, chilli, palm sugar and peanuts â€” Thailand''s most refreshing dish.', 'The mortar is essential â€” bruising rather than cutting releases the papaya juices and lets the dressing penetrate.', 'Traditional', NULL, ARRAY['2 cups green papaya, peeled and shredded','1 clove garlic','2 bird eye chillies','1 tbsp palm sugar','2 tbsp lime juice','1 tbsp soy sauce','2 tbsp roasted peanuts','Cherry tomatoes, halved','Long beans, cut short']::text[], ARRAY['Pound garlic and chillies to a rough paste in a mortar.','Add palm sugar and pound briefly to dissolve.','Add long beans and tomatoes; bruise lightly with the pestle.','Add shredded papaya; toss and bruise with the pestle and spoon together.','Add lime juice, soy sauce, peanuts; toss and adjust for balance.']::text[], ARRAY['snack']::text[], 'bowl', 150, 120, 4.2, 14.8, 3.5, 2.1, 0.8, 42, 0.1, 385, false),
  (135, 'Hobak Juk (Pumpkin Porridge)', 'Korean', 'asian', 'vegan', true, 'main', '2', '10 min', '30 min', 'Velvety, naturally sweet Korean pumpkin porridge studded with chewy rice balls â€” a warming bowl for cold mornings.', 'Kabocha gives the most naturally sweet and colourful juk â€” butternut works but needs a little extra sugar.', 'Traditional', NULL, ARRAY['300g kabocha squash, peeled and cubed','1/2 cup glutinous rice flour','4 cups water','2 tbsp sugar','Pinch of salt','1/2 tsp cinnamon (optional)']::text[], ARRAY['Boil squash in water until completely soft; blend until smooth with cooking liquid.','Return to pan over medium heat.','Mix glutinous rice flour with a little water to form a dough; roll into small balls.','Drop rice balls into simmering porridge; cook until they float.','Add sugar, salt and cinnamon; stir and serve warm.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 190, 3.2, 42.5, 0.8, 1.2, 0.6, 45, 0, 95, false),
  (136, 'Miyeokguk (Seaweed Soup)', 'Korean', 'asian', 'vegan', false, 'soup', '2', '30 min', '20 min', 'A clean, mineral-rich broth of rehydrated sea mustard with sesame oil â€” traditionally eaten on birthdays for its restorative properties.', 'Sauteing the seaweed in sesame oil before adding liquid gives the soup a deeper, nuttier character.', 'Traditional', NULL, ARRAY['20g dried miyeok (sea mustard), soaked 30 min','4 cups vegetable stock','1 tsp sesame oil','1 tbsp soy sauce','2 garlic cloves, minced','Salt and white pepper to taste','Toasted sesame seeds to garnish']::text[], ARRAY['Soak miyeok in cold water 30 min; drain, squeeze and cut into bite-sized pieces.','Heat sesame oil in a pot; saute garlic and seaweed briefly until fragrant.','Add stock; bring to a boil then simmer 15 min.','Season with soy sauce, salt and white pepper.','Serve in bowls scattered with sesame seeds.']::text[], ARRAY['breakfast']::text[], 'bowl', 200, 80, 3.2, 8.4, 2.1, 1.8, 2.4, 68, 0.4, 520, false),
  (137, 'Gyeran Toast (Korean Egg Toast)', 'Korean', 'asian', 'egg', true, 'main', '1', '5 min', '10 min', 'A Seoul street classic â€” egg-dipped toast griddled in butter with shredded cabbage inside, finished with ketchup and a pinch of sugar.', 'The pinch of sugar scattered over the finished toast is the street-stall touch that makes it distinctively Korean.', 'Traditional', NULL, ARRAY['2 slices thick white bread','2 eggs','1/4 cup shredded cabbage','1 spring onion, sliced','1 tbsp butter','Pinch of salt and sugar','Ketchup and yellow mustard to serve']::text[], ARRAY['Beat eggs with cabbage, spring onion and a pinch of salt.','Melt butter in a pan; pour egg mixture roughly the shape of the bread.','Before it fully sets, place bread on top, press, then flip so bread is underneath.','Cook until bread is golden; flip once more so egg is on top.','Transfer to plate; drizzle ketchup, a pinch of sugar and mustard.']::text[], ARRAY['breakfast']::text[], 'serving', 180, 280, 12.5, 28, 10.5, 1.2, 2.8, 65, 0.5, 420, false),
  (138, 'Doenjang Guk with Tofu', 'Korean', 'asian', 'vegan', false, 'soup', '2', '5 min', '15 min', 'A simple Korean soybean paste soup with soft tofu and zucchini â€” savoury, subtle and surprisingly restorative.', 'Dissolve the doenjang gradually and taste as you go â€” different brands vary significantly in saltiness.', 'Traditional', NULL, ARRAY['1.5 tbsp doenjang (Korean fermented soybean paste)','100g soft tofu, cubed','1/2 zucchini, diced','3 cups vegetable stock','1 garlic clove, minced','1 spring onion, sliced','Sesame oil to finish']::text[], ARRAY['Bring stock to a simmer; dissolve doenjang into the liquid by pressing through a spoon.','Add garlic and zucchini; cook 5 min until tender.','Add tofu; simmer gently 3 min without stirring vigorously.','Taste and adjust salt if needed.','Ladle into bowls; top with spring onion and a drop of sesame oil.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 120, 8.5, 4.2, 5.1, 0.8, 2.1, 95, 0.2, 620, false),
  (139, 'Jangjuk (Soy Sauce Congee)', 'Korean', 'asian', 'vegan', false, 'main', '2', '5 min', '20 min', 'Silky Korean rice porridge seasoned with soy sauce and sesame oil â€” the most comforting answer to a cold morning.', 'Covering the porridge for the last 5 minutes traps steam and creates an extra-silky texture.', 'Traditional', NULL, ARRAY['1/2 cup short-grain rice, rinsed','4 cups water or light vegetable stock','2 tbsp soy sauce','1 tsp sesame oil','1 tsp sesame seeds','2 spring onions, sliced','Kimchi on the side (optional)']::text[], ARRAY['Simmer rice in water on medium-low heat for 20 min, stirring occasionally, until soft and creamy.','Season with soy sauce.','Ladle into bowls; drizzle with sesame oil.','Garnish with sesame seeds and spring onion.','Serve with a small dish of kimchi on the side.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 200, 4.2, 32.5, 3.8, 0.6, 0.8, 42, 0.2, 580, false),
  (140, 'Bibim Guksu (Spicy Cold Noodles)', 'Korean', 'asian', 'egg', false, 'main', '2', '15 min', '10 min', 'Chewy thin noodles tossed in a bright gochujang dressing with cucumber and sesame â€” a Korean summer staple.', 'Rinsing in ice-cold water not only cools the noodles but firms the texture â€” warm noodles will clump.', 'Traditional', NULL, ARRAY['200g thin wheat noodles (somyeon)','3 tbsp gochujang','1 tbsp soy sauce','1 tbsp sugar','1 tbsp rice vinegar','1 tbsp sesame oil','1 cucumber, matchsticked','1 carrot, matchsticked','Toasted sesame seeds and a boiled egg to serve']::text[], ARRAY['Cook noodles per packet; rinse in ice-cold water until completely cold; drain well.','Whisk gochujang, soy, sugar, vinegar and sesame oil into a smooth sauce.','Toss cold noodles in the sauce until well coated.','Pile into bowls; top with cucumber, carrot and sesame seeds.','Serve immediately with a halved boiled egg.']::text[], ARRAY['lunch']::text[], 'plate', 300, 340, 12.5, 48.2, 9.8, 2.1, 2.4, 52, 0.35, 1240, false),
  (141, 'Tteokbokki (Spicy Rice Cakes)', 'Korean', 'asian', 'egg', false, 'main', '2', '5 min', '20 min', 'Chewy cylindrical rice cakes in a glistening gochujang and soy sauce â€” the most popular street-food comfort in Korea.', 'The sauce should reduce and cling â€” add a splash of water only if it sticks to the pan rather than the rice cakes.', 'Traditional', NULL, ARRAY['300g tteok (cylindrical rice cakes)','3 tbsp gochujang','1 tbsp gochugaru (red pepper flakes)','1 tbsp soy sauce','1 tbsp sugar','2 cups vegetable stock','2 spring onions, cut into 5cm pieces','Boiled eggs and sesame seeds to serve']::text[], ARRAY['Soak rice cakes in cold water 20 min if refrigerated.','Bring stock to a simmer; add gochujang, gochugaru, soy and sugar; stir to dissolve.','Add rice cakes; cook on medium heat 8-10 min, stirring, until sauce thickens and coats.','Add spring onions and cook 2 min more.','Serve topped with boiled eggs and sesame seeds.']::text[], ARRAY['lunch']::text[], 'plate', 250, 310, 8.5, 52, 3.5, 1.2, 1.8, 45, 0.1, 890, false),
  (142, 'Kongnamul Guk (Bean Sprout Soup)', 'Korean', 'asian', 'vegan', false, 'soup', '2', '5 min', '15 min', 'A clean, restorative Korean broth of crunchy bean sprouts with garlic and sesame â€” deceptively simple, deeply flavourful.', 'Never peek while the sprouts come to a boil â€” lifting the lid causes a bitter, grassy smell.', 'Traditional', NULL, ARRAY['2 cups soybean sprouts, rinsed','4 cups water','1 tsp soy sauce','1 garlic clove, minced','1 tsp sesame oil','1/2 tsp gochugaru','Salt to taste','1 spring onion, sliced']::text[], ARRAY['Place sprouts in a pot with water; cover and bring to a boil without lifting the lid.','Once boiling, add garlic and soy sauce; simmer 10 min.','Season with salt and gochugaru.','Turn off heat; stir in sesame oil.','Serve garnished with spring onion.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 90, 6.5, 8.2, 3.1, 1.8, 1.2, 45, 0, 320, false),
  (143, 'Dubu Jorim (Braised Tofu)', 'Korean', 'asian', 'vegan', false, 'side', '2', '5 min', '20 min', 'Crispy pan-fried tofu braised in a spicy, sticky gochujang and garlic sauce â€” one of Korea''s most beloved everyday dishes.', 'Patting the tofu completely dry before frying is essential â€” moisture is the enemy of a crispy crust.', 'Traditional', NULL, ARRAY['300g firm tofu, sliced 1cm thick','2 tbsp gochujang','1 tbsp soy sauce','1 tbsp sugar','1 tbsp sesame oil','3 garlic cloves, minced','3 tbsp water','Spring onion and sesame seeds to garnish']::text[], ARRAY['Press tofu dry; pan-fry in oil until golden on both sides; set aside.','Mix gochujang, soy, sugar, garlic and water into a sauce.','Add sauce to the pan; bring to a simmer.','Return tofu; spoon sauce over and cook 5 min until sauce reduces and glazes.','Garnish with spring onion and sesame seeds.']::text[], ARRAY['lunch']::text[], 'serving', 150, 210, 15.2, 8.5, 11.3, 1.2, 3.8, 185, 0, 542, false),
  (144, 'Hotteok (Sweet Filled Pancake)', 'Korean', 'asian', 'vegan', true, 'dessert', '2', '90 min', '15 min', 'Yeasted street pancakes oozing with brown sugar, cinnamon and crushed walnuts â€” the iconic Korean winter snack.', 'The dough will be sticky â€” resist adding more flour, as that stickiness creates the characteristic chewy texture.', 'Traditional', NULL, ARRAY['1 cup plain flour','1/2 tsp instant yeast','1/2 tsp sugar (for dough)','1/2 tsp salt','1/2 cup warm water','Filling: 3 tbsp brown sugar, 1 tsp cinnamon, 2 tbsp chopped walnuts','Oil for frying']::text[], ARRAY['Mix flour, yeast, sugar, salt and water to a sticky dough; prove 1 hour until doubled.','Mix filling ingredients together.','Grease hands; take a portion of dough, flatten, place 1 tbsp filling in centre, seal tightly.','Cook in oiled pan on medium; after 1 min, press flat with a spatula.','Flip; press again and cook 2 min until golden. Eat carefully â€” filling is very hot.']::text[], ARRAY['snack']::text[], 'piece', 80, 280, 6.2, 38.5, 9.8, 1.2, 1.8, 32, 0, 285, false),
  (145, 'Gyeran Ppang (Egg Bread)', 'Korean', 'asian', 'egg', true, 'snack', '2', '10 min', '20 min', 'Soft, pillowy corn bread buns baked with a whole egg inside â€” a popular Korean street snack that is mildly sweet and savoury.', 'Crack eggs from a low height so the yolk stays intact and centred â€” it looks beautiful when sliced open.', 'Traditional', NULL, ARRAY['1/2 cup flour','1 tsp baking powder','2 tbsp sugar','Pinch of salt','1 egg plus 2 extra eggs (one per bread)','3 tbsp milk','2 tbsp melted butter','Corn or grated cheese for topping']::text[], ARRAY['Mix flour, baking powder, sugar and salt; whisk in egg, milk and butter to a smooth batter.','Grease a muffin tin; fill each cavity halfway with batter.','Crack one egg carefully into each cavity on top of the batter.','Bake at 190Â°C for 15-18 min until egg is set and bread is golden.','Scatter toppings before baking for extra flavour.']::text[], ARRAY['snack']::text[], 'piece', 100, 210, 8.5, 22.5, 9, 0.4, 1.8, 85, 0.5, 280, false),
  (146, 'Jeon (Korean Vegetable Pancake)', 'Korean', 'asian', 'egg', false, 'snack', '2', '10 min', '15 min', 'Crispy-edged savoury pancakes stuffed with zucchini, spring onion or kimchi â€” paired with a soy-vinegar dipping sauce.', 'Using ice-cold water creates a lighter, crisper result â€” the temperature keeps gluten formation minimal.', 'Traditional', NULL, ARRAY['1 cup plain flour','1 egg','1 cup cold water','1/2 tsp salt','1 zucchini, grated or 2 spring onions, sliced','1/2 carrot, grated','Dipping sauce: 2 tbsp soy sauce, 1 tbsp rice vinegar, 1 tsp sesame oil, pinch chilli flakes']::text[], ARRAY['Mix flour, egg, cold water and salt to a loose batter.','Stir in grated or sliced vegetables.','Heat a thin layer of oil in a flat pan over medium-high heat.','Pour a ladleful of batter and spread; cook 3 min until edges crisp and set.','Flip and cook 2 min more; serve with dipping sauce.']::text[], ARRAY['snack']::text[], 'piece', 120, 240, 6.5, 32, 7.5, 1.8, 1.2, 45, 0.15, 680, false),
  (147, 'Bungeoppang (Red Bean Pastry)', 'Korean', 'asian', 'egg', true, 'dessert', '2', '15 min', '20 min', 'Fish-shaped waffle cakes filled with sweet red bean paste â€” a nostalgic Korean winter street snack.', 'Ready-made red bean paste from an Asian grocery gives consistent results every time.', 'Traditional', NULL, ARRAY['1 cup plain flour','1 tsp baking powder','2 tbsp sugar','1 egg','3/4 cup milk','2 tbsp melted butter','1 cup sweet red bean paste','Oil to grease mould']::text[], ARRAY['Whisk flour, baking powder and sugar; beat in egg, milk and butter to a smooth batter.','Heat a sandwich maker or bungeoppang mould and brush with oil.','Pour batter into one side to half-fill; add 2 tbsp red bean paste.','Cover with more batter; close the mould and cook 3 min each side.','Unmould and eat warm â€” the filling will be very hot.']::text[], ARRAY['snack']::text[], 'piece', 100, 200, 6.5, 28, 6.5, 1.8, 1.2, 85, 0.18, 145, false),
  (148, 'Yakgwa (Honey Sesame Cookie)', 'Korean', 'asian', 'veg', true, 'dessert', '4', '30 min', '20 min', 'Delicately fried Korean honey cookies perfumed with ginger and sesame, soaked in a fragrant sugar syrup.', 'Frying at very low temperature is essential â€” high heat burns the outside while the inside stays raw.', 'Traditional', NULL, ARRAY['1 cup plain flour','3 tbsp sesame oil','3 tbsp honey','1 tbsp rice wine or soju','Pinch of salt and ginger powder','Syrup: 1/2 cup honey, 1/4 cup water, 1 tsp ginger juice','Sesame seeds and pine nuts to garnish','Oil for frying']::text[], ARRAY['Mix flour with sesame oil, honey, rice wine, salt and ginger until crumbly; press into a dough.','Roll to 1cm thick; stamp into round or square shapes.','Fry in oil at 150Â°C (very low) for 12-15 min until golden throughout.','Drain; dip immediately into warm honey syrup for 30 min.','Drain again; press sesame seeds and pine nuts on top.']::text[], ARRAY['snack']::text[], 'piece', 50, 180, 3.2, 24.5, 10.8, 0.8, 1.2, 45, 0, 85, false),
  (149, 'Zaru Soba (Cold Buckwheat Noodles)', 'Japanese', 'asian', 'vegan', false, 'main', '2', '10 min', '10 min', 'Chilled buckwheat noodles served on a bamboo tray with a cold dashi dipping broth â€” clean, elegant and deeply refreshing.', 'Rinse the soba under cold water with vigour â€” the friction removes excess starch and gives each strand a clean, firm bite.', 'Traditional', NULL, ARRAY['200g dry soba noodles','1.5 cups dashi stock (kombu-based for vegetarian)','3 tbsp soy sauce','2 tbsp mirin','1 tsp sugar','2 spring onions, finely sliced','Wasabi and grated ginger to serve','Toasted nori, shredded']::text[], ARRAY['Cook soba per packet; drain and rinse immediately under cold running water until completely chilled.','Combine dashi, soy sauce, mirin and sugar; simmer 2 min; cool completely.','Arrange soba on a tray or plate; scatter nori on top.','Pour dipping broth into a small bowl.','Dip noodles in broth with spring onion, wasabi and ginger; eat immediately.']::text[], ARRAY['lunch']::text[], 'plate', 250, 280, 12.5, 42.8, 1.2, 3.8, 2.1, 45, 0.3, 1240, false),
  (150, 'Tofu Katsu Curry', 'Japanese', 'asian', 'egg', false, 'main', '2', '20 min', '30 min', 'Panko-crusted tofu cutlets on steamed rice with a thick, subtly spiced Japanese curry sauce â€” comfort food at its most satisfying.', 'Refrigerating the breaded tofu for 10 minutes before frying helps the panko adhere and prevents it falling off in the oil.', 'Traditional', NULL, ARRAY['300g firm tofu, sliced and pressed','1 cup panko breadcrumbs','1 egg, beaten','3 tbsp plain flour','For curry sauce: 1 onion, 1 carrot, 2 potatoes, 2 tbsp curry roux (S&B or similar)','2 cups water or vegetable stock','Oil for frying','Steamed rice to serve','Pickled ginger on the side']::text[], ARRAY['Dredge tofu in flour, dip in egg, coat in panko; refrigerate 10 min.','Simmer onion, carrot and potato in stock until tender; add curry roux and stir until smooth.','Fry breaded tofu in 170Â°C oil until golden and crisp; drain.','Serve rice in a bowl, ladle curry alongside.','Place tofu katsu on top; garnish with spring onion and pickled ginger.']::text[], ARRAY['lunch']::text[], 'plate', 400, 420, 18.5, 42.3, 14.2, 3.1, 2.8, 185, 0.3, 580, false),
  (151, 'Kinoko Gohan (Mushroom Rice)', 'Japanese', 'asian', 'vegan', false, 'main', '2', '10 min', '30 min', 'Fragrant Japanese rice cooked with a medley of mushrooms, soy and sake â€” a deeply umami one-pot that celebrates the earthy forest floor.', 'Removing the kombu before the rice finishes cooking prevents it from becoming slimy â€” 15 minutes of infusing is enough.', 'Traditional', NULL, ARRAY['1.5 cups short-grain rice, rinsed','200g mixed mushrooms (shiitake, enoki, shimeji)','2 tbsp soy sauce','1 tbsp sake or dry sherry','1 tbsp mirin','2 cups water','1 sheet kombu (dried kelp), wiped','Spring onion and toasted sesame to garnish']::text[], ARRAY['Soak rice in water 30 min; drain.','Slice mushrooms; sautÃ© in a little oil until golden and fragrant.','Combine rice, sauteed mushrooms, soy, sake, mirin, kombu and water in a rice cooker or pot.','Cook as normal rice; remove kombu before serving.','Fluff with a spoon; garnish with spring onion and sesame.']::text[], ARRAY['lunch']::text[], 'plate', 300, 310, 6.8, 62.5, 1.2, 2.1, 1.8, 28, 0.9, 485, false),
  (152, 'Ochazuke (Rice with Green Tea and Nori)', 'Japanese', 'asian', 'vegan', false, 'main', '1', '5 min', '5 min', 'Leftover rice revived with hot green tea, pickled plum and nori â€” Japan''s most contemplative and comforting light meal.', 'Hojicha (roasted green tea) gives a nuttier, smoother flavour than sencha â€” try both and see which you prefer.', 'Traditional', NULL, ARRAY['1 bowl cooked short-grain rice','1 cup hot green tea (sencha or hojicha)','1 umeboshi (pickled plum)','1 sheet nori, cut into strips','1 tbsp soy sauce','Toasted sesame seeds','Wasabi (optional)','Spring onion, sliced']::text[], ARRAY['Place rice in a bowl; arrange nori strips, umeboshi and spring onion on top.','Pour hot green tea over the rice.','Add soy sauce; stir gently.','Add a small dot of wasabi if using.','Eat immediately before the nori softens too much.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 180, 6.2, 35.8, 2.1, 1.4, 2.8, 85, 0.4, 820, false),
  (153, 'Yudofu (Simmered Tofu in Kombu Broth)', 'Japanese', 'asian', 'vegan', false, 'side', '2', '30 min', '20 min', 'Silken tofu gently heated in a clean kombu broth, eaten dipped in ponzu and grated ginger â€” the most meditative dish in Japanese cuisine.', 'Never let the broth boil â€” simmering silently is the point; boiling makes silken tofu fall apart and turns the broth bitter.', 'Traditional', NULL, ARRAY['400g silken or soft tofu, cubed','1 strip kombu (10cm), wiped','4 cups water','For dipping: 3 tbsp ponzu sauce','1 tbsp grated ginger','1 tbsp grated daikon','2 spring onions, finely sliced','Toasted sesame seeds']::text[], ARRAY['Soak kombu in water for 30 min; bring to a very gentle simmer.','Add tofu pieces; heat slowly until warmed through â€” do not boil.','Mix ponzu, grated ginger, daikon and spring onion for dipping sauce.','Serve tofu directly from the pot; dip each piece into the sauce.','Sip the warm kombu broth between bites.']::text[], ARRAY['lunch']::text[], 'bowl', 220, 150, 9.2, 4.8, 5.1, 0.8, 2.4, 180, 0, 580, false),
  (154, 'Miso Ramen (Vegetarian)', 'Japanese', 'asian', 'egg', false, 'main', '2', '15 min', '25 min', 'Rich, cloudy miso broth with springy noodles, corn, bamboo shoots and a drizzle of chilli oil â€” warming from first sip to last.', 'Add miso off the heat or at a very gentle simmer â€” boiling destroys its probiotic cultures and dulls the flavour.', 'Traditional', NULL, ARRAY['2 portions fresh ramen noodles','4 cups vegetable stock','3 tbsp white miso paste','1 tbsp soy sauce','1 tbsp sesame oil','1 tsp grated ginger','1 garlic clove, minced','Toppings: corn, bamboo shoots, soft-boiled egg, nori, spring onion, chilli oil']::text[], ARRAY['Simmer stock with garlic and ginger 5 min; whisk in miso and soy sauce â€” do not boil after adding miso.','Stir in sesame oil.','Cook noodles per packet; drain and divide into bowls.','Pour hot miso broth over noodles.','Arrange toppings artfully and drizzle chilli oil; serve immediately.']::text[], ARRAY['dinner']::text[], 'bowl', 400, 380, 14.5, 48, 12, 2.5, 2.8, 85, 0.35, 1240, false),
  (155, 'Japanese Vegetable Curry', 'Japanese', 'asian', 'veg', false, 'curry', '3', '15 min', '35 min', 'A thick, gentle curry of root vegetables in a rich, subtly spiced sauce served over steamed rice â€” Japan''s most popular home-cooked dish.', 'The curry roux needs 5 full minutes of simmering after melting to thicken properly and lose any raw flour taste.', 'Traditional', NULL, ARRAY['2 medium potatoes, cubed','2 carrots, sliced','1 large onion, wedged','1 courgette, sliced','2 tbsp Japanese curry roux (S&B Golden Curry)','2.5 cups water or vegetable stock','1 tbsp soy sauce','Steamed rice to serve','Fukujinzuke pickle to accompany']::text[], ARRAY['Saute onion in oil until softened; add carrots and potatoes and fry 3 min.','Add water or stock; bring to a boil and simmer 15 min until vegetables are nearly tender.','Add courgette; cook 5 min more.','Break in curry roux blocks; stir until completely melted and sauce thickens.','Season with soy sauce and serve over rice with pickle on the side.']::text[], ARRAY['dinner']::text[], 'bowl', 300, 360, 8.5, 52.3, 8.2, 6.1, 1.8, 62, 0.1, 720, false),
  (156, 'Vegetarian Sukiyaki', 'Japanese', 'asian', 'veg', false, 'main', '2', '15 min', '20 min', 'A Japanese hot-pot of vegetables, tofu and glass noodles simmered in a sweet soy broth, dipped in raw egg â€” indulgent and communal.', 'Keep the heat at a gentle simmer throughout â€” rapid boiling makes the tofu rubbery and breaks down the delicate vegetables.', 'Traditional', NULL, ARRAY['200g firm tofu, sliced','150g glass noodles (harusame), soaked','1 leek, sliced diagonally','200g napa cabbage, roughly cut','100g enoki mushrooms','4 tbsp soy sauce','3 tbsp mirin','2 tbsp sake','1 tbsp sugar','2 eggs for dipping (optional)']::text[], ARRAY['Mix soy, mirin, sake and sugar into a warishita (sukiyaki sauce).','Heat a wide shallow pan; pour in half the sauce and bring to a simmer.','Add tofu, leek, cabbage and mushrooms; cook until tender, adding more sauce as needed.','Add glass noodles; simmer until translucent.','Beat eggs lightly in small bowls; dip each bite before eating (or skip the egg for vegan).']::text[], ARRAY['dinner']::text[], 'bowl', 300, 290, 18.5, 32, 8.5, 3.5, 4.2, 185, 0.4, 1140, false),
  (157, 'Yakimeshi (Japanese Fried Rice)', 'Japanese', 'asian', 'egg', false, 'main', '2', '10 min', '15 min', 'Wok-fried Japanese rice with egg, spring onion and soy â€” simpler than Chinese fried rice, subtler in flavour and deeply habit-forming.', 'Day-old rice from the fridge is drier and fries better â€” fresh rice turns mushy and clumps.', 'Traditional', NULL, ARRAY['2 cups cooked short-grain rice (day-old is best)','2 eggs, beaten','3 spring onions, sliced','1 tbsp soy sauce','1 tbsp oyster sauce (or vegetarian version)','1 tsp sesame oil','1 tbsp vegetable oil','White pepper to taste','Pickled ginger to serve']::text[], ARRAY['Heat wok on high; add oil and scramble eggs until just set; break into pieces.','Add cold rice; press and stir-fry vigorously, breaking up any clumps.','Add soy and oyster sauce; toss until every grain is coated and starting to char slightly.','Add spring onion and white pepper; toss 30 seconds more.','Drizzle sesame oil; serve immediately with pickled ginger.']::text[], ARRAY['dinner']::text[], 'plate', 250, 350, 10.5, 42, 9.5, 0.8, 1.8, 45, 0.35, 520, false),
  (158, 'Edamame with Sea Salt', 'Japanese', 'asian', 'vegan', true, 'snack', '2', '2 min', '8 min', 'Boiled young soybeans in the pod, scattered with flaky sea salt â€” the purest, most effortless Japanese snack.', 'Salting both the cooking water and the finished edamame in two stages gives a more flavourful result than just one.', 'Traditional', NULL, ARRAY['250g frozen edamame in pods','1.5 tbsp salt (for boiling water)','Flaky sea salt to finish','Lemon wedge (optional)']::text[], ARRAY['Bring a large pot of water to a rolling boil; add salt generously.','Add frozen edamame; cook 4-5 min until bright green and tender.','Drain; toss immediately with a pinch of flaky salt.','Serve in a bowl with a small dish for the empty pods.','Squeeze lemon over if desired.']::text[], ARRAY['snack']::text[], 'bowl', 100, 120, 11.2, 8.5, 5.8, 3.2, 2.1, 65, 0, 285, false),
  (159, 'Yakitori Tofu Skewers', 'Japanese', 'asian', 'vegan', false, 'snack', '2', '15 min', '15 min', 'Tender tofu cubes glazed with a sweet soy tare and grilled until caramelised at the edges â€” the vegetarian answer to Japan''s most beloved skewer.', 'Press the tofu for at least 20 minutes before skewering â€” drier tofu holds together better and caramelises more evenly.', 'Traditional', NULL, ARRAY['300g firm tofu, pressed and cubed','3 tbsp soy sauce','2 tbsp mirin','1 tbsp sake','1 tsp sugar','2 spring onions, cut into 4cm pieces','Toasted sesame seeds and shichimi to garnish','Bamboo skewers, soaked in water']::text[], ARRAY['Simmer soy, mirin, sake and sugar in a small pan until slightly thickened; cool.','Thread tofu and spring onion alternately onto skewers.','Grill or pan-fry on medium-high heat, turning every 2 min.','Brush tare glaze over skewers during last 2 min of cooking.','Scatter sesame seeds and shichimi; serve immediately.']::text[], ARRAY['snack']::text[], 'serving', 150, 180, 12.5, 8.2, 6.8, 1.2, 2.1, 185, 0, 820, false),
  (160, 'Jianbing (Vegetable Savoury Crepe)', 'Chinese', 'asian', 'egg', false, 'main', '2', '10 min', '15 min', 'A crispy, layered Beijing street crepe with egg, hoisin, crispy wonton and spring onion â€” China''s most beloved breakfast on the go.', 'The batter should be almost as thin as water â€” a thick crepe loses the characteristic papery crispness.', 'Traditional', NULL, ARRAY['1/2 cup mung bean flour (or plain flour)','1/4 cup water','2 eggs','2 tbsp hoisin sauce','1 tsp chilli sauce','2 spring onions, sliced','4 small wonton wrappers, fried crisp','1/4 cup bean sprouts','Fresh coriander']::text[], ARRAY['Mix flour and water to a thin smooth batter.','Heat a non-stick pan; pour a thin layer of batter and swirl to coat.','Crack an egg on top; spread with the back of a spoon.','Sprinkle spring onion and bean sprouts; cook until egg sets.','Spread hoisin and chilli sauce, add coriander and crispy wonton; fold and serve.']::text[], ARRAY['breakfast']::text[], 'piece', 200, 290, 12.5, 28, 9.5, 2, 2.8, 65, 0.5, 620, false),
  (161, 'Steamed Vegetable Baozi (Buns)', 'Chinese', 'asian', 'vegan', false, 'snack', '2', '90 min', '20 min', 'Pillowy steamed yeast buns filled with seasoned cabbage, tofu and mushroom â€” the most comforting Chinese breakfast.', 'Squeezing excess water from the cabbage filling before stuffing prevents soggy, leaking buns.', 'Traditional', NULL, ARRAY['2 cups plain flour','1 tsp instant yeast','1 tbsp sugar','3/4 cup warm water','Filling: 1 cup napa cabbage, 100g tofu, 50g shiitake mushrooms','1 tbsp soy sauce, 1 tsp sesame oil, ginger, spring onion','Salt to taste']::text[], ARRAY['Mix flour, yeast, sugar and water to a smooth dough; prove 1 hour until doubled.','Finely chop filling ingredients; mix with soy, sesame oil, ginger and salt; squeeze out excess liquid.','Divide dough into 8; roll each into a circle; place 1 tbsp filling in centre.','Gather and pleat edges to seal; prove 15 min more.','Steam over high heat for 15 min; rest 2 min before lifting lid.']::text[], ARRAY['breakfast']::text[], 'piece', 150, 280, 9.5, 42, 4.2, 2.1, 2.8, 185, 0.3, 420, false),
  (162, 'Red Bean Porridge', 'Chinese', 'asian', 'vegan', true, 'main', '2', '8 hrs', '60 min', 'A gentle, lightly sweetened porridge of soft red beans and glutinous rice â€” a Chinese breakfast with quietly nourishing depth.', 'Soaking the beans overnight halves the cooking time and produces a creamier, more evenly cooked porridge.', 'Traditional', NULL, ARRAY['1/2 cup red adzuki beans, soaked overnight','1/4 cup glutinous rice','5 cups water','3 tbsp sugar (or to taste)','Pinch of salt','Dried tangerine peel or a pandan leaf (optional)']::text[], ARRAY['Drain soaked beans; simmer in fresh water with tangerine peel or pandan for 45 min until very soft.','Add rinsed glutinous rice; cook 20 min more, stirring occasionally, until porridge is thick.','Add sugar and salt; stir to dissolve.','Remove peel or pandan.','Serve warm; leftovers thicken overnight â€” thin with a little water when reheating.']::text[], ARRAY['breakfast']::text[], 'bowl', 300, 220, 8.5, 42, 0.8, 6.2, 2.1, 52, 0, 145, false),
  (163, 'Dan Dan Noodles (Vegetarian)', 'Chinese', 'asian', 'vegan', false, 'main', '2', '15 min', '20 min', 'Chewy noodles in a fiery, numbing sauce of sesame, chilli oil and Sichuan pepper â€” one of China''s most electrically flavoured dishes.', 'Using the hot noodle cooking water to loosen the sauce emulsifies it beautifully and helps it cling to every strand.', 'Traditional', NULL, ARRAY['200g wheat noodles','3 tbsp tahini or Chinese sesame paste','2 tbsp chilli oil','1 tbsp soy sauce','1 tbsp black vinegar (Chinkiang)','1 tsp Sichuan pepper, ground','1 tsp sugar','2 garlic cloves, minced','Spring onion and crushed peanuts to garnish']::text[], ARRAY['Cook noodles per packet; drain, reserving 3 tbsp cooking water.','Whisk tahini, chilli oil, soy, vinegar, Sichuan pepper, sugar and garlic; loosen with cooking water.','Toss hot noodles in the sauce immediately.','Transfer to bowls; top with spring onion and peanuts.','Add extra chilli oil at the table.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 380, 12.5, 38, 18.5, 2.8, 2.1, 95, 0, 580, false),
  (164, 'Buddha''s Delight (Lo Han Jai)', 'Chinese', 'asian', 'vegan', false, 'main', '3', '30 min', '30 min', 'A rich, glistening Buddhist temple stew of tofu, glass noodles, cloud ear mushrooms and lotus root â€” eaten on the first day of Lunar New Year for good fortune.', 'This dish improves overnight as the flavours meld â€” make it the evening before for the best result.', 'Traditional', NULL, ARRAY['100g glass noodles, soaked','100g firm tofu, cubed and fried','50g dried cloud ear mushrooms, soaked','1 cup lotus root, sliced','1 cup napa cabbage, cut','1 carrot, sliced','3 tbsp soy sauce','1 tbsp oyster sauce (vegetarian)','1 tsp sugar','Sesame oil to finish']::text[], ARRAY['Soak glass noodles and cloud ear mushrooms separately for 30 min; drain.','Fry tofu until golden; set aside.','Heat oil; stir-fry carrot, lotus root and cabbage 3 min.','Add mushrooms, tofu, soy, oyster sauce and sugar; toss well.','Add noodles and 1/2 cup water; simmer 8 min until glossy and sauce has absorbed; finish with sesame oil.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 210, 8.2, 24.5, 6.8, 3.4, 2.1, 95, 0.15, 685, false),
  (165, 'Winter Melon and Tofu Soup', 'Chinese', 'asian', 'vegan', false, 'soup', '3', '10 min', '25 min', 'A delicate, clear Chinese soup of winter melon and silken tofu in a light ginger broth â€” cooling, restorative and effortlessly elegant.', 'Do not stir the soup after adding tofu â€” silken tofu breaks apart easily and the clear broth is part of the beauty.', 'Traditional', NULL, ARRAY['400g winter melon, peeled, seeded and cubed','200g silken tofu, cubed','4 cups vegetable stock','2 cm ginger, sliced thin','1 tbsp light soy sauce','1 tsp sesame oil','Salt and white pepper to taste','Spring onion and coriander to garnish']::text[], ARRAY['Bring stock to a simmer with ginger slices.','Add winter melon; simmer 15 min until just translucent.','Gently slide in tofu; simmer 3 min.','Season with soy sauce, salt and white pepper.','Ladle into bowls; drizzle sesame oil and scatter spring onion and coriander.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 100, 5.2, 6.8, 2.1, 1.2, 1.8, 95, 0.15, 420, false),
  (166, 'Mushroom and Tofu Clay Pot', 'Chinese', 'asian', 'vegan', false, 'main', '2', '15 min', '25 min', 'A warming, fragrant clay pot of shiitake mushrooms and braised tofu in a dark, glossy soy and oyster sauce â€” the soul of Chinese home cooking.', 'A genuine clay pot retains heat beautifully but any heavy-bottomed pan works â€” the key is the slow simmer.', 'Traditional', NULL, ARRAY['300g firm tofu, cubed','200g mixed mushrooms (shiitake, oyster)','1 carrot, sliced','2 spring onions, cut','3 garlic cloves, minced','2 tbsp dark soy sauce','1 tbsp vegetarian oyster sauce','1 tbsp Shaoxing wine or dry sherry','1 tsp sugar','Sesame oil and white pepper']::text[], ARRAY['Fry tofu cubes in hot oil until golden; drain.','Saute garlic until fragrant; add mushrooms and carrot; fry 3 min.','Add soy sauce, oyster sauce, Shaoxing wine and sugar; stir.','Add tofu and 1/2 cup water; simmer 10 min until sauce thickens.','Add spring onion; drizzle sesame oil and season with white pepper; serve in the clay pot.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 230, 16.5, 18.2, 8.4, 3.1, 3.8, 185, 0.3, 685, false),
  (167, 'Tofu Pudding (Douhua)', 'Chinese', 'asian', 'vegan', true, 'dessert', '2', '5 min', '0 min', 'Silky-soft tofu pudding served warm with a fragrant ginger sugar syrup â€” Shanghai''s most gentle and beloved street snack.', 'Scoop douhua with a flat-edged spoon in a single sweeping motion to lift whole sheets without breaking them.', 'Traditional', NULL, ARRAY['400g fresh silken tofu (or douhua from Asian grocery)','For syrup: 3 tbsp sugar, 1 cup water, 2 cm ginger, smashed','Optional toppings: azuki beans, taro balls, peanuts']::text[], ARRAY['Simmer sugar, water and ginger until sugar dissolves; remove ginger.','Gently scoop douhua into bowls with a wide spoon â€” do not stir or it breaks.','Pour warm ginger syrup over.','Add toppings if using.','Serve immediately while warm.']::text[], ARRAY['snack']::text[], 'bowl', 200, 100, 5.2, 12.4, 1.8, 0.6, 1.2, 85, 0, 45, false),
  (168, 'Sesame Tang Yuan (Rice Balls)', 'Chinese', 'asian', 'veg', true, 'dessert', '2', '30 min', '15 min', 'Glutinous rice balls filled with a molten black sesame paste centre, served in a sweet ginger broth â€” the centrepiece of the Lantern Festival.', 'Chilling the sesame filling firms it so it can be wrapped cleanly â€” warm filling is too soft to handle.', 'Traditional', NULL, ARRAY['1 cup glutinous rice flour','3/4 cup warm water','Filling: 4 tbsp black sesame powder, 3 tbsp icing sugar, 3 tbsp butter or lard','For broth: 3 cups water, 3 tbsp sugar, 3 slices ginger']::text[], ARRAY['Mix sesame powder, icing sugar and butter until a stiff paste; refrigerate 15 min; roll into small balls.','Mix rice flour and water to a smooth, pliable dough.','Flatten a dough piece, place a sesame ball inside; seal and roll into a ball.','Simmer ginger broth; drop tang yuan in; cook until they float plus 2 min more.','Serve in ginger broth while hot.']::text[], ARRAY['snack']::text[], 'bowl', 150, 240, 4.2, 32.5, 8.3, 1.8, 2.1, 95, 0.08, 28, false),
  (169, 'Vegetable Spring Rolls', 'Chinese', 'asian', 'vegan', false, 'snack', '2', '20 min', '15 min', 'Thin, shatteringly crispy fried rolls stuffed with glass noodles, cabbage and carrot â€” the Chinese snack that travels the world.', 'Cooling the filling completely before wrapping is essential â€” hot filling creates steam that makes the wrapper soggy.', 'Traditional', NULL, ARRAY['8 spring roll wrappers (thin)','100g glass noodles, soaked and drained','1 cup napa cabbage, shredded','1 carrot, grated','2 tbsp soy sauce','1 tsp sesame oil','1 garlic clove, minced','Oil for deep frying','Sweet chilli sauce to serve']::text[], ARRAY['Stir-fry cabbage, carrot and garlic until softened; add noodles, soy and sesame oil; cool completely.','Place a spring roll wrapper on a flat surface at 45 degrees.','Spoon filling in a line across the lower third; fold bottom corner over filling.','Fold sides in and roll tightly to the top; seal with a paste of flour and water.','Deep fry at 180Â°C until golden and crisp, about 3-4 min; drain and serve.']::text[], ARRAY['snack']::text[], 'piece', 120, 220, 5.2, 28.4, 8.6, 1.8, 0.9, 42, 0, 485, false),
  (170, 'Peanut Sesame Noodles', 'Chinese', 'asian', 'vegan', false, 'main', '2', '10 min', '10 min', 'Cold wheat noodles tossed in a rich, nutty peanut and sesame sauce with cucumber and chilli â€” a satisfying Chinese snack any time of day.', 'A splash of warm water while whisking is the trick that transforms chunky peanut butter into a silky, pourable sauce.', 'Traditional', NULL, ARRAY['200g wheat noodles or spaghetti','3 tbsp peanut butter','2 tbsp soy sauce','1 tbsp sesame oil','1 tbsp rice vinegar','1 tsp sugar','1 tsp chilli flakes','1/2 cucumber, matchsticked','Spring onion and sesame seeds to garnish']::text[], ARRAY['Cook noodles per packet; drain and rinse under cold water; cool completely.','Whisk peanut butter, soy sauce, sesame oil, vinegar, sugar and chilli with a splash of warm water until smooth.','Toss cold noodles in the sauce.','Top with cucumber, spring onion and sesame seeds.','Serve cold or at room temperature.']::text[], ARRAY['snack']::text[], 'bowl', 250, 340, 12.5, 38.2, 16.8, 3.2, 2.1, 68, 0.1, 892, false),
  (171, 'Menemen (Turkish Scrambled Eggs with Peppers)', 'Middle Eastern', 'middle_eastern', 'egg', false, 'main', '2', '10 min', '15 min', 'A Turkish classic of eggs gently scrambled into a simmering sauce of tomatoes, peppers and spices — Istanbul in a pan.', 'The key to menemen is patience — stir slowly and remove from heat while still slightly underdone; carryover heat finishes it perfectly.', 'Traditional', NULL, ARRAY['4 eggs','2 medium tomatoes, roughly chopped','1 green pepper, diced','1 red pepper, diced','1 small onion, finely sliced','1/2 tsp red pepper flakes','1/2 tsp cumin','2 tbsp olive oil','Salt and black pepper','Fresh parsley to garnish','Crusty bread to serve']::text[], ARRAY['Heat olive oil; saute onion until soft, add peppers and cook 5 min.','Add tomatoes and spices; simmer 8 min until sauce thickens.','Beat eggs lightly and pour over the tomato mixture.','Stir gently and slowly until eggs are softly set — do not over-scramble.','Garnish with parsley; serve straight from the pan with crusty bread.']::text[], ARRAY['breakfast']::text[], 'plate', 250, 240, 12.5, 8.5, 18.2, 1.8, 2.1, 68, 0.68, 285, false),
  (172, 'Borek with Spinach and Feta', 'Middle Eastern', 'middle_eastern', 'egg', false, 'main', '3', '30 min', '35 min', 'Layers of flaky filo pastry encasing a salty, herbed spinach and feta filling — Turkey''s most beloved savoury pastry, straight from the oven.', 'Work with filo quickly and keep unused sheets covered with a damp cloth — it dries and tears within minutes of exposure.', 'Traditional', NULL, ARRAY['8 sheets filo pastry','300g fresh spinach, wilted and chopped','200g feta cheese, crumbled','2 eggs','1 onion, finely chopped','1/4 tsp nutmeg','3 tbsp olive oil and 2 tbsp butter, melted together','Sesame seeds to sprinkle','Salt and black pepper']::text[], ARRAY['Mix spinach with feta, one egg, onion, nutmeg and seasoning.','Brush a baking dish with butter; lay two sheets of filo, brushing each with butter mixture.','Spread half the filling; add two more buttered filo sheets; repeat layers.','Finish with two filo sheets, buttered on top; score into diamonds.','Beat remaining egg and brush over; scatter sesame seeds; bake at 190°C for 30-35 min until golden.']::text[], ARRAY['breakfast']::text[], 'piece', 150, 310, 12.5, 18.2, 18.8, 1.8, 2.1, 185, 0.5, 520, false),
  (173, 'Kaymak Toast with Honey and Walnuts', 'Middle Eastern', 'middle_eastern', 'veg', true, 'main', '2', '5 min', '0 min', 'Thick, clotted-cream-style kaymak spread on toasted bread and drizzled with dark floral honey and crushed walnuts — a Levantine luxury breakfast.', 'Source the best-quality honey you can find — this simple dish lives and dies by the quality of two ingredients.', 'Traditional', NULL, ARRAY['4 slices thick sourdough or simit bread, toasted','4 tbsp kaymak (or thick clotted cream)','3 tbsp dark honey (preferably pine or thyme honey)','3 tbsp walnuts, lightly crushed','Pinch of ground cinnamon','Fresh fruit to serve (optional)']::text[], ARRAY['Toast bread until golden.','Spread kaymak generously over each slice.','Drizzle honey liberally over the kaymak.','Scatter crushed walnuts and dust with cinnamon.','Serve immediately with fresh fruit and tea.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 320, 9.5, 32, 15.5, 2, 1.8, 85, 0.3, 285, false),
  (174, 'Freekeh Salad with Fresh Herbs', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'salad', '2', '10 min', '25 min', 'Nutty, smoky freekeh grain tossed with a confetti of fresh parsley, mint, tomato and a bright lemon dressing — the Levantine grain salad to know.', 'Cool the freekeh completely before adding the herbs — warm grain wilts them and dulls their bright colour.', 'Traditional', NULL, ARRAY['1 cup cracked freekeh','2 tomatoes, diced','1 cucumber, diced','1 bunch flat-leaf parsley, chopped','1/2 cup mint leaves, torn','3 spring onions, sliced','3 tbsp olive oil','Juice of 1.5 lemons','Salt and black pepper','Pomegranate seeds to garnish']::text[], ARRAY['Rinse freekeh; simmer in 2 cups water for 20 min until tender; drain and cool.','Combine parsley, mint, tomato, cucumber and spring onion in a large bowl.','Add cooled freekeh; toss gently.','Dress with olive oil, lemon juice, salt and pepper; toss again.','Garnish with pomegranate seeds and serve at room temperature.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 290, 9.2, 38.5, 12.8, 7.4, 2.1, 78, 0, 285, false),
  (175, 'Falafel and Hummus Wrap', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'main', '2', '20 min', '15 min', 'Crispy, herb-packed falafel in a warm flatbread with creamy hummus, fresh vegetables and tangy tahini — the street-food wrap that feeds the world.', 'The tahini sauce is the soul of the wrap — thin it with water and lemon until it pours like double cream.', 'Traditional', NULL, ARRAY['8 falafel (homemade or good quality ready-made)','2 flatbreads or pittas','4 tbsp hummus','1/2 cucumber, sliced','2 tomatoes, sliced','1/4 red onion, thinly sliced','Fresh parsley and mint','2 tbsp tahini sauce (tahini, lemon, water, garlic)','Pickled chillies (optional)']::text[], ARRAY['Fry or bake falafel until deeply golden and crispy.','Warm flatbreads directly on a gas flame or dry pan for 30 seconds.','Spread hummus generously on each flatbread.','Add cucumber, tomato, onion and herbs.','Place falafel on top; drizzle tahini sauce; roll tightly and serve.']::text[], ARRAY['lunch']::text[], 'serving', 250, 370, 12.5, 38, 12.8, 7.2, 3.1, 95, 0.05, 420, false),
  (176, 'Lentil Soup (Shorbat Adas)', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'soup', '3', '10 min', '30 min', 'A velvety, golden soup of red lentils perfumed with cumin and finished with a sizzle of lemon and olive oil — the staple of Levantine homes.', 'A squeeze of lemon just before serving is not optional — it brightens the whole soup and balances the earthiness of the lentils.', 'Traditional', NULL, ARRAY['1.5 cups red lentils, rinsed','1 large onion, diced','3 garlic cloves, minced','1.5 tsp ground cumin','1/2 tsp turmeric','5 cups vegetable stock','3 tbsp olive oil','Juice of 1 lemon','Salt and pepper','Toasted bread croutons and fresh parsley to garnish']::text[], ARRAY['Saute onion in olive oil until golden; add garlic and cumin, fry 1 min.','Add lentils, turmeric and stock; bring to a boil and simmer 20 min until lentils dissolve.','Blend until completely smooth; return to pan.','Adjust consistency and seasoning; add lemon juice.','Ladle into bowls; drizzle olive oil; garnish with parsley and croutons.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 220, 12.5, 28, 11.5, 5.5, 3.8, 45, 0, 480, false),
  (177, 'Koshari (Rice, Lentils and Crispy Onions)', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'main', '3', '15 min', '45 min', 'Egypt''s beloved street food — a triumphant pile of rice, lentils, pasta and crispy fried onions drenched in spiced tomato sauce.', 'The crispy onions are what make koshari extraordinary — fry them low and slow until caramel-dark, not just golden.', 'Traditional', NULL, ARRAY['1 cup rice','1/2 cup green lentils','1/2 cup macaroni or vermicelli','2 large onions, thinly sliced','For tomato sauce: 2 cups tomato puree, 4 garlic cloves, 1 tsp cumin, 1 tsp coriander, chilli','Oil for frying','Salt and vinegar']::text[], ARRAY['Cook lentils 20 min until just tender; cook rice separately; cook pasta separately.','Fry onion rings in oil until deeply golden and crisp; drain on paper.','Saute garlic for tomato sauce; add tomato puree, spices and a splash of vinegar; simmer 10 min.','Layer rice, then lentils, then pasta in a serving bowl.','Top with crispy onions and pour tomato sauce over; serve.']::text[], ARRAY['dinner']::text[], 'plate', 350, 420, 14.2, 62.5, 8.3, 5.8, 3.2, 45, 0, 380, false),
  (178, 'Vegetarian Moussaka', 'Middle Eastern', 'middle_eastern', 'egg', false, 'main', '4', '20 min', '50 min', 'Layers of roasted aubergine, spiced lentils and a thick bechamel crust — the Greek and Levantine classic in its most satisfying vegetarian form.', 'Resting the moussaka before cutting is essential — it firms up and holds its layers when sliced.', 'Traditional', NULL, ARRAY['2 large aubergines, sliced','1 cup green lentils, cooked','1 onion, 3 garlic cloves, 2 tomatoes','1 tsp cinnamon, 1 tsp allspice, 1 tsp cumin','For bechamel: 3 tbsp butter, 3 tbsp flour, 2 cups milk, nutmeg, 1 egg yolk','Olive oil, salt and pepper']::text[], ARRAY['Brush aubergine slices with oil; roast at 200°C for 20 min until golden.','Saute onion and garlic; add tomatoes and spices; stir in cooked lentils and simmer 10 min.','Make bechamel: melt butter, stir in flour, whisk in hot milk until thick; season with nutmeg; stir in egg yolk.','Layer in a baking dish: lentil mixture, aubergine slices, bechamel on top.','Bake at 180°C for 30 min until bechamel is golden and set; rest 10 min before cutting.']::text[], ARRAY['dinner']::text[], 'plate', 300, 310, 14.2, 28.5, 11.8, 6.2, 3.4, 185, 0.25, 420, false),
  (179, 'Stuffed Peppers (Dolma)', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'main', '2', '20 min', '40 min', 'Vibrant bell peppers filled with herbed rice, pine nuts and currants, baked until tender — a jewel of the Levantine table.', 'Parboiling the rice just halfway before stuffing ensures it finishes cooking perfectly inside the pepper without being crunchy.', 'Traditional', NULL, ARRAY['4 medium bell peppers','1 cup long-grain rice, parboiled','1 onion, finely diced','3 tbsp pine nuts','3 tbsp currants or raisins','1 tsp allspice, 1 tsp cinnamon','2 tbsp flat-leaf parsley and mint, chopped','Olive oil, salt, pepper','1 cup tomato juice for baking']::text[], ARRAY['Fry onion in olive oil until soft; add pine nuts and fry until golden.','Mix with parboiled rice, currants, herbs and spices; season well.','Slice tops off peppers; remove seeds; fill each one firmly with rice mixture.','Place in a baking dish; pour tomato juice around; drizzle olive oil.','Cover with foil; bake at 180°C for 35 min; uncover last 5 min to colour tops.']::text[], ARRAY['dinner']::text[], 'piece', 300, 280, 8.5, 42, 8.5, 4.2, 2.1, 35, 0, 385, false),
  (180, 'Couscous with Seven Vegetables', 'Middle Eastern', 'middle_eastern', 'veg', false, 'main', '3', '15 min', '30 min', 'A Moroccan-inspired mound of steamed couscous crowned with sweet, saffron-spiced vegetables — a feast dish in spirit and in practice.', 'A generous knob of butter stirred into the couscous as it steams gives it the fluffiness that distinguishes a great dish from a flat one.', 'Traditional', NULL, ARRAY['2 cups instant couscous','1 tbsp butter','2 carrots, chunked','2 courgettes, chunked','1 cup pumpkin, cubed','1 cup chickpeas, cooked','1 onion, wedged','1 tsp saffron in warm water','1 tsp ras el hanout','1 cinnamon stick','Salt and olive oil']::text[], ARRAY['Saute onion in oil; add spices and saffron water; cook 1 min.','Add carrots, pumpkin and 2 cups water; simmer 10 min.','Add courgettes and chickpeas; simmer 8 min more.','Pour boiling stock over couscous with butter and salt; cover and rest 5 min; fluff with a fork.','Mound couscous in a serving dish; crown with vegetables and broth.']::text[], ARRAY['dinner']::text[], 'plate', 350, 350, 12.5, 52, 8.5, 8.2, 3.8, 65, 0.08, 385, false),
  (181, 'Kibbeh Nayeh (Bulgur and Herb Croquette)', 'Middle Eastern', 'middle_eastern', 'vegan', false, 'snack', '2', '20 min', '15 min', 'Crispy bulgur wheat croquettes packed with herbs and warming spices — the vegetarian version of one of the Levant''s oldest dishes.', 'Fine bulgur is essential — coarse bulgur will not bind properly and the croquettes will fall apart in the pan.', 'Traditional', NULL, ARRAY['1 cup fine bulgur wheat, soaked and drained','1 small onion, very finely grated','1 tsp allspice','1/2 tsp cinnamon','1/2 tsp black pepper','Salt to taste','2 tbsp pine nuts','1/4 cup fresh parsley, minced','Oil for shallow frying']::text[], ARRAY['Mix soaked, drained bulgur with grated onion, spices, salt and parsley until it holds together.','Taste the raw mix — adjust seasoning now.','Shape into small oval patties; press a pine nut into the centre of each.','Shallow-fry in hot oil 3 min each side until golden crust forms.','Drain; serve with yoghurt, mint and a squeeze of lemon.']::text[], ARRAY['snack']::text[], 'piece', 150, 200, 7.2, 22.5, 8.3, 4.8, 1.9, 42, 0, 185, false),
  (182, 'Hoppers (Appa) with Coconut Sambol', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '8 hrs', '20 min', 'Bowl-shaped fermented rice crepes with crispy lacey edges and a soft centre, served with a fiery, tangy coconut sambol.', 'The fermentation is the soul of a good hopper — a 6-hour batter produces a mildly sour, airy crepe with perfect edge crispiness.', 'Traditional', NULL, ARRAY['1 cup rice flour','1/4 cup coconut milk','1/2 cup water','1/2 tsp instant yeast','1/2 tsp sugar','Salt to taste','For sambol: 1 cup fresh coconut grated, 2 red chillies, 1/2 onion, lime juice, salt']::text[], ARRAY['Mix rice flour, coconut milk, water, yeast and sugar; ferment 6-8 hrs until bubbly and slightly sour.','Prepare sambol: blend coconut with chilli and onion coarsely; add lime juice and salt; toss.','Heat a hopper pan (or small wok); grease lightly; pour a ladle of batter and swirl to coat sides.','Cover and cook 2-3 min until edges are golden and crisp; centre should remain soft.','Serve hoppers immediately with coconut sambol.']::text[], ARRAY['breakfast']::text[], 'serving', 150, 280, 4.2, 48.5, 8.3, 2.1, 1.8, 52, 0.1, 380, false)
